private fun DetectionCandidate.isTactileDetection(): Boolean {
    return className.lowercase(Locale.US).contains("tactile") || className.contains("점자")
}

private fun CameraFrameQualityReason.isTransientPreflightQualityFailure(): Boolean = when (this) {
    CameraFrameQualityReason.BRIGHTNESS_OUTSIDE_APPROVED_RANGE,
    CameraFrameQualityReason.OCCLUSION_OUTSIDE_APPROVED_RANGE,
    CameraFrameQualityReason.MOUNT_ANGLE_OUTSIDE_APPROVED_RANGE,
    CameraFrameQualityReason.MOUNT_ANGLE_NEAR_BOUNDARY,
    -> true
    else -> false
}

internal fun shouldPermanentlyLimitOneShotSpeechRecognition(error: Int): Boolean =
    error == SpeechRecognizer.ERROR_LANGUAGE_NOT_SUPPORTED

internal fun userReportAuthorityExpiryDelayMs(
    accessExpiresAtEpochMs: Long,
    idleExpiresAtEpochMs: Long,
    absoluteExpiresAtEpochMs: Long,
    nowEpochMs: Long,
): Long = UserReportInteractionOwner.userReportAuthorityExpiryDelayMs(
    accessExpiresAtEpochMs, idleExpiresAtEpochMs, absoluteExpiresAtEpochMs, nowEpochMs,
)






/**
 * Android runtime composition root.
 *
 * The GL thread owns each ARCore Frame and depth acquisition. ARCore results enter the metric
 * pipeline only through its device gate. CameraX fallback detections stay in a separate non-metric
 * advisory policy and can never become route or report evidence.
 */
open class MainActivity @JvmOverloads constructor(
    safetyThresholdProfile: ApprovedWalkRuntimeSafetyThresholdProfile? =
        WalkRuntimeSafetyCoordinator.productionThresholdProfile,
) : Activity(), GLSurfaceView.Renderer {
    private lateinit var surfaceView: GLSurfaceView
    private lateinit var cameraFallbackPreviewView: PreviewView
    private var accountSignupExpanded: Boolean
        get() = accountAccessPresenter.accountSignupExpanded
        set(value) { accountAccessPresenter.accountSignupExpanded = value }

    private var accountSignupStep: AccountSignupStep
        get() = accountAccessPresenter.accountSignupStep
        set(value) { accountAccessPresenter.accountSignupStep = value }

    private var accountConsentDisclosureExpanded: Boolean
        get() = accountAccessPresenter.accountConsentDisclosureExpanded
        set(value) { accountAccessPresenter.accountConsentDisclosureExpanded = value }

    private var accountInputErrorActive: Boolean
        get() = accountAccessPresenter.accountInputErrorActive
        set(value) { accountAccessPresenter.accountInputErrorActive = value }

    private var accountAccessNotice: String?
        get() = accountAccessPresenter.accountAccessNotice
        set(value) { accountAccessPresenter.accountAccessNotice = value }

    private var passwordLoginFailureNotice: String?
        get() = accountAccessPresenter.passwordLoginFailureNotice
        set(value) { accountAccessPresenter.passwordLoginFailureNotice = value }

    private val accountAccessPresenter by lazy(LazyThreadSafetyMode.NONE) {
        AccountAccessPresenter(
            style = viewStyle,
            actions = AccountAccessPresenter.Actions(
                isRequestBusy = { emailAccountController.isRequestInFlight() },
                isGatewayRequestInFlight = {
                    GatewaySessionProcessCoordinator.snapshot().inFlightOperationId != null
                },
                refreshActionAvailability = ::refreshAccountActionAvailability,
                refreshAccessUi = {
                    updateEmailAccountAccessUi(firstRunOnboardingSnapshot)
                },
                showAccountMessage = ::showAccountMessage,
            ),
        )
    }

    private val nativeRegistrationComposition: NativeRegistrationScreenComposition by lazy(LazyThreadSafetyMode.NONE) {
        NativeRegistrationScreenComposition(this, viewStyle, nativeUiPublication) { accountAccessPresenter }
    }
    private val firstRunOnboardingPresenter get() = nativeRegistrationComposition.firstRunPresenter()
    private val accountConsentCards = linkedMapOf<String, LinearLayout>()
    private val accountConsentClauseTexts = linkedMapOf<String, TextView>()
    private val accountConsentListenButtons = linkedMapOf<String, Button>()
    private val accountAccessInteractionOwner: AccountAccessInteractionOwner by lazy(LazyThreadSafetyMode.NONE) { createAccountAccessInteractionOwner() }
    private val accountConsentSpeechOwner: AccountConsentSpeechOwner by lazy(LazyThreadSafetyMode.NONE) { createAccountConsentSpeechOwner() }

    private fun resetAccountConsentSpeechContextAfterBinding() {
        accountConsentSpeechOwner.resetCompletedContextAfterBinding()
    }
    private val firstRunIntegratedConsentButtons =
        mutableMapOf<IntegratedConsentItem, Button>()
    private var walkReadinessExpanded: Boolean
        get() = walkReadinessPresentationController.expanded
        set(value) { walkReadinessPresentationController.expanded = value }
    private val viewStyle by lazy(LazyThreadSafetyMode.NONE) { WalkSafeViewStyle(this) }
    private val nativeScreenPresenter by lazy(LazyThreadSafetyMode.NONE) { NativeScreenPresenter(viewStyle) }
    private val nativePagePresentationController by lazy(LazyThreadSafetyMode.NONE) {
        NativePagePresentationController(
            workflow = { nativeWorkflowController }, screen = { nativeScreenPresenter },
            queries = object : NativePagePresentationController.Queries {
                override fun destinationConfirmationMessage() = nativeDestinationConfirmationMessage()
                override fun currentGuidancePresentation() = currentNativeGuidancePresentation()
                override fun walkingCalibrationStatusMessage() = this@MainActivity.walkingCalibrationStatusMessage()
                override fun destinationStartAvailable() = nativeFeatureAvailable(NativeUiPage.DESTINATION_CONFIRM)
                override fun runtimeActive() = isWalkSessionRuntimeActive()
                override fun activityForeground() = isActivityForeground
            },
            phases = object : NativePagePresentationController.Phases {
                override fun renderGuidanceStatus(presentation: DestinationGuidancePresentation, measurements: String) { updateNativeGuidanceStatus(presentation, measurements) }
                override fun renderPreview(frame: NativeScreenPresenter.FrameFacts) { applyNativePreviewPresentation(frame.homeAvailable, frame.homeVisible, frame.settingsVisible, frame.forceSettings) }
                override fun renderVoiceFirst(homeAvailable: Boolean) { applyNativeVoiceFirstPresentation(homeAvailable) }
                override fun updatePaneTitle(homeAvailable: Boolean, settingsVisible: Boolean) { updateNativeAccessibilityPaneTitle(homeAvailable, settingsVisible) }
                override fun updateHomeGeometry() { updateNativeHomeGeometry() }
                override fun clearSearchFocusAndHideKeyboard() { nativeScreenPresenter.clearSearchFocusAndHideKeyboard(this@MainActivity) }
                override fun renderMainUi() { this@MainActivity.renderMainUi() }
                override fun selectFocusTarget(page: NativeUiPage): NativeWorkflowController.FocusTarget? = nativeScreenPresenter.pageFocusTarget(page, { nativeHomeUiPresenter }, { settingsPrivacyPresenter })
            },
        )
    }
    private val nativeUiPublication = NativeUiPublication()
    private val nativeHomeUiPresenter = NativeHomeUiPresenter()
    private val nativeWorkflowController: NativeWorkflowController by lazy(LazyThreadSafetyMode.NONE) {
        NativeWorkflowController(
            queries = object : NativeWorkflowController.EntryQueries {
                override fun shouldShowNativeHome(): Boolean = this@MainActivity.shouldShowNativeHome()
                override fun nativeHomeFeatureContextAvailable(): Boolean = this@MainActivity.nativeHomeFeatureContextAvailable()
                override fun isWalkSessionRuntimeActive(): Boolean = this@MainActivity.isWalkSessionRuntimeActive()
                override fun walkingArea() = isInWalkInteractionArea()
                override fun nativeFeatureAvailable(page: NativeUiPage): Boolean = this@MainActivity.nativeFeatureAvailable(page)
                override fun deletionRecoveryRequired(): Boolean = this@MainActivity.accountDeletionRecoveryLoginRequired() || GatewaySessionProcessCoordinator.snapshot().deletionRecoveryOnly
                override fun deletionProcessingBlocked(): Boolean = this@MainActivity.accountDeletionStateMachine.processingBlocked()
            },
            pages = object : NativeWorkflowController.PageUi {
                override fun invalidatePagePresentationOwner() {
                    this@MainActivity.statusPresentationOwner = Any()
                    this@MainActivity.userReportInteractionOwner.invalidateLocalQuarantineSelection()
                }
                override fun invalidateGuidanceStopConfirmation() { this@MainActivity.invalidateGuidanceStopConfirmation() }
                override fun cancelDeviceRuntimeCalibration() { this@MainActivity.cancelDeviceRuntimeCalibration("page_changed") }
                override fun retireForegroundWake(preserveVoiceInteraction: Boolean) { if (!preserveVoiceInteraction) this@MainActivity.cancelForegroundHomeWakeAcknowledgement(); this@MainActivity.cancelForegroundHomeWakeListening(resetFailure = true) }
                override fun clearPageVoiceDialog() { this@MainActivity.clearHomeDestinationVoiceDialog(VoiceDialogDiagnosticReason.PAGE_CHANGED) }
                override fun retireOutgoingVoiceInteraction(wasVoicePage: Boolean) {
                    if (nativeUiPage == NativeUiPage.GUIDANCE && arrivalEndingOwner?.isCurrent() == true) {
                        routeGuidanceController.retireArrivalForExit()
                    }
                    if (wasVoicePage) {
                        this@MainActivity.stopHandsFreeVoiceService()
                        this@MainActivity.cancelVoiceCommandRecognition()
                    } else this@MainActivity.cancelCommandSpeechResponse()
                }
                override fun displayPage(page: NativeUiPage): NativeWorkflowController.FocusTarget? {
                    this@MainActivity.privacySectionExpanded = page == NativeUiPage.SETTINGS
                    return this@MainActivity.nativePagePresentationController.displayPage(page)
                }
                override fun updateLiveVisibility() { this@MainActivity.updateRuntimeDebugControlsVisibility(); this@MainActivity.updateLiveCameraScreenVisibility() }
                override fun readyForNativeRendering(): Boolean = this@MainActivity.firstRunOnboardingController.initialized && this@MainActivity.nativeUiPublication.isPublished(NativeUiPublication.Target.HOME_CARD_GRID) && this@MainActivity.nativeUiPublication.isPublished(NativeUiPublication.Target.NATIVE_VOICE_CONTROLS) && this@MainActivity.nativeUiPublication.isPublished(NativeUiPublication.Target.PRIVACY_CONTROLS)
                override fun renderFrame(frame: NativeScreenPresenter.FrameFacts) {
                    this@MainActivity.nativePagePresentationController.renderFrame(frame)
                }
                override fun showHomeLockNotice() { this@MainActivity.showHomeCardLockNotice("앱 내의 기능 사용 제한", "기기 장착 상태와 기기 상태를 확인해주세요.") }
                override fun resetSearchInput() { this@MainActivity.nativeScreenPresenter.searchBinding().destinationQueryInput.text?.clear(); this@MainActivity.nativeScreenPresenter.searchBinding().destinationQueryInput.clearFocus(); this@MainActivity.nativeScreenPresenter.searchBinding().destinationMoreButton.isEnabled = false; this@MainActivity.nativeScreenPresenter.searchBinding().destinationMoreButton.visibility = View.GONE; this@MainActivity.updateDestinationSearchUi() }
                override fun listenForVoiceCommand() { this@MainActivity.ensureVoicePermissionThenListen() }
                override fun postVoiceStart(isCurrent: () -> Boolean) { this@MainActivity.nativeScreenPresenter.voiceBinding().voiceReportButton.post { if (isCurrent()) this@MainActivity.nativeScreenPresenter.voiceBinding().voiceReportButton.performClick() } }
                override fun releaseCommandPageOwnership() { this@MainActivity.voiceInputController.releaseCommandPageOwnership() }
                override fun clearDestinationFocus() { this@MainActivity.nativeScreenPresenter.searchBinding().destinationQueryInput.clearFocus() }
                override fun updateNavigationStatus(message: String) { this@MainActivity.updateNavigationStatus(message) }
            },
            preparation = object : NativeWorkflowController.PreparationActions {
                override fun beginNativeWalkFromHome(): Boolean = this@MainActivity.beginNativeWalkFromHome()
                override fun continueNativeFeaturePreparation() { this@MainActivity.nativePrewalkController.continueFeaturePreparation() }
                override fun cancelNativePrewalkPreparation(cancelFeatureEntry: Boolean) { this@MainActivity.cancelNativePrewalkPreparation(cancelFeatureEntry) }
                override fun refreshForegroundHomeWakeListening() { this@MainActivity.refreshForegroundHomeWakeListening() }
                override fun hasPreparationDialog(): Boolean = this@MainActivity.nativePrewalkDialog != null
            },
            destinations = object : NativeWorkflowController.DestinationTransactions {
                override fun captureNativeDestinationStartOwner(destination: DestinationSearchResult): (() -> Boolean)? = this@MainActivity.captureNativeDestinationStartOwner(destination)
                override fun currentDestinationSearchAllowsWork(): Boolean = this@MainActivity.currentDestinationSearchAllowsWork()
                override fun blockRouteMutationWhileDeviationChoicePending(): Boolean = this@MainActivity.blockRouteMutationWhileDeviationChoicePending()
                override fun explainNavigationFeatureUnavailable() { this@MainActivity.explainNavigationFeatureUnavailable() }
                override fun clearPendingExplicitRouteStart() { this@MainActivity.clearPendingExplicitRouteStart() }
                override fun cancelDestinationSearchLocation() { this@MainActivity.cancelDestinationSearchLocation() }
                override fun requestDestinationSearchLocation() { this@MainActivity.requestDestinationSearchLocation() }
                override fun cancelSearchRequestsAndResetEntry() { this@MainActivity.navigationRequests.cancelDestinationSearch(); this@MainActivity.destinationSearchController.resetForSearchEntry() }
                override fun needsGuidancePreparationSpeech(): Boolean = this@MainActivity.pendingGuidancePreparationSpeech?.isCurrent?.invoke() != true && !this@MainActivity.routeNavigator.hasRoute()
                override fun ownsExplicitLocationWait(destination: DestinationSearchResult): Boolean { val explicit = this@MainActivity.routeAcquisitionController.explicitStart; return explicit != null && explicit.context == this@MainActivity.ownedExplicitRouteStartContextOrNull(destination.point, destination.coordinateEvidence) }
                override fun postNativeDestinationStart(destination: DestinationSearchResult) { this@MainActivity.postNativeDestinationStart(destination) }
            },
        )
    }

