            }
            override fun drawBackground(frame: Frame) = backgroundRenderer.draw(frame, cameraTextureId)
        }, frameRecognition, object : ArFrameClock {
            override fun elapsedRealtimeMs() = SystemClock.elapsedRealtime()
            override fun wallClockMs() = System.currentTimeMillis()
        }, object : ArFrameRenderObserver<ArSessionLease, ArSessionPurpose> {
            override fun onRenderCallback() { fieldDiagnosticRecording.onRenderCallback() }
            override fun geometryChanged(lease: ArSessionLease, frameGeneration: Int, epoch: WalkRuntimeEpoch) {
                resetVisualTrackingState()
                updateDisplayGeometryIfReady()
                runOnUiThread {
                    if (isArSessionLeaseCurrent(lease) && isCurrentFrameGeneration(frameGeneration, epoch)) debugBboxOverlay.clear()
                }
            }
            override fun updateFailed(status: String, detail: String, purpose: ArSessionPurpose,
                arGeneration: Long, epoch: WalkRuntimeEpoch, diagnosticKind: String, error: Throwable) {
                if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeDepthCheck",
                    "event=AR_UPDATE_FAILED kind=$diagnosticKind exception=${error.javaClass.simpleName}")
                this@MainActivity.runtimeMetricSession.handleRuntimeMetricFrameFailure(status, detail, purpose, arGeneration, epoch)
            }
            override fun diagnoseRuntimeCapture(capture: ScopedArFrameCapture<ArSessionLease, ArSessionPurpose>) {
                val arLease = capture.resources.originalLease
                val frame = capture.frame
                val elapsedRealtimeMs = capture.capturedElapsedMs
                val recognitionFrame = capture.recognition
                val snapshot = capture.snapshot
                val provider = capture.resources.provider
                val runtimeAcquisitionFailure = capture.acquisitionFailure
        if (BuildConfig.DEBUG && arLease.purpose == ArSessionPurpose.RUNTIME &&
            elapsedRealtimeMs - runtimeMetricFrameDiagnosticAtMs >= 1_000L) {
            runtimeMetricSession.noteFrameDiagnostic(elapsedRealtimeMs)
            val cpuTimestampNs = recognitionFrame?.input?.cameraTimestampNs
            android.util.Log.d("WalkSafeDepthCheck",
                "event=RUNTIME_METRIC_FRAME phase=${if (runtimeMetricActivationSession == null) "ACTIVE" else "QUALIFYING"} " +
                    "tracking=${frame.camera.trackingState.name} tracking_reason=${frame.camera.trackingFailureReason.name} " +
                    "input=${recognitionFrame?.input != null} cpu=${cpuTimestampNs != null} " +
                    "source_match=${runtimeRecognitionMatchesDepth(cpuTimestampNs, frame.timestamp, snapshot)} " +
                    "raw_pair=${snapshot.hasMetricRawDepth} raw_fresh=${snapshot.hasFreshMetricRawDepth} " +
                    "full_fresh=${snapshot.hasFreshFullDepth} samples=${runtimeRecognitionMetricSampleCount(cpuTimestampNs, frame.timestamp, snapshot)} " +
                    "failure=${runtimeAcquisitionFailure?.name ?: "NONE"} acquisition=${provider.runtimeAcquisitionDiagnostics()} " +
                    snapshot.metricPixelDiagnostics())
        }
            }
            override fun processPreflight(capture: ScopedArFrameCapture<ArSessionLease, ArSessionPurpose>) {
                handleRuntimeMetricPreflightFrame(capture.frame, capture.snapshot, capture.capturedElapsedMs,
                    capture.resources.generation, capture.frameWalkEpoch)
            }
        })
    }

