            override fun visualOutputAllowsWork(lease: ArSessionLease, frameTimestampNs: Long, tracking: Boolean) =
                currentRuntimeVisualDepthProcessingAllowsWork(lease, frameTimestampNs, tracking)
            override fun expectedCameraFps(lease: ArSessionLease) = lease.session.cameraConfig.fpsRange.lower
            override fun observeRuntimeFrame(expectedFps: Int, tracking: () -> Boolean) {
                runtimeCameraFrameBudgetMs = expectedFps.takeIf { it > 0 }?.let { kotlin.math.ceil(1000.0 / it).toLong() }
                runtimeLoadFrameScope = RuntimeFeatureScope.CAMERA_TRACKING_METRIC_DEPTH
                runtimeLoadNormalFrameAtMs = if (runtimeMetricOutputAllowed && tracking()) SystemClock.elapsedRealtime() else null
                observeRuntimeInferenceLoad(inputObserved = true)
            }
            override fun recordTrackingLoad(snapshot: DepthFrameSnapshot, frameTimestampNs: () -> Long,
                depthProcessingMs: Long, trackingStartedMs: Long, hasGray: Boolean, trackingBudgetNs: () -> Long) {
                runtimeLoadObservationSource.recordFrame(snapshot.cameraImageTimestampNs ?: frameTimestampNs(),
                    SystemClock.elapsedRealtime(), depthProcessingMs,
                    if (hasGray) SystemClock.elapsedRealtime() - trackingStartedMs else null,
                    kotlin.math.ceil(trackingBudgetNs() / 1_000_000.0).toLong(), runtimeLoadEnvironmentKey())
            }
            override fun requestEarlyDetection(atElapsedRealtimeMs: Long) { primaryDetectorOwner.requestEarlyWork(atElapsedRealtimeMs) }
        }
        val tactile = frameTactileResults
        val risk = frameRiskOutputs
        val recording = object : FrameRecordingPeer {
            override fun acquisitionFailures(provider: ArCoreFrameProvider, capturedElapsedMs: Long) = recordDepthAcquisitionFailuresIfDue(provider, capturedElapsedMs)
            override fun buildCaptureEntry(audit: FrameCaptureAudit) = buildCaptureLogEntry(audit.timestampMs, audit.wallClockMs,
                audit.snapshot, audit.overlay, audit.depthDetections, audit.depth, audit.bestOutput, audit.transformPath, audit.fallbackReason)
            override fun appendMetadata(entry: MetadataCaptureLogEntry) = fieldDiagnosticRecording.appendMetadata(entry)
            override fun enqueueMetadataIfOriginalUploadAllowed(entry: MetadataCaptureLogEntry) {
                runIfActivityOriginalUploadAllowed { if (metadataLogUploader.isEnabled()) metadataLogUploader.enqueue(entry) }
            }
            override fun freshLocation() = freshTrustedLocationOrNull()
            override fun frameProduced() = fieldDiagnosticRecording.onFrameProduced()
            override fun appendTelemetry(entry: MetadataCaptureLogEntry, alertsAllowed: Boolean, reportsAllowed: Boolean,
                freshLocation: TrustedLocation?, locationAgeMs: Long?) {
                fieldSessionLog.appendTelemetry(entry, FieldRuntimeSnapshot(latestStepCount, stepLengthEstimator.stepLengthM,
                    isRouteActive, latestNavigationState, alertsAllowed, reportsAllowed, latestReportCandidateStatus,
                    freshLocation != null, freshLocation?.accuracyM, locationAgeMs, latestHeadingDeg))
            }
        }
        val report = FrameReportPublicationPeer { data ->
            publishCurrentFrameReportState(frameGeneration = data.generation,
                expectedRuntimeMetricGeneration = data.arGeneration,
                automaticReportOutput = data.automaticOutput, reportGateState = data.automaticGate,
                explicitReportOutput = data.explicitOutput, explicitReportGateState = data.explicitGate,
                explicitReportDamageWithoutDepth = data.damageWithoutDepth,
                explicitReportConflictingState = data.conflictingDamage,
                reportImage = data.sourceSnapshot.reportImage, nowMs = data.wallClockMs,
                capturedAtMs = data.sourceSnapshot.capturedAtMs ?: data.wallClockMs,
                expectedWalkEpoch = data.epoch, frozenReportCapture = data.frozenCapture,
                reportCaptureFacts = data.sourceSnapshot.reportCaptureFacts)
        }
        val clock = object : ArFrameClock {
            override fun elapsedRealtimeMs() = SystemClock.elapsedRealtime()
            override fun wallClockMs() = System.currentTimeMillis()
        }
        val publication = FramePublicationController(frameStateLock, runtime::ownsFrame, runtime::metricOutputAllowsWork,
            runtime::visualOutputAllowsWork, tactile, risk, recording, report, { framePresentation }, clock)
        FramePipelineController(frameStateLock, frameRenderController, runtime,
            object : FrameDetectionSchedulingPeer<ArSessionLease> {
                override fun scheduleUnknown(input: RuntimeRecognitionInput?, frame: Frame, snapshot: DepthFrameSnapshot,
                    capturedElapsedMs: Long, generation: Int, epoch: WalkRuntimeEpoch, lease: ArSessionLease) =
                    scheduleUnknownDetectionIfDue(input, frame, snapshot, capturedElapsedMs, generation, epoch, lease)
                override fun scheduleNamed(input: RuntimeRecognitionInput?, lease: ArSessionLease, frame: Frame,
                    timestampMs: Long, wallClockMs: Long, capturedElapsedMs: Long, snapshot: DepthFrameSnapshot,
                    generation: Int, epoch: WalkRuntimeEpoch, arGeneration: Long, gray: GrayTrackingFrame?) =
                    scheduleDetectionIfDue(input, lease, frame, timestampMs, wallClockMs, capturedElapsedMs, snapshot,
                        generation, epoch, arGeneration, gray?.key)
            }, frameSynthesisOwner, frameGeometry, frameRouteEvidence, tactile, risk, recording, { framePresentation }, publication, { it.statusTextForNoDetection() }, clock)
    }
    private val framePresentation: FramePresentationController<ArSessionLease> by lazy {
        FramePresentationController(frameStateLock, object : FramePresentationSource<ArSessionLease> {
            override fun ownsFrame(frameGeneration: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(frameGeneration, epoch)
            override fun ownsLease(lease: ArSessionLease) = isArSessionLeaseCurrent(lease)
            override fun metricAllowsWork(arGeneration: Long) = currentRuntimeMetricOutputAllowsWork(arGeneration)
            override fun visualDepthAllowsWork(lease: ArSessionLease, frameTimestampNs: Long, tracking: Boolean) =
                currentRuntimeVisualDepthProcessingAllowsWork(lease, frameTimestampNs, tracking)
        }, object : FramePresentationContext {
            override val cameraVisible get() = cameraScreenVisible
            override val surfaceWidth get() = this@MainActivity.surfaceWidth
            override val surfaceHeight get() = this@MainActivity.surfaceHeight
            override val statusOwner get() = statusPresentationOwner
            override fun captureStatusContext() = FrameStatusUiContext(reporterUserId, gatewaySessionGeneration,
                nativeUiPage, cameraScreenVisible, this@MainActivity.surfaceWidth, this@MainActivity.surfaceHeight,
                synchronized(frameStateLock) { visualGeometryVersion })
            override fun isStatusContextCurrent(context: FrameStatusUiContext) = reporterUserId == context.actorId &&
                gatewaySessionGeneration == context.accountGeneration && nativeUiPage == context.page &&
                cameraScreenVisible == context.cameraVisible && this@MainActivity.surfaceWidth == context.viewportWidth &&
                this@MainActivity.surfaceHeight == context.viewportHeight
            override fun geometryVersion() = visualGeometryVersion
        }, object : FramePresentationView {
            override val overlayWidth get() = debugBboxOverlay.width
            override val overlayHeight get() = debugBboxOverlay.height
            override var cameraStatus: String
                get() = cameraScreenStatus.text.toString()
                set(value) { cameraScreenStatus.text = value }
            override val statusLabel get() = statusText.text.toString()
            override val detailText get() = this@MainActivity.detailText.text.toString()
            override val statusDescription get() = statusText.contentDescription?.toString()
            override fun updateStatus(status: String, detail: String) = this@MainActivity.updateStatus(status, detail)
            override fun clearOverlay() = debugBboxOverlay.clear()
            override fun updateMapped(boxes: List<FrameMappedDebugBox>, sourceFrameId: Long, sourceCapturedAt: Long) =
                debugBboxOverlay.updateMapped(boxes, sourceFrameId, sourceCapturedAt, sourceComplete = true, animate = false)
            override fun onUi(action: () -> Unit) = runOnUiThread(action)
            override fun postOverlay(delayMs: Long, action: () -> Unit) { debugBboxOverlay.postDelayed({ action() }, delayMs) }
            override fun postCameraStatus(delayMs: Long, action: () -> Unit) { cameraScreenStatus.postDelayed({ action() }, delayMs) }
            override fun postStatus(delayMs: Long, action: () -> Unit) { statusText.postDelayed({ action() }, delayMs) }
            override fun updateDebugUploadButton() = this@MainActivity.updateDebugUploadButton()
        }, object : FramePresentationDiagnostics {
            override fun depthSupported() = this@MainActivity.depthSupported
            override fun noDetectionStatus(snapshot: DepthFrameSnapshot) = snapshot.statusTextForNoDetection()
            override fun statusParts(gateText: String) = FrameStatusDiagnosticParts(
                "$gateText · $latestTactileRouteState · ${feedbackActuatorStatusText()} · $latestReportCandidateStatus · steps=$latestStepCount stepLength=${meters(stepLengthEstimator.stepLengthM)}",
                currentUserMotionStatusText(), adaptiveInferencePacingStatusText(), latestVisualTrackingStatus,
                primaryDetectorLifecycleController.metadata().statusText, unknownRuntimeStatus, metadataLogUploader.statusText(), fieldDiagnosticRecording.metadataSummaryText())
            override fun gapParts() = FrameGapDiagnosticParts(latestVisualTrackingStatus, unknownRuntimeStatus)
        }, SystemClock::elapsedRealtime, OVERLAY_UPDATE_INTERVAL_MS, UI_UPDATE_INTERVAL_MS,
            MAX_OVERLAY_DETECTION_SOURCE_AGE_MS, MAX_OVERLAY_DETECTION_FRAME_DELTA_MS)
    }

