    // Construction captures ports only; no engine or timer starts during Activity initialization.
    private val speechOutputController = createSpeechOutputController()

    private fun createSpeechOutputController(): SpeechOutputController = SpeechOutputController(
        reader = object : SpeechOutputReader {
            override fun lifetime() = SpeechOutputLifetime(feedbackLifecycleGeneration, isActivityForeground)
            override fun commandContext(): CommandSpeechContext {
                val page = nativeUiPage
                return CommandSpeechContext(voiceRecognitionGeneration, reporterUserId,
                    GatewaySessionProcessCoordinator.snapshot().generation,
                    if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.snapshot().epoch else null,
                    page, page.isVoiceInteractionPage(),
                    nativeUiPublication.isPublished(NativeUiPublication.Target.GATEWAY_VOICE_STATUS_TEXT) && page in setOf(NativeUiPage.DESTINATION_SEARCH,
                        NativeUiPage.DESTINATION_CONFIRM, NativeUiPage.VOICE_COMMAND),
                    voiceRecognitionActive, voiceInputController.gateway.isRecording())
            }
            override fun navigationOwner() = NavigationSpeechOwner(
                if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.currentRuntimeEpochOrNull() else null,
                routeNavigator.currentRouteId(), routeNavigator.pendingDecisionToken())
            override fun navigationOwnerIsCurrent(owner: NavigationSpeechOwner): Boolean =
                owner.epoch != null && walkSessionLifecycle.currentRuntimeEpochOrNull() == owner.epoch &&
                    routeNavigator.currentRouteId() == owner.routeId && routeNavigator.pendingDecisionToken() == owner.decisionToken &&
                    isWalkSessionRuntimeActive() && navigationEnvironmentOutputsAllowed() &&
                    !voiceInputController.state.deferredPending && !isGuidanceVoiceInputActive()
            override fun homeFeatureContextAvailable() = nativeHomeFeatureContextAvailable()
            override fun stateSourceIsCurrent(source: CurrentStateSpeechLease) = source.isCurrent(currentStateSpeechReader())
            override fun guidanceVoiceInputActive() = isGuidanceVoiceInputActive()
            override fun screenReaderActive() = isScreenReaderActive()
        },
        input = SpeechInputPeerAdapter({ voiceInputController }, { voiceInteractionControllers }),
        presentation = voiceSpeechPresentation,
        readyEffects = object : SpeechOutputReadyEffects {
            override fun refreshReadyUi() {
                if (offlineKoreanTextToSpeechCapabilityOverride == false) offlineKoreanTextToSpeechCapabilityOverride = null
                refreshStartupCapabilityUi()
                updatePriorityUserOnboardingUi()
                updateVoiceCommandButton(active = voiceRecognitionActive)
            }
            override fun reevaluateCurrentRisk(actuator: AndroidFeedbackActuator, lifecycleGeneration: Int, nowMs: Long) =
                reevaluateCurrentRiskAfterSpeechReady(actuator, lifecycleGeneration, nowMs)
            override fun retryCurrentNavigation(nowMs: Long) = this@MainActivity.routeGuidanceController.retryCurrentNavigationSpeechAfterReady(nowMs)
            override fun offlineSpeechUnavailable(lifecycleGeneration: Int, actuator: AndroidFeedbackActuator) =
                handleOfflineKoreanSpeechUnavailable(lifecycleGeneration, actuator)
            override fun beforeCommandReplacement(previousGeneration: Long) = this@MainActivity.routeGuidanceController.failInterruptedRouteDecisionSpeech(previousGeneration)
        },
        storage = object : kr.co.hanium.dreamup.walksafe.voice.output.SpeechOutputStorageBinding {
            override fun invalidate() = invalidateSpeechOutputStorageBinding()
            override fun refresh(actuator: AndroidFeedbackActuator) = refreshSpeechOutputStorageBinding(actuator)
        },
        actuatorFactory = SpeechOutputActuatorFactory { unavailable, ready ->
            AndroidFeedbackActuator(context = this, onOfflineKoreanSpeechUnavailable = unavailable,
                onOfflineKoreanSpeechReady = ready, speechAllowed = ::authorizeActuatorSpeechForHomeWakeInput,
                hapticAllowed = {
                    trainingOutputCapabilityAllowed(WalkSafeStartupRequirement.VIBRATION) ||
                        startupCapabilityDecision?.allowsRequirement(WalkSafeStartupRequirement.VIBRATION) != false
                }).also { actuator ->
                    actuator.guidanceDiagnosticListener = { event ->
                        if (feedbackActuator === actuator) recordGuidanceDiagnosticEvent("tts", mapOf(
                            "stage" to event.kind.name, "tts_state" to event.outcome.name,
                            "elapsed_ms" to event.atElapsedRealtimeMs,
                        ))
                    }
                }
        },
        scheduler = voiceCallbacks,
    )

