private fun createTactileReferenceDelivery(): TactileReferenceDeliveryController<TactileResultReceipt> = TactileReferenceDeliveryController(
    frameStateLock = frameStateLock,
    source = object : TactileReferenceSource<TactileResultReceipt> {
        override fun currentFrame(generation: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(generation, epoch)
        override fun currentReceipt(receipt: TactileResultReceipt) = tactileResultIsCurrent(receipt)
        override fun clearReadyRiskInput() = clearSpeechReadyRiskInput()
        override fun updateLocalRouteDiagnostic(message: String) { latestTactileRouteState = message }
    },
    output = object : TactileReferenceOutput {
        override fun currentActor() = feedbackActuator
        override fun isMainThread() = Looper.myLooper() == Looper.getMainLooper()
        override fun postRetiredCancellation(action: () -> Unit) { detectorWatchdogHandler.post(action) }
    },
    nowMs = SystemClock::elapsedRealtime,
)


    private val voiceInputController by lazy { createVoiceInputController() }

    private fun createVoiceInputController(): VoiceInputSessionController {
        val platform = AndroidVoiceInputPlatform(this)
        return VoiceInputSessionController(
            environment = object : VoiceInputEnvironment {
                override fun identity() = VoiceInputIdentity(reporterUserId, GatewaySessionProcessCoordinator.snapshot().generation)
                override fun page() = VoiceInputPage(nativeUiPage, nativeUiPage.isVoiceInteractionPage() || voiceHelpScreen != null,
                    nativeUiPage == NativeUiPage.VOICE_COMMAND, nativeUiPage == NativeUiPage.GUIDANCE,
                    nativeUiPage == NativeUiPage.DESTINATION_SEARCH, pendingNativeUiPage == NativeUiPage.VOICE_COMMAND,
                    (pendingNativeUiPage == null || nativeUiPage == NativeUiPage.GUIDANCE) && voiceHelpScreen == null && !isInWalkInteractionArea())
                override fun walkOrNull() = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.snapshot() else null
                override fun foreground() = isActivityForeground
                override fun feedbackLifetimeGeneration() = feedbackLifecycleGeneration
                override fun capabilityDecision() = startupCapabilityDecision
                override fun capabilityAllows(decision: WalkSafeStartupCapabilityDecision, requirement: WalkSafeStartupRequirement) = decision.allowsRequirement(requirement)
                override fun microphoneGranted() = hasRecordAudioPermission()
                override fun notificationGranted() = hasHandsFreeNotificationPermission()
                override fun handsFreeFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE)
                override fun voiceGuidanceFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)
                override fun disclosureAccepted() = isHandsFreeVoiceDisclosureAccepted()
                override fun serverCommandRecognitionEnabled() = BuildConfig.WALKSAFE_SERVER_STT_ENABLED
                override fun walkAreaCommandAvailable() = walkAreaVoiceCommandAvailable()
                override fun walkWakeContextAvailable() = walkAreaVoiceCommandAvailable() &&
                    walkSessionLifecycle.snapshot().state != WalkSessionState.ACTIVE &&
                    nativeUiPage in setOf(NativeUiPage.GUIDANCE, NativeUiPage.SETTINGS) &&
                    nativeGuidanceConfirmationScreen == null && walkExitConfirmationScreen == null &&
                    voiceHelpScreen == null
                override fun homeFeatureContextAvailable() = nativeHomeFeatureContextAvailable()
                override fun startupCapabilityConfirmed() = isStartupCapabilityConfirmed()
                override fun runtimeActive() = isWalkSessionRuntimeActive()
                override fun confirmation() = VoiceInputConfirmation(walkSessionResumeController.promptPending,
                    walkSessionResumeController.confirmationToken, gatewayWalkSessionController.takeoverPromptPending,
                    gatewayWalkSessionController.takeoverPromptOperationId, gatewayWalkSessionController.startConfirmationToken)
                override fun commandWork() = VoiceInputCommandWork(destinationSearchGeneration, destinationSearchInFlight,
                    routeRequestGeneration, routeAcquisitionController.requestPending,
                    locationGeneration = destinationSearchController.locationConsumerGeneration,
                    locationInFlight = destinationSearchController.isAcquiring)
                override fun pendingNavigationDecisionToken() = routeNavigator.pendingDecisionToken()
                override fun takeoverConflictAvailable(epoch: WalkRuntimeEpoch) = gatewayWalkAuthorityController.currentConflictOrNull(epoch) != null
            },
            commands = VoiceInputCommandPeerAdapter({ voiceInteractionControllers }, { destinationSearchController },
                { walkSessionResumeController }, { gatewayWalkSessionController }, voiceInputPresentation,
                { speechOutputController }, ::nativeHomeFeatureContextAvailable,
                interceptRecognized = ::handleOverlayVoiceInput),
            presentation = voiceInputPresentation,
            applicationEffects = object : VoiceInputApplicationEffects {
                override fun requireStartupCapabilityConfirmation() = this@MainActivity.requireStartupCapabilityConfirmation()
                override fun permissionStateChanged(reason: String) = this@MainActivity.permissionFlowController.applyObservedPermissionStateChange(reason)
                override fun showMicrophoneDenial() = showPermissionDenialPanel(setOf(ObservedPermission.MICROPHONE), "voice_command_microphone_missing")
                override fun continueDeviceCheck() = maybeContinuePostLoginDeviceCheck()
                override fun refreshCapabilityUi() = refreshStartupCapabilityUi()
                override fun limitPersistentHandsFreeRecognition() {
                    val wasConfirmed = isStartupCapabilityConfirmed()
                    onDeviceSpeechRecognitionCapabilityOverride = false
                    refreshStartupCapabilityUi()
                    if (wasConfirmed) {
                        confirmedStartupCapabilityDecision = startupCapabilityDecision?.takeIf {
                            it.mayConfirmAndStart
                        }
                        refreshStartupCapabilityUi()
                    }
                    val walkStartStillAllowed = startupCapabilityDecision?.mayConfirmAndStart == true
                    updateStatus(
                        if (walkStartStillAllowed) "호출어 음성 기능 제한" else "휴대폰 내부 음성 인식 사용 불가",
                        if (walkStartStillAllowed) {
                            "기기 내 Vosk 음성 처리 오류로 호출어 기능만 제한했습니다. " +
                                "화면 음성 명령과 보행의 다른 기능은 계속 사용할 수 있습니다."
                        } else {
                            "기기 내 Vosk 음성 처리 오류로 휴대폰 내부 음성 인식을 사용할 수 없어 " +
                                "보행을 시작하거나 계속할 수 없습니다."
                        },
                    )
                }
            },
            output = VoiceInputSpeechPeerAdapter({ speechOutputController }, { this@MainActivity.riskFeedbackComponents.delivery }, SystemClock::elapsedRealtime, ::isScreenReaderActive),
            scheduler = voiceCallbacks,
            platform = platform,
            wakePlatform = platform,
            gatewayPlatform = platform,
            gatewayEnvironment = object : GatewayVoiceEnvironment {
                override fun networkAllowed(reason: String) = isGatewayNetworkAllowed(reason)
                override fun networkState() = gatewayFeatureNetworkState()
                override fun sessionPrerequisitesAllowed() =
                    isGatewayFeatureNetworkAllowed() && isActivityForeground &&
                        firstRunOnboardingController.initialized &&
                        firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
                        firstRunOnboardingSnapshot.isComplete && postLoginDeviceCheckPassesFeatureGate()
                override fun processSnapshot() = GatewaySessionProcessCoordinator.snapshot()
            },
        )
    }


