private fun createRiskFeedbackComponents(): RiskFeedbackComponents<TactileResultReceipt> = RiskFeedbackComponents(
    frameStateLock = frameStateLock,
    phoneMountingObservationLock = phoneMountingObservationLock,
    admission = object : RiskFeedbackAdmission {
        override fun generation() = feedbackLifecycleGeneration
        override fun lifecycleCurrent(generation: Int) = isFeedbackLifecycleCurrent(generation)
        override fun runtimeEpochOrNull() = walkSessionLifecycle.currentRuntimeEpochOrNull()
        override fun runtimeEpochCurrent(epoch: WalkRuntimeEpoch) = walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        override fun evaluateSafety(nowMs: Long) = walkRuntimeSafetyCoordinator.evaluate(nowMs)
        override fun qualitativeAllowsWork(nowMs: Long) = currentArCoreQualitativeFeedbackAllowsWork(nowMs)
        override fun deviceGateAllowsAlerts() = currentFeedbackDeviceGateAllowsAlerts()
        override fun freshUnknownFeedbackBatches(nowMs: Long) = this@MainActivity.freshUnknownFeedbackBatches(nowMs)
        override fun unknownFeedbackTrackIsCurrent(trackId: String) =
            unknownCaptureCoordinatorLazy.isInitialized() && unknownCaptureCoordinator.feedbackTrackIsCurrent(trackId)
        override fun phoneMountingOutputsAllowed() = phoneMountingOutputsAllowed
    },
    output = RiskVoicePeerAdapter({ speechOutputController }, { voiceInputController }),
    scheduler = voiceCallbacks,
    log = object : RiskFeedbackLog {
        override fun initialized() = ::fieldSessionLog.isInitialized
        override fun recordEvent(name: String, fields: Map<String, Any?>) = fieldSessionLog.recordEvent(name, fields)
    },
    frames = object : RiskFeedbackFrameDelivery<TactileResultReceipt> {
        override fun deliver(dispatch: TactileFrameFeedbackDispatch) = tactileFrameFeedbackDelivery(dispatch)
        override fun dispatchTactileFrameFeedback(frame: TactileSnapshotFrameResult, stale: Boolean, deviceGateAllowsAlerts: Boolean,
            nowMs: Long, feedbackActuatorOverride: TactileFrameFeedbackActuator?, independentFreshOutputs: List<UnknownObjectFeedbackBatch>,
            warningContext: kr.co.hanium.dreamup.walksafe.navigation.WarningRegionContext?) =
            this@MainActivity.dispatchTactileFrameFeedback(frame, stale, deviceGateAllowsAlerts, nowMs,
                feedbackActuatorOverride, independentFreshOutputs, warningContext)
        override fun dispatchConsumedTactileFrameFeedback(receipt: TactileResultReceipt, frame: TactileSnapshotFrameResult,
            stale: Boolean, deviceGateAllowsAlerts: Boolean, nowMs: Long, feedbackActuatorOverride: TactileFrameFeedbackActuator?,
            independentFreshOutputs: List<UnknownObjectFeedbackBatch>, warningContext: kr.co.hanium.dreamup.walksafe.navigation.WarningRegionContext?) =
            this@MainActivity.dispatchConsumedTactileFrameFeedback(receipt, frame, stale, deviceGateAllowsAlerts, nowMs,
                feedbackActuatorOverride, independentFreshOutputs, warningContext)
    },
)

