    private val tactileDotDispatch: TactileDotReferenceDispatchController<RuntimeArObservation, TactileResultReceipt> by lazy {
        TactileDotReferenceDispatchController(
            { tactileReferenceDelivery },
            object : TactileDotDispatchAuthority<RuntimeArObservation> {
                override fun feedbackLifecycleCurrent(generation: Int) = isFeedbackLifecycleCurrent(generation)
                override fun frameCurrent(generation: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(generation, epoch)
                override fun leaseCurrent(lease: RuntimeArObservation, observe: () -> RuntimeArObservation) = isRuntimeArLeaseCurrent(lease, observe)
                override fun safety(nowMs: Long) = evaluateWalkRuntimeSafety(nowMs)
                override fun metricOutputAllowed(arGeneration: Long, observe: () -> RuntimeArObservation) = currentRuntimeMetricOutputAllowsWork(arGeneration, observe)
                override fun deviceGate(arGeneration: Long, observe: () -> RuntimeArObservation) = buildDeviceGateState(
                    bestOutput = null, staleReason = null, expectedRuntimeMetricGeneration = arGeneration, observeRuntimeAr = observe)
                override fun voiceFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)
                override fun offlineTtsAllowed() = startupCapabilityDecision?.allowsRequirement(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) == true
                override fun guidanceVoiceInputActive() = isGuidanceVoiceInputActive()
            }, TactileDotDispatchActor { ensureFeedbackActuator() },
        )
    }

