    private val firstRunOnboardingController: FirstRunOnboardingController by lazy(LazyThreadSafetyMode.NONE) {
        FirstRunOnboardingController(
            profiles = priorityUserProfileController,
            gateway = object : FirstRunOnboardingController.Gateway {
                override fun storeInitialized() = this@MainActivity::gatewaySessionStore.isInitialized
                override fun fieldActorId() = this@MainActivity.gatewayFieldSession?.actorId
                override fun clearSession() { this@MainActivity.clearGatewaySession(logoutRemote = true) }
                override fun publishStageSnapshot(actorId: String, snapshot: () -> FirstRunOnboardingSnapshot) {
                    val process = GatewaySessionProcessCoordinator.snapshot()
                    val published = GatewaySessionProcessCoordinator.updateFirstRunSnapshot(
                        expectedGeneration = process.generation, expectedActorId = actorId, firstRunSnapshot = snapshot())
                    if (published && process.session?.isBackendAccountDeviceBound == true) {
                        val stored = this@MainActivity.gatewaySessionStore.updateBackendDeviceFirstRunSnapshot(
                            requireNotNull(process.session.versionOrNull), snapshot())
                        if (stored == GatewaySessionStoreResult.BLOCKED || stored == GatewaySessionStoreResult.STORAGE_FAILURE)
                            GatewaySessionProcessCoordinator.markStorageBlocked(process.generation)
                    }
                }
                override fun publishCompletedSnapshot(actorId: String, snapshot: FirstRunOnboardingSnapshot): Boolean {
                    val process = GatewaySessionProcessCoordinator.snapshot()
                    return GatewaySessionProcessCoordinator.updateFirstRunSnapshot(
                        expectedGeneration = process.generation, expectedActorId = actorId, firstRunSnapshot = snapshot)
                }
            },
            education = object : FirstRunOnboardingController.Education {
                override fun cancelPendingFeedback() { this@MainActivity.educationInteractionController.cancelPendingPriorityUserTrainingFeedback() }
                override fun evidenceComplete() = this@MainActivity.currentFirstRunEducationEvidenceComplete()
            },
            effects = object : FirstRunOnboardingController.Effects {
                override fun onboardingComplete() = this@MainActivity.firstRunOnboardingComplete()
                override fun quickStartEnabled() = this@MainActivity.developmentQuickStartEnabled
                override fun quickStartActorOrNull() = this@MainActivity.developmentQuickStartController.developmentQuickStartSessionOrNull()?.actorId
                override fun reporterActorId() = this@MainActivity.reporterUserId
                override fun setReporterActor(actorId: String) { this@MainActivity.reporterUserId = actorId }
                override fun invalidateSpeechActorIfChanged(actorId: String) { this@MainActivity.speechOutputStorageCoordinator.invalidatePermissionActorIfChanged(actorId) }
                override fun authenticateActor(actorId: String) { this@MainActivity.permissionSessionPolicy.authenticated(actorId) }
                override fun reapplyActorBoundConsent() { this@MainActivity.reapplyActorBoundIntegratedConsent() }
                override fun rawWalkWasActive() = this@MainActivity::walkSessionLifecycle.isInitialized &&
                    this@MainActivity.walkSessionLifecycle.snapshot().state == WalkSessionState.ACTIVE
                override fun deviceGatePassed() = this@MainActivity.postLoginDeviceCheckPassesFeatureGate()
                override fun invalidateMetric(reason: String) { this@MainActivity.runtimeMetricInvalidation.invalidate(reason) }
                override fun safetyStop(reason: String) { this@MainActivity.enterWalkSessionSafetyStopAndCancelOutputs(reason) }
                override fun walkRuntimeActive() = this@MainActivity.isWalkSessionRuntimeActive()
                override fun invalidateEnvironment(reason: String) { this@MainActivity.invalidateOfficialEnvironmentEvidence(reason) }
                override fun invalidateMounting(reason: String) { this@MainActivity.invalidatePhoneMountingEvidence(reason) }
                override fun authenticatedFor(actorId: String) = this@MainActivity.permissionSessionPolicy.isAuthenticatedFor(actorId)
                override fun invalidateSpeechStorage() { this@MainActivity.invalidateSpeechOutputStorageBinding() }
                override fun rememberActor(actorId: String) { this@MainActivity.permissionSessionPolicy.rememberActor(actorId) }
                override fun acknowledgeVoiceDisclosure() = this@MainActivity.acknowledgeHandsFreeVoiceDisclosure()
                override fun startFirstRunDeviceCheckProbes() { this@MainActivity.maybeStartFirstRunDeviceCheckProbes() }
                override fun updateOnboardingUi() { this@MainActivity.updateFirstRunOnboardingUi() }
                override fun updatePriorityUi() { this@MainActivity.updatePriorityUserOnboardingUi() }
                override fun refreshStartupIfInitialized() { if (this@MainActivity::startupCapabilityProbe.isInitialized) this@MainActivity.refreshStartupCapabilityUi() }
                override fun refreshConfirmedConsentAfterCompletion(actorId: String) {
                    this@MainActivity.runOnUiThread {
                        if (isFinishing || isDestroyed || !isActivityForeground ||
                            !firstRunOnboardingSnapshot.isComplete ||
                            firstRunOnboardingSnapshot.verifiedActorBinding?.value != actorId ||
                            reporterUserId != actorId || priorityUserOnboardingActorId != actorId) {
                            return@runOnUiThread
                        }
                        val consent = integratedConsentController.screenState()
                        if (consent.pendingMutation != null || consent.requestInFlight ||
                            integratedConsentSession.pendingMutationOrNull() != null) {
                            return@runOnUiThread
                        }
                        runCatching { refreshIntegratedConsentFromServer() }.onFailure {
                            updateNavigationStatus(
                                "integratedConsent=refresh_start_failed trigger=education_complete",
                            )
                        }
                    }
                }
                override fun focusStage(stage: FirstRunOnboardingStage) { this@MainActivity.focusCurrentFirstRunStage(stage) }
                override fun screenReaderActive() = this@MainActivity.isScreenReaderActive()
                override fun foreground() = this@MainActivity.isActivityForeground
                override fun showStatus(status: String, detail: String) { this@MainActivity.updateStatus(status, detail) }
                override fun navigationDiagnostic(message: String) { this@MainActivity.updateNavigationStatus(message) }
                override fun speakInteraction(message: String, purpose: FirstRunOnboardingController.AnnouncementPurpose) {
                    val restoredLoginCurrent = {
                        nativeUiPage == NativeUiPage.HOME &&
                            nativeHomeFeatureContextAvailable() && !isScreenReaderActive()
                    }
                    val restoredLogin = purpose == FirstRunOnboardingController.AnnouncementPurpose.RESTORED_LOGIN
                    val restoredLoginAllowed = restoredLogin && restoredLoginCurrent()
                    if (BuildConfig.DEBUG) {
                        android.util.Log.d("WalkSafeVoiceInput", "event=ONBOARDING_OUTPUT purpose=$purpose" +
                            " dispatch=${if (!restoredLogin) "GENERAL" else if (restoredLoginAllowed) "HOME_STATUS" else "OMITTED"}")
                    }
                    if (restoredLogin) {
                        if (restoredLoginAllowed) {
                            speechOutputController.speakCommandResponse(message, statusExplanation = true,
                                additionalCurrent = restoredLoginCurrent)
                        }
                    } else {
                        this@MainActivity.speakInteraction(message)
                    }
                }
            },
            digest = ::sha256Hex,
        )
    }
