    runtime = object : GatewayWalkRuntime {
        override fun snapshot() = walkSessionLifecycle.snapshot()
        override fun currentStartReadinessOrNull(token: WalkSessionConfirmationToken) = currentGatewayWalkStartReadinessOrNull(token)
        override fun blocksAutomaticStart() = permissionRecoveryGate.blocksAutomaticResourceStart && !developmentGuidanceStartBypassEnabled
        override fun startRequested(token: WalkSessionConfirmationToken, readiness: WalkSessionReadinessSnapshot) {
            transitionWalkSession(WalkSessionEvent.StartRequested(token, readiness))
        }
        override fun isActive() = isWalkSessionRuntimeActive()
        override fun activate() = activateWalkSessionRuntime()
        override fun isForeground() = isActivityForeground
        override fun safetyStop(reason: String) = enterWalkSessionSafetyStopAndCancelOutputs(reason)
        override fun refreshReadinessUi() = refreshStartupCapabilityUi()
        override fun observeResourceSafety() { observeWalkRuntimeResourceSafety() }
    },
    identity = object : GatewayWalkIdentity {
        override fun sessionOrNull(reason: String, speak: Boolean) = gatewaySessionOrNull(reason, speak)
        override fun currentSession() = gatewayFieldSession
        override fun isCurrent(session: GatewayFieldSession) = this@MainActivity.gatewaySessionController.isCurrentGatewaySession(session)
        override fun isRenewedContinuation(session: GatewayFieldSession) = this@MainActivity.gatewaySessionController.isRenewedGatewaySessionContinuation(session)
        override fun awaitRenewal(onRenewed: () -> Unit) = awaitInRunGatewaySessionRenewal(onRenewed)
        override fun probeAfterUnauthorized(session: GatewayFieldSession, onRenewed: () -> Unit) = probeGatewaySessionAfterUnauthorized(session, onRenewed)
    },
    output = object : GatewayWalkOutput {
        override fun updateStatus(title: String, detail: String) = this@MainActivity.updateStatus(title, detail)
        override fun updateNavigationStatus(detail: String) = this@MainActivity.updateNavigationStatus(detail)
        override fun makeStartRetryAvailable(detail: String, spoken: String?) {
            startupCapabilityConfirmationPending = false
            confirmedStartupCapabilityDecision = null
            startupCapabilityRetryRequiresUserAction = true
            refreshStartupCapabilityUi()
            updateStatus("보행 시작 대기", detail)
            spoken?.let(::speakInteraction)
        }
        override fun startTakeoverRecognition(operationId: String) = startVoiceCommandRecognition(
            purpose = VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER,
            expectedGatewayWalkOperationId = operationId,
        )
        override fun speakTakeover(message: String, onCompleted: () -> Unit, onFailed: () -> Unit) =
            ensureFeedbackActuator().speakInteraction(message, onCompleted, onFailed) == NavigationSpeechDispatchResult.ACCEPTED
        override fun debug(tag: String, message: String) { android.util.Log.d(tag, message) }
    },
    scheduler = object : GatewayWalkScheduler {
        override fun execute(action: () -> Unit) { gatewaySessionExecutor.execute(action) }
        override fun runOnUiThread(action: () -> Unit) { this@MainActivity.runOnUiThread(action) }
        override fun runOnUiThread(action: Runnable) { this@MainActivity.runOnUiThread(action) }
        override fun nowMs() = SystemClock.elapsedRealtime()
        override fun removeCallbacks(runnable: Runnable) { gatewayWalkRenewalHandler.removeCallbacks(runnable) }
        override fun post(runnable: Runnable) { gatewayWalkRenewalHandler.post(runnable) }
        override fun postDelayed(runnable: Runnable, delayMs: Long) { gatewayWalkRenewalHandler.postDelayed(runnable, delayMs) }
        override fun postDelayed(action: () -> Unit, delayMs: Long) { gatewayWalkRenewalHandler.postDelayed(action, delayMs) }
    },
)

    // Walk lease deadlines are computed from SystemClock.elapsedRealtime(); expiry must use the same
    // deep-sleep-inclusive clock (System.nanoTime() stops during Android deep sleep).
    private val gatewayWalkAuthorityController = GatewayWalkAuthorityController(
        elapsedClock = SystemClock::elapsedRealtime,
    )
