                override fun clearNativeSearchAndShowHome() {
                                    clearNativeDestinationSearchState()
                                    showNativeUiPage(NativeUiPage.HOME)
                                }
                override fun renderMain() = renderMainUi()
                override fun resetStartSpeechState(clearGuidanceState: () -> Unit) {
                                    guidancePreparationController.clearPreparationFailureOwner()
                                    cancelGuidancePreparationSpeech()
                                    clearGuidanceState()
                                }
                override fun beginInstalledRoute(clearResume: () -> Unit): () -> Unit {
                                    val previous = pendingGuidancePreparationSpeech?.takeIf { it.isCurrent() }
                                    cancelGuidancePreparationSpeech()
                                    clearResume()
                                    return { inheritGuidancePreparationSpeechFailure(previous) }
                                }
                override fun recordInstalledRoute(route: WalkingRoute, currentRouteId: () -> String?) {
                                    if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("route_installed",
                                        mapOf("routeId" to currentRouteId(), "points" to route.polyline.size,
                                            "guides" to route.guidePoints.size, "distanceM" to route.summary.distanceM))
                                }
                override fun showDestinationCoordinates(destination: RoutePoint) {
                                    if (::destinationLatInput.isInitialized) destinationLatInput.setText(destination.latitude.toString())
                                    if (::destinationLngInput.isInitialized) destinationLngInput.setText(destination.longitude.toString())
                                }
                override fun recordStage(stage: String) = recordGuidancePreparationStage(stage)
                override fun sessionNotReady(session: GatewayFieldSession) { clearGatewaySession(logoutRemote = false, expectedSession = session) }
                override fun failureAdmission(session: GatewayFieldSession, authenticationFailure: Boolean): (() -> Boolean)? {
                                    val guard = gatewayFailureUiGuardOrNull(session = session,
                                        expectedAuthenticationFailure = authenticationFailure) ?: return null
                                    return { isGatewayFailureUiGuardCurrent(session, guard) }
                                }
            } },
            backend = { object : RouteAcquisitionController.Backend {
                            override fun fetchRoute(session: GatewayFieldSession, request: WalkingRouteRequest) = walkingRouteClient.fetchRouteCall(session, request)
                            override fun revalidate(session: GatewayFieldSession, actorId: String?, capacitySessionGeneration: Long) =
                                gatewaySessionClient.revalidate(session, actorId, capacitySessionGeneration = capacitySessionGeneration)
                        } },
