                        override val recording get() = ::fieldSessionLog.isInitialized || guidanceDiagnosticRuntime != null
                        override fun log(tag: String, message: String) { android.util.Log.d(tag, message) }
                        override fun record(event: String, values: Map<String, Any?>) {
                            if (::fieldSessionLog.isInitialized) runCatching { fieldSessionLog.recordEvent(event, values) }
                            GuidanceDiagnosticMetadata.structured(event, values)?.let { recordGuidanceDiagnosticEvent(it.name, it.fields) }
                            recordDirectionGraceDiagnostic()
                        }
                        override fun confidenceLine(snapshot: PositioningSnapshot) = positioningDiagnosticsPresenter.positionConfidenceDiagnosticLine(snapshot)
                    } }
        ),
        gpsActor = object : NavigationGpsActorAuthority {
