        elapsedRealtimeMs = SystemClock::elapsedRealtime,
        wallTimeMs = System::currentTimeMillis,
        isMainThread = { Looper.myLooper() == Looper.getMainLooper() },
        postToUi = { action -> runOnUiThread { action() } }
