    private fun arrivalCleanupBlocksNewWalk(): Boolean {
        val cleanup = arrivalCleanupCheckpoints ?: return false
        return !cleanup.allStagesComplete() || routeSnapshotPurgeFailed || primaryDetectorOwner.nativeWorkBlocked()
    }

    private fun arrivalCleanupFailed(): Boolean {
        val cleanup = arrivalCleanupCheckpoints ?: return false
        return cleanup.hasUncertainStages() || routeSnapshotPurgeFailed || primaryDetectorOwner.nativeWorkBlocked()
    }
