    private val accountDeletionClient = AndroidPrivacyDeletionClient(
        signEvidence = { journal, evidence -> installationEvidenceKey.signIfPresent(journal, evidence,
            requireNotNull(accountDeletionRecoveryStore.evidenceActorHashOrNull(journal, evidence))) },
        onDeviceVerification = { status, view ->
            if (::accountDeletionActivityLease.isInitialized) {
                val lease = accountDeletionActivityLease
                postGatewayActivityCallback(lease) {
                    val journal = accountDeletionStateMachine.snapshotOrNull()
                    if (journal != null && journal.requestId == status.requestId && journal.installationId == status.installationId &&
                        journal.serverRevision <= status.revision && journal.clientRevision == status.clientRevision &&
                        (journal.accountGeneration == null || journal.accountGeneration == status.accountGeneration) &&
                        (journal.tombstoneId == null || journal.tombstoneId == status.tombstoneId) &&
                        (journal.requestReceiptSha256 == null || journal.requestReceiptSha256 == status.requestReceiptSha256)) {
                        accountDeletionDeviceVerification = status to view
                        updateAccountDeletionUi()
                    }
                }
            }
        },
    )
