    private fun createPrivacyConsent(): Lazy<IntegratedConsentController> =
        privacyAuthority.createIntegratedConsentController { reportConsent, legacyPurge, speechStorage ->
        PrivacyConsentParticipants(
            gateway = object : IntegratedConsentController.Gateway {
            override fun configuredOrigin() = configuredGatewayOriginOrNull()
            override fun installationId() = gatewaySessionStore.getOrCreateInstallDeviceId()
            override fun sessionOrNull(reason: String, speak: Boolean) = gatewaySessionOrNull(reason, speak)
            override fun refreshSessionOrNull() = integratedConsentRefreshSessionOrNull()
            override fun isCurrentSession(session: GatewayFieldSession) = this@MainActivity.gatewaySessionController.isCurrentGatewaySession(session)
        },
            permissions = { permissionSessionPolicy },
            actor = object : IntegratedConsentController.Actor {
            override fun currentReporterActorId() = reporterUserId
            override fun isIntegratedConsentOnboardingStage() = firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.INTEGRATED_CONSENT
        },
            reports = object : IntegratedConsentController.Reports {
            override fun withdrawAuthority() { reportConsent().withdraw() }
            override fun cancelDrain() = cancelReportQueueDrain()
            override fun automaticRevoked(receipt: String, reporterActorId: String, accountGeneration: Long?) =
                reportQueueDrainController.onAutomaticReportingRevoked(receipt, reporterActorId, accountGeneration)
            override fun cancelAutomaticCalls() {
                synchronized(reportUploadSafetyLock) {
                    automaticReportUploadSafetyGeneration += 1L
                    reportConsent().cancelActiveCalls(ReportTransferPurpose.AUTOMATIC)
                }
            }
            override fun scheduleLegacyPurge() { legacyPurge().schedule() }
            override fun cancelAllCallsForMobileWithdrawal() {
                synchronized(reportUploadSafetyLock) {
                    reportUploadSafetyGeneration += 1L
                    reportConsent().cancelActiveCalls()
                }
            }
            override fun applyConfirmationAuthority(unchanged: Boolean, guard: IntegratedConsentAuthorityGuard) {
                synchronized(reportUploadSafetyLock) {
                    if (!unchanged || !reportConsent().isGranted()) {
                        reportUploadSafetyGeneration += 1L
                        automaticReportUploadSafetyGeneration += 1L
                        reportConsent().cancelActiveCalls()
                    }
                    reportConsent().grantFromServerConfirmedIntegratedConsent(guard)
                }
            }
            override fun invalidateExplicitReport() = invalidatePendingExplicitReport()
        },
            raw = object : IntegratedConsentController.RawStorage {
            override fun cancelOriginalUploads() = cancelActivityOriginalUploads()
            override fun cancelActiveUploadIfReady() {
                if (::rawCollectionRuntimeCoordinator.isInitialized) rawCollectionRuntimeCoordinator.cancelActiveUpload()
            }
            override fun withdrawReceiptIfReady(previousReceipt: String?) {
                if (::rawCollectionRuntimeCoordinator.isInitialized) {
                    rawCollectionTransferController.clearUploadWalk()
                    rawCollectionRuntimeCoordinator.cancelActiveUpload()
                    executeRawCollectionTask {
                        if (previousReceipt != null) rawCollectionRuntimeCoordinator.onConsentRevoked(previousReceipt)
                        clearRawDetectionWindow()
                        currentRawCollectionRuntimeContextOrNull()?.let { context -> rawCollectionRuntimeCoordinator.revalidate(context) }
                    }
                }
            }
            override fun disableMetadataIfReady() {
                if (::metadataLogUploader.isInitialized) metadataLogUploader.setEnabled(false)
            }
            override fun blockFieldLogIfReady() {
                if (::fieldSessionLog.isInitialized) fieldSessionLog.blockForRawSourceWithdrawal()
            }
            override fun blockFieldLog() { fieldSessionLog.blockForRawSourceWithdrawal() }
            override fun holdReceiptUntilDecidedIfReady(receipt: String) {
                if (::rawCollectionRuntimeCoordinator.isInitialized) rawCollectionRuntimeCoordinator.holdReceiptUntilDecided(receipt)
            }
            override fun resetFieldLogAfterConfirmedConsentIfActive() {
                if (speechStorage().collectionOrNull()?.retired?.get() != true) fieldSessionLog.resetRawSourceAfterConfirmedConsent()
            }
            override fun confirmedReceiptChangedIfReady(previousReceipt: String?, previousConfirmation: IntegratedConsentConfirmation?, confirmation: IntegratedConsentConfirmation, rawEffective: Boolean) {
                if (::rawCollectionRuntimeCoordinator.isInitialized) {
                    rawCollectionTransferController.clearUploadWalk()
                    rawCollectionRuntimeCoordinator.cancelActiveUpload()
                    val rawSupersede = rawConsentSupersede(previousConfirmation, confirmation, currentRawEffective = rawEffective)
                    executeRawCollectionTask {
                        if (previousReceipt != null) {
                            if (rawSupersede == RawConsentSupersede.RAW_CONTINUED) {
                                rawCollectionRuntimeCoordinator.onConsentContinued(previousReceipt, confirmation.backendConsentReceiptSha256)
                            } else {
                                rawCollectionRuntimeCoordinator.onConsentRevoked(previousReceipt)
                            }
                        }
                        clearRawDetectionWindow()
                        currentRawCollectionRuntimeContextOrNull()?.let { context -> rawCollectionRuntimeCoordinator.revalidate(context) }
                    }
                }
            }
        },
            network = object : IntegratedConsentController.Network {
            override fun refreshFeaturePolicy() = refreshGatewayFeatureNetworkPolicy()
            override fun isCellularIfReady() = ::networkStateProbe.isInitialized && networkStateProbe.currentTransport() == ActiveNetworkTransport.CELLULAR
            override fun cancelGatewayCalls() = cancelGatewayNetworkCalls()
        },
            ui = object : IntegratedConsentController.Ui {
            override fun postRefresh() = postIntegratedConsentUiRefresh()
            override fun refresh() = updateIntegratedConsentUi()
            override fun status(message: String) = updateNavigationStatus(message)
            override fun speakInteraction(message: String) { this@MainActivity.speakInteraction(message) }
            override fun completeFirstRunIfReady(confirmation: IntegratedConsentConfirmation) { completeFirstRunIntegratedConsentIfReady(confirmation) }
            override fun schedulePostWalkTransfers() = this@MainActivity.schedulePostWalkTransfers()
            override fun scheduleAutomaticReportCleanupRetry(action: () -> Unit, delayMs: Long) {
                reportCleanupCallbackHandler.postDelayed({ if (!privacyStartupInspectionDestroyed) action() }, delayMs)
            }
        },
            executor = gatewaySessionExecutor,
        )
    }
