    private val accountDeletionPreparationController = createPrivacyPreparation()

    private fun createPrivacyPreparation(): AccountDeletionPreparationController =
        privacyAuthority.createAccountDeletionPreparationController(
        queries = object : AccountDeletionPreparationQueries {
            override fun generalSession() = gatewaySessionOrNull(reason = "account_deletion", speak = false)
            override fun trustedOrigin() = configuredGatewayOriginOrNull()
            override fun currentReporterActor() = currentReporterUserId()
            override fun sensitiveStorageBlocked() = sensitivePrefs.isBlocked()
            override fun captureInstallationKeyPreparation(session: GatewayFieldSession): (() -> CancellableNetworkCall<Unit>)? {
                val confirmation = integratedConsentSession.currentConfirmationOrNull(emptySet()) ?: return null
                val snapshot = GatewaySessionProcessCoordinator.snapshot()
                if (snapshot.session !== session || !GatewaySessionProcessCoordinator.isCurrentGeneralSession(snapshot.generation, session) ||
                    session.accountGenerationOrNull == null) return null
                return { integratedConsentClient.registerInstallationEvidenceKeyCall(session, confirmation) {
                    GatewaySessionProcessCoordinator.isCurrentGeneralSession(snapshot.generation, session)
                } }
            }
        }, reapplyActorBoundConsentAction = ::reapplyActorBoundIntegratedConsent,
    )

