            override fun persistentFieldLoggerReady() = ::fieldSessionLog.isInitialized && fieldSessionLog is PersistentFieldSessionLog
            override fun blockPersistentFieldLogger() { fieldSessionLog.blockForAccountDeletion() }
            override fun purgePersistentFieldLogger() = fieldSessionLog.purgeAll()
            override fun purgeCollectionFieldProvider() = speech().collectionOrNull()?.provider?.purgeAll()
            override fun purgeOutdoorPositionArtifacts() = DebugCollectionArtifacts.purgeOutdoorPositionTest(noBackupFilesDir)
            override fun purgeGuidanceDiagnostics() = purgeGuidanceDiagnosticsOnWorker()
            override fun purgeRuntimeDiagnostics() = BoundedRuntimeDiagnosticLog.purgeForAccountDeletion(cacheDir)
            override fun purgeSerialPedestrianProfiles() = !::stepLengthPrefs.isInitialized ||
