    private val accountDeletionRuntimeFenceController by createPrivacyRuntimeFence()

    private fun createPrivacyRuntimeFence(): Lazy<AccountDeletionRuntimeFenceController> =
        privacyAuthority.createAccountDeletionRuntimeFenceController {
        PrivacyFenceParticipants(
            purgeAndRotatePosition = ::purgeAndRotatePositionFieldScope,
            reports = object : AccountDeletionReportFenceActions {
            override fun cancelDrainAndFenceQueue() { cancelReportQueueDrain(); reportQueueDrainController.onAccountDeleted() }
            override fun clearUserRequests() {
                clearUserReportRequestUiForAuthorityFence()
                if (::userReportController.isInitialized) userReportController.onAuthorityChanged()
            }
            override fun advanceUploadAuthority() { synchronized(reportUploadSafetyLock) {
                reportUploadSafetyGeneration += 1L
                automaticReportUploadSafetyGeneration += 1L
            } }
            override fun cancelOriginalUploads() { cancelActivityOriginalUploads() }
            override fun clearAttemptState() {
                reportAttemptStore = AndroidReportAttemptStore(bootCountProvider = ::reportCooldownBootCount)
                actorReportAttemptRepository.clearForAccountDeletion()
            }
        },
            fenceRawCollections = {
            if (::rawCollectionRuntimeCoordinator.isInitialized) {
                rawCollectionTransferController.clearUploadWalk()
                rawCollectionRuntimeCoordinator.fenceAccountDeletionAdmission()
                clearRawDetectionWindow()
            }
        },
            blockFieldProcessing = { if (::fieldSessionLog.isInitialized) fieldSessionLog.blockNewProcessingForAccountDeletion() },
            clearPermissions = { permissionSessionPolicy.applyIntegratedConsentSelections(IntegratedConsentSelections()) },
            disableMetadata = { if (::metadataLogUploader.isInitialized) metadataLogUploader.setEnabled(false) },
            invalidateFrames = ::invalidateFrameStateForPause,
            stopActiveWalk = { if (::surfaceView.isInitialized && isWalkSessionRuntimeActive()) {
            enterWalkSessionSafetyStopAndCancelOutputs("account_deletion_requested", persistInterruptionMarker = false)
        } },
            showPositionFailure = { updateNavigationStatus("accountDeletion=blocked:position_field_purge") },
        )
    }

