    private fun createVisionUnknownComposition() = VisionUnknownComposition(
        { applicationContext }, { this }, { primaryDetectorOwner }, { primaryRuntimeCalibrationOwner },
        { frameStateLock }, { unknownCaptureClock },
        authority = { object : UnknownRuntimeServiceAuthority {
                override fun destroyedOrDetectorClosing() = isDestroyed || primaryDetectorOwner.projection().closing
                override fun mayStartWalkingService() = !isDestroyed && !primaryDetectorOwner.projection().closing && isActivityForeground && primaryDetectorOwner.projection().available
                override fun calibrationCameraAvailable() = calibrationCameraOwnerAvailable()
                override fun speechActive() = voiceRecognitionActive || feedbackActuator?.isAppSpeechActive() == true
            } },
        captureScope = { object : UnknownCaptureScopeReader {
                override fun runtime() = UnknownCaptureRuntimeScope(
                    walkSessionLifecycle.currentRuntimeEpochOrNull(), isActivityForeground, primaryDetectorOwner.projection().closing,
                    primaryDetectorOwner.projection().frameGeneration, arSessionOwner.observe().generation, visualGeometryVersion, primaryDetectorOwner.projection().loadGeneration,
                    feedbackLifecycleGeneration, stepLengthEstimator.stepLengthM, reportRuntimeConfig)
                override fun withDepthAuthority(capture: UnknownCaptureProcessingLease,
                    check: (UnknownCaptureDepthAuthority) -> Boolean): Boolean = synchronized(runtimeMetricStateLock) {
                    check(UnknownCaptureDepthAuthority(runtimeMetricLastFrameTimestampNanos, runtimeVisualDepthFrameTracking) {
                        currentRuntimeVisualDepthProcessingAllowsWork(
                            capture.arLease.originalLease as ArSessionLease,
                            runtimeMetricLastFrameTimestampNanos, runtimeVisualDepthFrameTracking)
                    })
                }
                override fun ownsFrame(generation: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(generation, epoch)
                override fun execution() = UnknownCaptureExecutionObservation(latestInferenceThermalThrottled)
                override fun metricOutputAllowsWork(expectedArGeneration: Long) = currentRuntimeMetricOutputAllowsWork(expectedArGeneration)
                override fun cameraProfile() = activeCameraFrameQualityProfile
                override fun powerSaveMode() = getSystemService(android.os.PowerManager::class.java).isPowerSaveMode
            } },
        captureObserver = { object : UnknownCaptureObserver {
                override fun observeCamera(observation: CameraFrameQualityObservation) { observeOfficialEnvironmentCameraFrame(observation) }
                override fun projectTactile(bundle: TactileMaskCaptureBundle, atElapsedRealtimeNs: Long) =
                    projectTactileMaskCaptureBundle(bundle, atElapsedRealtimeNs)
                override fun publishTactile(bundle: TactileMaskCaptureBundle, surfaces: List<TactileMaskSurfaceResult>,
                    publication: UnknownTactilePublication, decisionNs: Long,
                    admissionIsCurrent: () -> Boolean, outputIsCurrent: () -> Boolean): Boolean {
                    val source = TactileResultSource(TactileDotReferenceDeliveryOwner(publication.epoch,
                        publication.feedbackLifecycleGeneration, publication.detectorGeneration, publication.arGeneration),
                        bundle.semanticCapture.token.frameId, bundle.semanticCapture.token.capturedElapsedNs / 1_000_000L,
                        bundle.semanticCapture.token.cpuImageTimestampNs, publication.geometryVersion,
                        bundle.snapshot.frameEvidence?.tactileContext?.expectedRouteId,
                        bundle.snapshot.frameEvidence?.tactileContext?.routeProjection?.let {
                            kr.co.hanium.dreamup.walksafe.navigation.TactileActiveRouteProgress(it.routeRevision, it.segmentIndex)
                        })
                    return deliverTactileMaskCaptureBundle(bundle, decisionNs, surfaces, source,
                        admissionIsCurrent = admissionIsCurrent) { frame, receipt ->
                        publishCompletedTactileMaskCapture(publication, frame, receipt, decisionNs, outputIsCurrent)
                    }
                }
                override fun cancelFeedbackForTrackPrefix(prefix: String) = this@MainActivity.riskFeedbackComponents.delivery.cancelFeedbackForTrackPrefix(prefix)
                override fun retireTerminalFeedbackForTrackPrefix(prefix: String) {
                    this@MainActivity.riskFeedbackComponents.delivery.cancelTerminalForTrackPrefix(prefix)
                }
                override fun observeLoad(nowMs: Long, normal: Boolean, completion: RuntimeLoadCompletion) =
                    observeUnknownRuntimeLoad(nowMs, normal, auxiliaryCompletion = completion)
            } },
        onMain = { runOnUiThread(it) }, invalidateObservations = ::invalidateUnknownObjectObservations,
        interaction = object : VisionUnknownPreparationInteraction {
            override fun cancelHomeWakeListening() = cancelForegroundHomeWakeListening()
            override fun closeDetector() = closeDetectorAsync()
