    private fun createPrimaryCameraFallbackDetectorWorker() = PrimaryCameraFallbackDetectorWorker<Int>(
        primaryDetectorOwner, primaryDetectorInvocationWorker,
        object : PrimaryFallbackWorkAuthority<Int> {
            override fun obstacleFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
            override fun captureIsCurrent(epoch: WalkRuntimeEpoch, fallbackGeneration: Int) = isActivityForeground &&
                isCameraFallbackLeaseCurrent(epoch, fallbackGeneration, requireRunning = true)
            override fun captureDeliveryOwner() = feedbackLifecycleGeneration
            override fun cameraOutputsAllowed() = cameraEnvironmentOutputsAllowed()
            override fun completionIsCurrent(epoch: WalkRuntimeEpoch, fallbackGeneration: Int,
                deliveryOwner: Int, detectorGeneration: Int) =
                isCameraFallbackLeaseCurrent(epoch, fallbackGeneration, requireRunning = true) &&
                    deliveryOwner == feedbackLifecycleGeneration && isCurrentFrameGeneration(detectorGeneration, epoch) &&
                    cameraEnvironmentOutputsAllowed() && isActivityForeground
            override fun advisoryGate(nowElapsedRealtimeMs: Long) = currentCameraFallbackAdvisoryGate(nowElapsedRealtimeMs)
            override fun tactileTier(gate: NonMetricAdvisoryGate) = resolveAndroidLocalTactileTier(gate)
        }, object : PrimaryFallbackFrameObservation {
            override fun load(timestampNs: Long, observedAtElapsedRealtimeMs: Long) {
                runtimeCameraFrameBudgetMs = null
                runtimeLoadFrameScope = RuntimeFeatureScope.CAMERA_TRACKING
                runtimeLoadNormalFrameAtMs = if (cameraEnvironmentOutputsAllowed()) observedAtElapsedRealtimeMs else null
                runtimeLoadObservationSource.recordFrame(timestampNs, observedAtElapsedRealtimeMs,
                    null, null, null, runtimeLoadEnvironmentKey())
                observeRuntimeInferenceLoad(inputObserved = true)
            }
            override fun luma(epoch: WalkRuntimeEpoch, observedAtElapsedRealtimeMs: Long, width: Int, height: Int,
                bytes: ByteBuffer?, rowStride: Int?, pixelStride: Int?) = observeOfficialEnvironmentCameraFrame(
                cameraFrameQualityObservation(epoch = epoch, observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                    frameAvailable = true, width = width, height = height, yPlaneBuffer = bytes,
                    yPlaneRowStride = rowStride, yPlanePixelStride = pixelStride))
            override fun observe(observation: CameraFrameQualityObservation) { observeOfficialEnvironmentCameraFrame(observation) }
            override fun approvedProfile() = activeCameraFrameQualityProfile
        }, detectorRuntimeSupervisor, primaryWorkerTimingEffects,
        object : PrimaryFallbackRecording<Int> {
            override fun analyzed(epoch: WalkRuntimeEpoch, fallbackGeneration: Int, deliveryOwner: Int) {
                recordCameraFallbackFrameAnalyzedOnce(epoch, fallbackGeneration, deliveryOwner)
            }
            override fun completed(event: PrimaryCompletedInference) { recordPrimaryCompletedInference(event) }
            override fun sample(result: AndroidDetectionResult, tier: AndroidLocalTactileTier,
                gate: NonMetricAdvisoryGate, observedAtElapsedRealtimeMs: Long) {
                recordCameraFallbackInferenceSample(result, tier, gate, observedAtElapsedRealtimeMs)
            }
        }, nonMetricAdvisoryPolicy, primaryWorkerCompletion,
        PrimaryFallbackPresentation { action, epoch, generation, deliveryOwner ->
            cameraAdvisoryDelivery.dispatch(action, epoch, generation, deliveryOwner)
        }, { runOnUiThread(it) }, SystemClock::elapsedRealtime,
    )

