    private val postLoginDeviceCheckController by lazy(LazyThreadSafetyMode.NONE) { createPostLoginDeviceCheckController() }

    private val postLoginDeviceCheckBindingFactory by lazy(LazyThreadSafetyMode.NONE) {
        AndroidPostLoginDeviceCheckBindingFactory(applicationContext) {
            if (!::startupCapabilityProbe.isInitialized || !::gatewaySessionStore.isInitialized) null else {
                val installationId = gatewaySessionStore.getOrCreateInstallDeviceId()
                if (installationId == null) null else {
                    val startup = startupCapabilityProbe.snapshot()
                    val environment = activeEnvironmentProfiles
                    val profile = startupCapabilityProbe.deviceProfileMatch()
                    PostLoginDeviceCheckBindingFacts(
                        installationId, startup, environment?.bundleId, environment?.revision,
                        profile.profileId, profile.profileVersion,
                        requiredPostLoginDeviceCheckPermissions().toSet(),
                        isLocationServiceEnabledForDeviceCheck(), isHandsFreeVoiceDisclosureAccepted(),
                    )
                }
            }
        }
    }

    private fun capturePostLoginDeviceCheckActorFacts(): PostLoginDeviceCheckActorFacts {
        val process = GatewaySessionProcessCoordinator.snapshot()
        val session = process.session
        val verifiedActor = if (firstRunOnboardingController.initialized) firstRunOnboardingSnapshot.verifiedActorBinding?.value else null
        return PostLoginDeviceCheckActorFacts(
            foreground = isActivityForeground,
            actorId = session?.actorId,
            sessionGeneration = session?.let { process.generation },
            verifiedActorId = verifiedActor,
            sessionVerified = session?.verificationState == GatewaySessionVerificationState.VERIFIED,
            sessionUsable = session?.let { it.isUsableFor(it.actorId) } == true,
            storageBlocked = process.storageBlocked,
            deletionRecoveryOnly = process.deletionRecoveryOnly,
            quickStartSessionUsable = developmentQuickStartEnabled && this@MainActivity.developmentQuickStartController.developmentQuickStartSessionOrNull() != null,
        )
    }

    private fun createPostLoginDeviceCheckController(): PostLoginDeviceCheckController {
        val reader = AndroidPostLoginDeviceCheckFactsReader(
            context = applicationContext,
            actorSource = ::capturePostLoginDeviceCheckActorFacts,
            startupSource = { startupCapabilityProbe.snapshot() },
            resourceSource = { walkSessionResourceProbe.snapshot() },
            detectorSource = {
                PostLoginDeviceCheckDetectorFacts(primaryDetectorLifecycleController.metadata().loadAttempted, primaryDetectorLifecycleController.metadata().loadInFlight,
                    primaryDetectorLifecycleController.metadata().configLoaded, primaryDetectorOwner.projection().available,
                    when {
                        !primaryDetectorLifecycleController.metadata().loadAttempted || primaryDetectorLifecycleController.metadata().loadInFlight -> PostLoginDeviceCheckSignal.PENDING
                        primaryDetectorLifecycleController.metadata().configLoaded && primaryDetectorOwner.projection().available -> RunningDetectorReadiness.deviceCheckSignal(primaryDetectorLifecycleController.verificationState(primaryDetectorOwner.projection().detector))
                        else -> PostLoginDeviceCheckSignal.UNAVAILABLE
                    })
            },
            voiceSource = { PostLoginDeviceCheckVoiceFacts(handsFreeVoiceModelPreparationFailed,
                onDeviceSpeechRecognitionCapabilityOverride, offlineKoreanTextToSpeechCapabilityOverride) },
            voiceDisclosureAccepted = ::isHandsFreeVoiceDisclosureAccepted,
            resultBindingSource = postLoginDeviceCheckBindingFactory::create,
        )
        return PostLoginDeviceCheckController(
            facts = reader,
            savedResults = AndroidPostLoginDeviceCheckSavedResults { if (::postLoginDeviceCheckResultStore.isInitialized) postLoginDeviceCheckResultStore else null },
            probes = postLoginDeviceProbes,
            permissions = object : PostLoginDeviceCheckPermissionPort {
                override fun acknowledgeVoiceDisclosure() = acknowledgeHandsFreeVoiceDisclosure()
                override fun requestedPermissions() = requestedPostLoginDeviceCheckPermissions()
                override fun request(binding: PostLoginDeviceCheckBinding, permissions: List<String>) = requestPermissionsWithLease(permissions.toTypedArray(), PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK)
                override fun cancel(requestCode: Int) { permissionFlowController.cancelRequest(requestCode) }
                override fun ownsDialog(requestCode: Int) = permissionFlowController.ownsRequest(requestCode)
            },
            effects = object : PostLoginDeviceCheckEffects {
                private var jitPermissionObservationBinding: PostLoginDeviceCheckBinding? = null
                override fun invalidateRouteResponseLease() = invalidateRouteSnapshotResponseLease()
                override fun invalidateSpeechStorageLease() = invalidateSpeechOutputStorageBinding()
                override fun applyCapabilityOverrides(overrides: PostLoginDeviceCheckCapabilityOverrides) {
                    runtimeMetricSession.restoreCapability(overrides.metricDistance)
                    runtimeObstacleDetectionCapabilityOverride = overrides.obstacleDetection
                    onDeviceSpeechRecognitionCapabilityOverride = null
                    voiceInputController.clearTranscriberFailureHistory()
                    offlineKoreanTextToSpeechCapabilityOverride = overrides.koreanSpeech
                }
                override fun clearAttemptPresentation() {
                    postLoginDeviceCheckLastLiveStatus = null
                    if (nativeUiPublication.isPublished(NativeUiPublication.Target.POST_LOGIN_DEVICE_CHECK_LIVE_STATUS_TEXT)) {
                        firstRunOnboardingPresenter.readinessBinding().postLoginDeviceCheckLiveStatusText.accessibilityLiveRegion = View.ACCESSIBILITY_LIVE_REGION_POLITE
                        firstRunOnboardingPresenter.readinessBinding().postLoginDeviceCheckLiveStatusText.text = ""
                        firstRunOnboardingPresenter.readinessBinding().postLoginDeviceCheckLiveStatusText.visibility = View.GONE
                    }
                }
                override fun showStatus(title: String, detail: String) = updateStatus(title, detail)
                override fun announceTerminal(message: String) = this@MainActivity.postLoginDeviceInteraction.announcePostLoginDeviceCheckTerminal(message)
                override fun failureMessage(failure: PostLoginDeviceCheckFailure?) = postLoginDeviceCheckFailureMessage(failure)
                override fun refreshReadinessPresentation() { if (nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_CAPABILITY_TEXT)) refreshStartupCapabilityUi() }
                override fun noteCancellation(reason: String) { if (nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_CAPABILITY_TEXT)) updateNavigationStatus("postLoginDeviceCheck=cancelled reason=$reason") }
                override fun recordPermissionObservation(binding: PostLoginDeviceCheckBinding): Boolean {
                    jitPermissionObservationBinding = null
                    if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 && firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION) {
                        if (!firstRunOnboardingController.recordEmailPermissionObservation()) return false
                        jitPermissionObservationBinding = binding
                    }
                    return true
                }
                override fun afterPermissionObservation(binding: PostLoginDeviceCheckBinding) {
                    if (jitPermissionObservationBinding == binding) {
                        jitPermissionObservationBinding = null
                        onFirstRunOnboardingStateChanged("권한 상태를 확인했습니다. 이제 기기 기능을 점검합니다.")
                    }
                }
                override fun afterPassed(snapshot: PostLoginDeviceCheckSnapshot): PostLoginDeviceCheckPassContinuation {
                    val lifecycleGeneration = feedbackLifecycleGeneration
                    val isCurrent = {
                        isFeedbackLifecycleCurrent(lifecycleGeneration) &&
                            postLoginDeviceCheckController.isPassedSnapshotCurrent(snapshot)
                    }
                    if (!isCurrent()) return PostLoginDeviceCheckPassContinuation.TRANSITION_REJECTED
                    speechOutputController.restartFailedActuatorAfterDeviceCheck(isCurrent)
                    if (!isCurrent()) return PostLoginDeviceCheckPassContinuation.TRANSITION_REJECTED
                    return this@MainActivity.actorSessionLifecycleCoordinator.completePostLoginDeviceCheckPassEffects(snapshot)
                }
                override fun afterRestoredResult() {
                    if (advanceEmailStagesWithRestoredDeviceCheck()) onFirstRunOnboardingStateChanged(
                        announcement = "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요.", preservePostLoginDeviceCheck = true)
                }
                override fun scheduleCalibration() = scheduleDeviceRuntimeCalibration()
                override fun metricCapabilityChanged(available: Boolean) { runtimeMetricSession.restoreCapability(available) }
                override fun clearCameraCapabilityOverrides() { runtimeMetricSession.restoreCapability(null); runtimeObstacleDetectionCapabilityOverride = null }
                override fun prepareDetectorRetry() { primaryDetectorLifecycleController.allowLoadRetryIfUnavailable() }
            },
            scheduler = object : PostLoginDeviceCheckScheduler {
                override fun schedule(delayMs: Long, action: () -> Unit): DeviceCheckScheduledTask {
                    val scheduled = Runnable(action)
                    firstRunOnboardingPresenter.readinessBinding().startupCapabilityText.postDelayed(scheduled, delayMs)
                    return DeviceCheckScheduledTask { if (nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_CAPABILITY_TEXT)) firstRunOnboardingPresenter.readinessBinding().startupCapabilityText.removeCallbacks(scheduled) }
                }
            },
            config = PostLoginDeviceCheckController.Config(POST_LOGIN_DEVICE_CHECK_TIMEOUT_MS,
                developmentQuickStartEnabled, developmentPostLoginDeviceCheckBypassed),
        )
    }
