    private val postLoginDeviceProbesHolder: Lazy<AndroidPostLoginDeviceProbes> = lazy {
        val uiDispatcher = object : PostLoginProbeDispatcher {
            override fun post(action: Runnable) { runOnUiThread(action) }
            override fun schedule(delayMs: Long, action: Runnable): DeviceCheckScheduledTask {
                firstRunOnboardingPresenter.readinessBinding().startupCapabilityText.postDelayed(action, delayMs)
                return DeviceCheckScheduledTask { firstRunOnboardingPresenter.readinessBinding().startupCapabilityText.removeCallbacks(action) }
            }
        }
        val releaseDispatcher = object : PostLoginProbeDispatcher {
            override fun post(action: Runnable) { cameraReleaseHandler.post(action) }
            override fun schedule(delayMs: Long, action: Runnable): DeviceCheckScheduledTask {
                cameraReleaseHandler.postDelayed(action, delayMs)
                return DeviceCheckScheduledTask { cameraReleaseHandler.removeCallbacks(action) }
            }
        }
        AndroidPostLoginDeviceProbes.android(
            context = this,
            locationClient = { if (::fusedLocationClient.isInitialized) fusedLocationClient else null },
            detector = { primaryDetectorOwner.projection().detector }, detectorExecutor = primaryDetectorOwner.nativeLane,
            mainExecutor = ContextCompat.getMainExecutor(this), displayRotation = ::displayRotation,
            dispatcher = uiDispatcher, cameraReleaseDispatcher = releaseDispatcher,
            awaitCameraClosed = ::awaitCameraXClosed,
            elapsedRealtimeMs = SystemClock::elapsedRealtime,
            environment = { PostLoginProbeEnvironment(
                locationPermission = hasLocationPermission(),
                locationServiceEnabled = isLocationServiceEnabledForDeviceCheck(),
                cameraPermission = hasCameraPermission(), detectorAvailable = primaryDetectorOwner.projection().available,
                otherCameraOwnerBusy = officialEnvironmentCameraPreflightActive ||
                    officialEnvironmentCameraCleanupPending || cameraFallbackCleanupPending ||
                    cameraFallbackRequested || cameraFallbackRunning ||
                    arSessionOwner.observe().purpose != ArSessionPurpose.NONE || arSessionOwner.observe().session != null,
            ) },
            currentBinding = { postLoginDeviceCheckSnapshot.bindingOrNull },
            isCurrent = ::isPostLoginDeviceCheckBindingCurrent,
            uiAlive = { nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_CAPABILITY_TEXT) && !isFinishing && !isDestroyed },
            sharedReleaseBlocked = { cameraXReleaseBlocked },
            markSharedReleaseBlocked = { cameraFallbackController.markReleaseBlocked() },
            modelDirectory = { handsFreeVoiceModelDirectory },
            modelPreparationFailed = { handsFreeVoiceModelPreparationFailed },
            voiceOutputSuppressed = ::isHandsFreeVoiceOutputActive,
            stopVoiceService = ::stopHandsFreeVoiceService,
            support = object : PostLoginProbeRuntimeSupport {
                override val capabilityProbeStarted get() = startupCapabilityProbeStarted
                override fun restartCapabilityAndResources(binding: PostLoginDeviceCheckBinding, onChanged: () -> Unit) {
                    if (::startupCapabilityProbe.isInitialized) privacyStartupResources.releaseOnUiThread(startupCapabilityProbe)
                    startupCapabilityProbe = privacyStartupResources.acquireOnUiThread(create = { AndroidStartupCapabilityProbe(this@MainActivity) {
                        completeVoiceDataInstallRecheckIfPossible()
                        onChanged()
                    } }, release = { it.close() })
                    startupCapabilityProbeStarted = false
                    resetWalkSessionResourceProbe()
                }
                override fun prepareVoiceModelAndDetector() {
                    prepareHandsFreeVoiceModel()
                    loadDetectorForPostLoginDeviceCheck()
                }
                override fun startAutomaticProbes(binding: PostLoginDeviceCheckBinding) {
                    maybeStartFirstRunDeviceCheckProbes()
                }
                override fun startMetricPreflight(binding: PostLoginDeviceCheckBinding) {
                    beginRuntimeMetricPreflight()
                }
                override fun cancelCalibration(reason: String) { cancelDeviceRuntimeCalibration(reason) }
                override fun cancelMetricPreflight(reason: String) {
                    if (postLoginMetricPreflightStarted || metricPreflightPostLoginBinding != null ||
                        arSessionOwner.observe().purpose == ArSessionPurpose.PREFLIGHT) this@MainActivity.runtimeMetricInvalidation.invalidate(reason)
                    else runtimeMetricSession.clearPreflightBinding()
                }
                override fun closeCapabilityAndResetResources() {
                    if (::startupCapabilityProbe.isInitialized && startupCapabilityProbeStarted) {
                        privacyStartupResources.releaseOnUiThread(startupCapabilityProbe)
                        startupCapabilityProbeStarted = false
                    }
                    if (::walkSessionResourceProbe.isInitialized && walkSessionResourceProbeStarted)
                        resetWalkSessionResourceProbe()
                }
                override fun mayValidateStoredBinding() = ::startupCapabilityProbe.isInitialized &&
                    ::postLoginDeviceCheckResultStore.isInitialized
                override fun startStoredBindingValidation(onChanged: () -> Unit): Boolean {
                    privacyStartupResources.releaseOnUiThread(startupCapabilityProbe)
                    startupCapabilityProbe = privacyStartupResources.acquireOnUiThread(create = { AndroidStartupCapabilityProbe(this@MainActivity) {
                        completeVoiceDataInstallRecheckIfPossible()
                        startupCapabilityCoordinator.refreshAfterStoredBindingProbeChanged(onChanged)
                    } }, release = { it.close() })
                    startupCapabilityProbeStarted = true
                    if (runCatching { startupCapabilityProbe.start() }.isFailure) {
                        startupCapabilityProbeStarted = false
                        privacyStartupResources.releaseOnUiThread(startupCapabilityProbe)
                        return false
                    }
                    return true
                }
                override fun mayStartStoredMetricRefresh(binding: PostLoginDeviceCheckBinding) =
                    metricPreflightOwner == RuntimeMetricPreflightOwner.NONE && isActivityForeground &&
                        !isFinishing && !isDestroyed && nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_METRIC_PREFLIGHT_BUTTON) &&
                        hasCameraPermission() && !isWalkSessionRuntimeActive() &&
                        !runtimeCameraStartBlockedByAnotherOwner() && arSessionOwner.observe().session == null &&
                        arSessionOwner.observe().purpose == ArSessionPurpose.NONE
                override fun startStoredMetricRefresh(binding: PostLoginDeviceCheckBinding) {
                    runtimeMetricSession.beginStoredDepthRefresh(binding)
                }
            },
            observer = object : PostLoginProbeObserver {
                override fun changed() { refreshStartupCapabilityUi() }
                override fun continueCheck(binding: PostLoginDeviceCheckBinding) { maybeContinuePostLoginDeviceCheck(binding) }
                override fun evaluateCheck(binding: PostLoginDeviceCheckBinding) { evaluatePostLoginDeviceCheck(binding) }
                override fun navigationDiagnostic(message: String) { updateNavigationStatus(message) }
                override fun locationDiagnostic(decision: DeviceCheckLocationFixDecision) {
                    if (BuildConfig.DEBUG) android.util.Log.d(GPS_PREFLIGHT_LOG_TAG,
                        "reason=${decision.reason} accuracyMeters=${decision.accuracyMeters} ageMs=${decision.ageMs}")
                }
                @SuppressLint("ApplySharedPref")
                override fun locationTerminal(result: String, reason: String, accuracyBucket: String, ageBucket: String) {
                    if (::stepLengthPrefs.isInitialized) stepLengthPrefs.edit()
                        .putString(PREF_DEVICE_CHECK_LOCATION_RESULT, result)
                        .putString(PREF_DEVICE_CHECK_LOCATION_REASON, reason)
                        .putString(PREF_DEVICE_CHECK_LOCATION_ACCURACY_BUCKET, accuracyBucket)
                        .putString(PREF_DEVICE_CHECK_LOCATION_AGE_BUCKET, ageBucket).commit()
                    if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent(
                        "post_login_location_check_terminal", mapOf("result" to result, "reason" to reason,
                            "accuracy_bucket" to accuracyBucket, "age_bucket" to ageBucket))
                }
                override fun cameraSamplingFailure(generation: Long, attempts: Int, passes: Int, failure: PostLoginCameraPipelineFailure) {
                    if (BuildConfig.DEBUG) android.util.Log.d(CAMERA_PREFLIGHT_LOG_TAG,
                        "postLogin generation=$generation attempts=$attempts passes=$passes reason=$failure")
                }
                override fun wakeReady() {
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.WAKE_UI_READY, backend = OfflineSpeechEngine.VOSK)
                }
                override fun wakeResult(result: VoskWakePhraseProbeResult) {
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.WAKE_UI_RESULT, backend = OfflineSpeechEngine.VOSK,
                        matched = result.availability == VoskWakePhraseProbeAvailability.AVAILABLE,
                        failure = result.failure, streamingError = result.streamingError)
                }
                override fun announceProgress(message: String) { this@MainActivity.postLoginDeviceInteraction.announcePostLoginDeviceCheckProgress(message) }
            },
        )
    }
