                override fun postResumeActivation(epoch: WalkRuntimeEpoch) { statusText.post { completePendingWalkSessionResumeActivation(epoch) } }
                override fun preflightDiagnostic(observation: CameraFrameQualityObservation, assessment: CameraFrameQualityAssessment, generation: Long) {
                    if (BuildConfig.DEBUG) {
                        val profile = activeCameraFrameQualityProfile
                        android.util.Log.d(CAMERA_PREFLIGHT_LOG_TAG,
                            "generation=$generation frameAvailable=${observation.frameAvailable} brightness=${observation.normalizedBrightness} " +
                            "minimumBrightness=${profile?.minimumNormalizedBrightness} occludedFraction=${observation.occludedFraction} nearBlackFraction=${observation.nearBlackFraction} " +
                            "maximumOccludedFraction=${profile?.maximumOccludedFraction} shakeDegreesPerSecond=${observation.angularShakeDegreesPerSecond} " +
                            "maximumShakeDegreesPerSecond=${profile?.maximumAngularShakeDegreesPerSecond} mountPitchDegrees=${observation.mountPitchDegrees} " +
                            "mountPitchRange=${profile?.minimumMountPitchDegrees}..${profile?.maximumMountPitchDegrees} status=${assessment.status} reason=${assessment.reason}")
                    }
                }
                override fun updateMountingUi() { updatePhoneMountingUi() }
                override fun refreshReadinessUi() { refreshStartupCapabilityUi() }
            }, SystemClock::elapsedRealtime, { action -> runOnUiThread(action) }, { developmentGuidanceStartBypassEnabled })
    }

