    private val phoneMountingSession: PhoneMountingSessionController<PositioningMountTarget, PositioningMountObservation> by lazy(LazyThreadSafetyMode.SYNCHRONIZED) {
        PhoneMountingSessionController(
            phoneMountingObservationLock, officialEnvironmentEvidenceStore,
            MountingPreflightEvidence { officialEnvironmentPreflightController.resetCameraObservations() },
            { walkSessionLifecycle }, { activePhoneMountingProfile }, { cameraAnalysisFeaturesEnabled() },
            { developmentGuidanceStartBypassEnabled },
            { epoch -> nativePhoneMountingCheckRequest?.takeIf {
                isActivityForeground && it.actorId == reporterUserId &&
                    it.gatewayGeneration == GatewaySessionProcessCoordinator.snapshot().generation &&
                    it.checkRequest.epoch == epoch
            }?.checkRequest },
            object : MountingSensorLifecycle {
                override fun start() = phoneMountingSensorProbe.start()
                override fun stop() { phoneMountingSensorProbe.stop() }
            }, object : PositioningMountBridge<PositioningMountTarget, PositioningMountObservation> {
                override fun captureTarget() = capturePositioningMountTarget()
                override fun captureLocked(target: PositioningMountTarget?, epoch: WalkRuntimeEpoch, observedAtMs: Long,
                    phase: PhoneMountingAssessmentPhase, previousState: PhoneMountingRuntimeState?,
                    cameraOverride: CameraFrameQualityAssessment?, retryRequested: Boolean, facts: MountingPositionFacts) =
                    capturePositioningMountObservation(target, epoch, observedAtMs, phase, previousState, cameraOverride, retryRequested, facts)
                override fun invalidatedLocked(target: PositioningMountTarget, generation: Long, observedAtMs: Long) =
                    PositioningMountObservation(target, generation, null, null, null, observedAtMs)
                override fun consume(receipt: PositioningMountObservation?, receivedAtMs: Long) { observePositioningMount(receipt, receivedAtMs) }
            }, object : MountingScheduler {
                override fun postMounting(action: () -> Unit, delayMs: Long) = firstRunOnboardingPresenter.readinessBinding().phoneMountingStatusText.postDelayed({ action() }, delayMs)
                override fun postStatus(delayMs: Long, action: () -> Unit) = statusText.postDelayed({ action() }, delayMs)
            }, object : MountingEffects {
                override fun revokeReportOutputs() {
                    synchronized(reportUploadSafetyLock) {
                        reportUploadSafetyGeneration += 1L
                        reportPrivacyConsentSession.cancelActiveCalls()
                    }
                }
                override fun updateMountingUi() { updatePhoneMountingUi() }
                override fun observeUnavailableCamera(epoch: WalkRuntimeEpoch, observedAtMs: Long) {
                    observeOfficialEnvironmentCameraFrame(epoch = epoch, observedAtElapsedRealtimeMs = observedAtMs, frameAvailable = false)
                }
                override fun sensorStartFailed() {
                    updateStatus("장착 센서 시작 실패", "중력 센서를 사용할 수 없어 카메라 인식과 거리 안내를 제한합니다. 위치 품질이 확인되면 경로 안내는 계속됩니다.")
                }
                override fun cameraHandoffStarted() { officialEnvironmentRuntimeController.invalidateWatchdog() }
                override fun reassessOfficialEnvironment() { applyCurrentOfficialEnvironmentRuntimeAssessment() }
                override fun cameraHandoffTimedOut() {
                    updateStatus("런타임 카메라 연결 시간 초과", "카메라 전환 뒤 유효한 영상을 받지 못해 보행 출력을 계속 중지합니다. 카메라를 사용하는 다른 앱을 닫고 장착 상태를 다시 확인하세요.")
                }
                override fun correction(assessment: PhoneMountingAssessment, announce: Boolean) {
                    val epoch = assessment.nextState.epoch

                    if (announce) {
                        invalidatePhoneMountingDetectionOutputs(epoch)
                        this@MainActivity.reportCandidateController.clearFrameState("phone_mounting_correction")
                        this@MainActivity.riskFeedbackComponents.delivery.resetDeliveryState()
                        this@MainActivity.riskFeedbackComponents.delivery.cancelPendingFeedbackDeliveries()
                        if (!assessment.nextState.requiresExplicitCorrection) {
                            updateStatus("카메라 품질 재확인 중", "${assessment.accessibleReasonKo} ${assessment.accessibleActionKo}")
                            // The environment recheck owns its warning; GPS speech stays current.
                            return
                        }
                        cancelVoiceCommandRecognition()
                        feedbackLifecycleGeneration += 1
                        speechOutputController.closeActuator()
                        updateStatus(
                            "휴대전화 장착 교정 필요",
                            "${assessment.accessibleReasonKo} ${assessment.accessibleActionKo} " +
                                "교정 뒤 화면에서 장착 상태를 명시적으로 다시 확인하세요.",
                        )
                        ensureFeedbackActuator().playPhoneMountingCorrectionVibration()
                        speakStatusExplanation(
                            phoneMountingFailureSpeech(assessment),
                        )
                    }
                }
                override fun unusable(assessment: PhoneMountingAssessment, announce: Boolean) {
                    val epoch = assessment.nextState.epoch

                    val detail =
                        "${assessment.accessibleReasonKo} ${assessment.accessibleActionKo} " +
                            "카메라 인식·거리·위험 안내를 제한합니다. 위치 품질이 확인되면 경로 안내는 계속됩니다."
                    if (announce) {
                        invalidatePhoneMountingDetectionOutputs(epoch)
                        updateStatus("휴대전화 장착 · 카메라 기능 제한", detail)
                        ensureFeedbackActuator().playPhoneMountingSafetyStopVibration()
                        speakStatusExplanation(phoneMountingFailureSpeech(assessment))
                    }
                }
                override fun invalidated(reason: String) {
                    if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("phone_mounting_evidence_invalidated", mapOf("reason" to reason))
                    if (nativeUiPublication.isPublished(NativeUiPublication.Target.PHONE_MOUNTING_STATUS_TEXT)) updatePhoneMountingUi()
                }
            }, SystemClock::elapsedRealtime, RUNTIME_CAMERA_HANDOFF_TIMEOUT_MS,
        )
    }

