        }
        val producers = WalkReadinessProducers(
            FirstRunReadinessProducer(::firstRunOnboardingComplete, { firstRunOnboardingSnapshot.stage }),
            PriorityWalkReadinessProducer({ priorityUserOnboardingPolicy }, ::currentPriorityUserSupportEnvironment,
                ::isWalkSessionRuntimeActive, { developmentQuickStartEnabled }, ::currentReporterUserId),
            PermissionReadinessProducer(::currentObservedPermissionSnapshot, ::hasRecordAudioPermission),
            FeatureReadinessProducer(object : ReadinessFeatureAdmission {
                override fun cameraEnabled() = cameraAnalysisFeaturesEnabled()
                override fun cameraPermission() = hasCameraPermission()
                override fun locationEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
                override fun locationPermission() = hasLocationPermission()
                override fun disabledFeatures() = currentPostLoginDisabledFeatures()
                override fun restrict(decision: WalkSafeStartupCapabilityDecision) = this@MainActivity.startupCapabilityCoordinator.applyPostLoginDeviceFeatureRestrictions(decision)
            }, object : ReadinessDetector {
                override fun ensureLoadedAfterCameraGate() { loadDetectorAfterCameraGate() }
                override fun isAvailable() = primaryDetectorOwner.projection().available
                override fun loadFailureReason() = primaryDetectorLifecycleController.metadata().loadReason
                override fun modelState() = synchronized(frameStateLock) {
                    val detector = primaryDetectorOwner.observe()
                    val metadata = primaryDetectorLifecycleController.metadata()
                    ReadinessDetector.ModelState(detector.available, metadata.loadInFlight, metadata.loadReason)
                }
                override fun modelKey() = primaryDetectorLifecycleController.metadata().loadedModelKey
            }), EndpointReadinessProducer(BuildConfig.DEBUG, BuildConfig.WALKSAFE_GATEWAY_ORIGIN),
            GatewayReadinessProducer(::isGatewaySessionReadyForCurrentActor), official, mounting,
        )
        WalkReadinessCoordinator({ walkSessionLifecycle }, startupReadinessEvidence,
            object : ReadinessResourceSource {
                override fun retryFailedMonitoring() { retryFailedWalkSessionResourceMonitoring() }
                override fun snapshot() = walkSessionResourceProbe.snapshot()
                override fun recordDiagnostic(source: String, resources: WalkSessionDeviceResourceSnapshot) { logWalkSessionResourceDiagnostics(source, resources) }
            }, official, mounting, producers, { developmentGuidanceStartBypassEnabled }, SystemClock::elapsedRealtime, Build.VERSION.SDK_INT,
        )
    }

