    private val runtimeMetricInvalidation: RuntimeMetricInvalidationController<FirstRunAsyncLease, ArSessionPurpose, Session, ArCoreFrameProvider> by lazy {
        RuntimeMetricInvalidationController(
            runtimeMetricStateLock, { runtimeMetricSession }, { arSessionOwner },
            { if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle else null },
            { speechOutputController }, { this@MainActivity.riskFeedbackComponents.delivery },
            object : RuntimeMetricInvalidationStartup {
                override fun currentBinding() = postLoginDeviceCheckSnapshot.bindingOrNull
                override fun clearConfirmation() {
                    confirmedStartupCapabilityDecision = null
                    startupCapabilityConfirmationPending = false
                    startupCapabilityRetryRequiresUserAction = false
                }
                override fun invalidateAvailabilityRecheck() = invalidateArCoreAvailabilityRecheck()
                override fun refreshPublishedForegroundUi() {
                    if (nativeUiPublication.isPublished(NativeUiPublication.Target.STARTUP_CAPABILITY_TEXT) && isActivityForeground) {
                        refreshStartupCapabilityUi()
                    }
                }
            },
            object : RuntimeMetricInvalidationFallback {
                override fun hasActivity() = cameraFallbackRequested || cameraFallbackRunning ||
                    cameraFallbackCleanupPending || cameraFallbackHasCamera || cameraFallbackAfterReleasePending
                override fun clearContinuationIfInitialized() {
                    if (cameraFallbackControllerHolder.isInitialized()) cameraFallbackController.clearPendingContinuation()
                }
                override fun clearPendingStart() { pendingCameraFallbackStart = null }
                override fun stop() = stopCameraFallbackSession(updateUi = false)
                override fun moveToCreatedIfInitialized() {
                    if (cameraFallbackControllerHolder.isInitialized()) cameraFallbackController.moveTo(Lifecycle.State.CREATED)
                }
            },
            object : RuntimeMetricInvalidationNavigation {
                override fun safetyStopAndPersist() {
                    transitionWalkSession(WalkSessionEvent.SafetyStopRequested)
                    persistWalkSessionInterruptionMarker()
                }
                override fun cancelAndClearRequests() {
                    val cancellation = cancelNavigationRequestsForPause()
                    clearActiveRouteRequestState(cancellation.routeCancelled)
                    clearDestinationSearchState(cancellation.destinationSearchCancelled)
                }
                override fun resetRoute() = resetRouteState()
                override fun invalidateFrame() = invalidateFrameStateForPause()
                override fun stopLocation() { stopLocationUpdates() }
                override fun stopSteps() = stopStepTracking()
                override fun stopOrientationIfInitialized() { if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop() }
            },
            object : RuntimeMetricInvalidationVoice {
                override fun advanceFeedbackGeneration() { feedbackLifecycleGeneration += 1 }
                override fun cancelRecognition() = cancelVoiceCommandRecognition()
                override fun removeTalkBackIfPublished(task: Runnable?) {
                    if (::statusText.isInitialized) task?.let(statusText::removeCallbacks)
                }
                override fun cancelTerminalResolution() = cancelPendingFeedbackTerminalResolution()
            },
            object : RuntimeMetricInvalidationReports {
                override fun cancelPrivacyCalls() {
                    synchronized(reportUploadSafetyLock) {
                        reportUploadSafetyGeneration += 1L
                        reportPrivacyConsentSession.cancelActiveCalls()
                    }
                }
                override fun clearExplicitFrame(reason: String) = this@MainActivity.reportCandidateController.clearFrameState(reason)
                override fun recordInvalidationIfInitialized(reason: String, wasPreflight: Boolean) {
                    if (::fieldSessionLog.isInitialized && !wasPreflight) {
                        fieldSessionLog.recordEvent("runtime_metric_evidence_invalidated", mapOf("reason" to reason))
                    }
                }
            },
            object : RuntimeMetricInvalidationRenderer {
                override fun pauseForSessionClose() = pauseRendererForSessionClose()
                override fun resumeAfterSessionClose(resume: Boolean) = resumeRendererAfterSessionClose(resume)
                override fun clearNativePresentation() {
                    cameraTextureBound = false
                    arCoreSupported = false
                    depthSupported = false
                    syncActiveSessionScreenPolicy()
                }
                override fun pauseForSafetyStopIfInitialized() {
                    if (::surfaceView.isInitialized) {
                        syncGlSurfaceRenderMode(forceFrame = true)
                        surfaceView.onPause()
                    }
                }
            },
            ArSessionPurpose.PREFLIGHT, ArSessionPurpose.RUNTIME,
            { it.close() }, { it.pause() }, SystemClock::elapsedRealtime, BuildConfig.DEBUG,
            { reason -> android.util.Log.d("WalkSafeNavigation", "output=metric_evidence_invalidated reason=$reason"); Unit },
            sourceChanged = ::startUnknownRuntimeForWalk,
        )
    }

