    private val runtimeMetricSession: RuntimeMetricSessionController<FirstRunAsyncLease, ArSessionPurpose, Session> by lazy {
        RuntimeMetricSessionController(
            runtimeMetricStateLock,
            object : RuntimeMetricScope {
                override val lifecycle get() = walkSessionLifecycle
                override val runtimeActive get() = isWalkSessionRuntimeActive()
                override val foreground get() = isActivityForeground
                override val finishing get() = isFinishing
                override val destroyed get() = isDestroyed
                override val onboardingComplete get() = firstRunOnboardingComplete()
                override val cameraOutputsAllowed get() = cameraEnvironmentOutputsAllowed()
                override val mountingOutputsAllowed get() = phoneMountingOutputsAllowed
                override val metricDistanceAllowed get() = startupCapabilityDecision?.allowsMetricDistance()
                override val startupConfirmed get() = isStartupCapabilityConfirmed()
                override val profile get() = activeEnvironmentProfiles?.runtimeMetric
                override val feedbackGeneration get() = feedbackLifecycleGeneration
            },
            object : RuntimeMetricNativePort<ArSessionPurpose, Session> {
                override val purpose get() = arSessionOwner.observe().purpose
                override val generation get() = arSessionOwner.observe().generation
                override val sessionPresent get() = arSessionOwner.observe().session != null
                override val providerPresent get() = arSessionOwner.observe().provider != null
                override val cleanupPending get() = runtimeArSessionCleanupPending()
                override fun observe() = captureRuntimeArObservation().asMetricObservation()
                override fun preflightDiagnostics() = arSessionOwner.observe().provider?.preflightDiagnostics() ?: "not_started"
                override fun detachCompletedPreflight() = arSessionOwner.detachCompletedPreflight()
                override fun finishDetachedPreflight(currentSession: Session?) {
                    val resumeRenderer = pauseRendererForSessionClose()
                    if (currentSession != null) {
                        runCatching { currentSession.pause() }
                        currentSession.close()
                    }
                    cameraTextureBound = false
                    arCoreSupported = false
                    depthSupported = false
                    syncActiveSessionScreenPolicy()
                    resumeRendererAfterSessionClose(resumeRenderer)
                }
            },
            object : RuntimeMetricDeviceChecks<FirstRunAsyncLease> {
                override val probeAvailable get() = ::startupCapabilityProbe.isInitialized
                override val firstRunAllowsPreflight get() = firstRunDeviceCheckAllowsPreflight()
                override val cameraResourceConflict get() = this@MainActivity.postLoginDeviceProbes.cameraActive ||
                    this@MainActivity.postLoginDeviceProbes.cameraCleanupPending || postLoginDeviceProbes.hasCamera ||
                    cameraFallbackCleanupPending || cameraFallbackHasCamera || cameraXReleaseBlocked
                override val fieldSessionActive get() = ::fieldSessionLog.isInitialized && isFieldSessionActive()
                override val snapshot get() = postLoginDeviceCheckSnapshot
                override val onboardingMayEnterWalk get() = firstRunOnboardingController.initialized && firstRunOnboardingSnapshot.mayEnterWalk
                override val depthState get() = postLoginMetricDepthState
                override val cameraChecksDeferred get() = postLoginCameraDependentChecksDeferred
                override val storedRefreshPending get() = storedMetricDepthRefreshPending
                override fun startupInput() = startupCapabilityProbe.snapshot()
                override fun bindingCurrent(binding: PostLoginDeviceCheckBinding) = isPostLoginDeviceCheckBindingCurrent(binding)
                override fun bindingLive(binding: PostLoginDeviceCheckBinding) = isPostLoginDeviceCheckSnapshotBindingLive(binding)
                override fun firstRunLease() = currentFirstRunAsyncLease()
                override fun firstRunLeaseCurrent(lease: FirstRunAsyncLease) = isFirstRunAsyncLeaseCurrent(lease)
                override fun storedRefreshCurrent(binding: PostLoginDeviceCheckBinding) = storedMetricDepthRefreshContext?.let {
                    it.binding == binding && isStoredMetricDepthRefreshContextCurrent(it)
                } == true
                override fun setPreflightStarted(started: Boolean) { postLoginDeviceProbes.setMetricPreflightStarted(started) }
                override fun restoreDepth(state: PostLoginMetricDepthState) { postLoginDeviceProbes.restoreMetricDepth(state) }
                override fun continueDeviceCheck(binding: PostLoginDeviceCheckBinding) { maybeContinuePostLoginDeviceCheck(binding) }
                override fun completeStoredRefresh(available: Boolean?, binding: PostLoginDeviceCheckBinding) = completeStoredMetricDepthRefresh(available, binding)
                override fun profileMatch() = startupCapabilityProbe.deviceProfileMatch()
                override fun persistResult(result: RuntimeMetricPreflightResult, profileMatch: ApprovedDeviceProfileMatch) {
                    this@MainActivity.runtimeMetricPreflightStore.persist(result, profileMatch)
                }
            },
            object : RuntimeMetricEffects {
                override val cameraPermission get() = hasCameraPermission()
                override val explainCameraPermission get() = shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)
                override val debug get() = BuildConfig.DEBUG
                override fun clearStartupConfirmation() {
                    confirmedStartupCapabilityDecision = null
                    startupCapabilityConfirmationPending = false
                }
                override fun refreshStartupUi() { refreshStartupCapabilityUi() }
                override fun requestCameraPermission() {
                    requestPermissionsWithLease(arrayOf(Manifest.permission.CAMERA), PermissionRequestPurpose.METRIC_PREFLIGHT_CAMERA)
                }
                override fun startNativePreflight(generation: Long, lifecycleGeneration: Int) { this@MainActivity.runtimeMetricPreflight.startRuntimeMetricPreflight(generation, lifecycleGeneration) }
                override fun status(status: String, detail: String) { updateStatus(status, detail) }
                override fun postToUi(action: () -> Unit) { runOnUiThread(action) }
                override fun startNavigationServices() { startNavigationServicesIfNeeded() }
                override fun cameraFrameUnavailable(epoch: WalkRuntimeEpoch, observedAtMs: Long) {
                    observeOfficialEnvironmentCameraFrame(epoch, observedAtMs, frameAvailable = false)
                }
                override fun runtimeMetricLost(expectedArGeneration: Long) { this@MainActivity.runtimeMetricPreflight.handleRuntimeMetricLoss(expectedArGeneration) }
                override fun clearReportFrame(reason: String) { this@MainActivity.reportCandidateController.clearFrameState(reason) }
                override fun debug(tag: String, message: String) { android.util.Log.d(tag, message) }
                override fun info(tag: String, message: String) { android.util.Log.i(tag, message) }
            },
            ArSessionPurpose.NONE, ArSessionPurpose.PREFLIGHT, ArSessionPurpose.RUNTIME,
            RUNTIME_METRIC_STALE_TIMEOUT_MS, SystemClock::elapsedRealtime,
        )
    }

