    private var depthSupported = false
    private val primaryDetectorLifecycleController by lazy {
        PrimaryDetectorLifecycleController(frameStateLock, primaryDetectorOwner, primaryRuntimeCalibrationOwner,
            { frameSynthesisOwner }, detectorRuntimeSupervisor,
            object : PrimaryLifecycleCurrentness {
                override fun destroyed() = isDestroyed
                override fun foreground() = isActivityForeground
                override fun frameIsCurrent(generation: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(generation, epoch)
                override fun epochIsCurrent(epoch: WalkRuntimeEpoch) = walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
            }, object : PrimaryModelConfiguration {
                override fun loadOrCurrent() = reportRuntimeConfig ?: loadReportRuntimeConfig().also { reportRuntimeConfig = it }
                override fun current() = reportRuntimeConfig
                override fun sha256() = reportModelConfigSha256
            }, AndroidPrimaryLifecyclePlatform { applicationContext },
            object : PrimaryPreparationInteraction {
                override fun metricDistanceEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)
                override fun walkRuntimeActive() = isWalkSessionRuntimeActive()
                override fun featureGatePassed() = postLoginDeviceCheckSnapshot.passesFeatureGate
                override fun progress(message: String) {
                    if (postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING) updateStatus("객체 인식 실행 방식 준비", message)
                }
                override fun modelUnavailable(metricDistanceWasEnabled: Boolean) {
                    runtimeObstacleDetectionCapabilityOverride = false
                    if (metricDistanceWasEnabled) runtimeMetricSession.restoreCapability(false)
                }
                override fun modelVerified() { maybeContinuePostLoginDeviceCheck(); refreshStartupCapabilityUi() }
                override fun loaded() { maybeContinuePostLoginDeviceCheck(); refreshStartupCapabilityUi(); prepareRuntimeServices() }
                override fun disableUnverifiedCapabilities() {
                    if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)) runtimeMetricSession.restoreCapability(false)
                    runtimeObstacleDetectionCapabilityOverride = false
                }
                override fun activeOrPausedWalk() = ::walkSessionLifecycle.isInitialized &&
                    walkSessionLifecycle.snapshot().state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
                override fun showVerificationFailure(walking: Boolean) {
                    if (::debugBboxOverlay.isInitialized) debugBboxOverlay.clear()
                    if (::statusText.isInitialized) updateStatus(
                        if (walking) "객체 탐지 모델 확인 실패 · 안전 중지" else "객체 탐지 모델 확인 실패",
                        RunningDetectorReadiness.WALK_BLOCK_NOTICE_KO)
                }
            }, object : PrimaryLifecyclePresentation {
                override fun onUi(effect: () -> Unit) = runOnUiThread(effect)
                override fun status(status: String, detail: String) = updateStatus(status, detail)
                override fun clearOverlay() = debugBboxOverlay.clear()
            }, object : PrimaryLifecycleAuxiliary {
                override fun calibrationPresent() = unknownServiceOwnerLazy.isInitialized() && unknownServiceOwner.hasCalibration
                override fun cancelCalibration(reason: String) = cancelDeviceRuntimeCalibration(reason)
                override fun releaseLoadingIfInitialized() { if (unknownServiceOwnerLazy.isInitialized()) unknownServiceOwner.releaseLoadingIfPresent() }
                override fun closeActiveOrInvalidateObservations() {
                    if (unknownServiceOwnerLazy.isInitialized()) unknownServiceOwner.closeActiveForDetector()
                    else invalidateUnknownObjectObservations()
                }
            }, object : PrimaryDetectorFailureEffects {
                override fun developmentBypassEnabled() = developmentGuidanceStartBypassEnabled
                override fun observeSafetyFailure(epoch: WalkRuntimeEpoch, observedAtMs: Long): Boolean {
                    val decision = walkRuntimeSafetyCoordinator.observe(WalkRuntimeSafetyObservation(epoch = epoch,
                        observedAtElapsedRealtimeMs = observedAtMs, riskTrusted = false))
                    return !decision.safetyOutputsAllowed && decision.epoch == epoch
                }
                override fun resetVisualTracking() = resetVisualTrackingState()
                override fun enterSafetyStop() = enterWalkSessionSafetyStopAndCancelOutputs("detector_runtime_failed")
                override fun stopCameraFallback() = stopCameraFallbackSession(updateUi = false)
                override fun stopDepthSession() { this@MainActivity.stopDepthSession(closeSession = true) }
                override fun blockReportCandidates() = reportCandidateController.setStatus("reportCandidate=blocked:camera_non_metric_unavailable")
                override fun showDetectorUnavailable() {
                    setActionButton("카메라 보조 경고 사용 불가", ActionMode.START, enabled = false)
                    updateStatus(if (developmentGuidanceStartBypassEnabled) "객체 탐지 중지" else "객체 탐지 중지 · 안전 중지",
                        if (developmentGuidanceStartBypassEnabled) "객체 탐지를 실행하지 못했습니다. 길안내 테스트는 계속합니다."
                        else "detector 실행 오류로 보행 기능을 안전 중지했습니다.")
                }
            }, object : PrimaryNativeFlightScheduler {
                override fun postDelayed(task: Runnable, delayMs: Long) = detectorWatchdogHandler.postDelayed(task, delayMs)
                override fun remove(task: Runnable) { detectorWatchdogHandler.removeCallbacks(task) }
            }, SystemClock::elapsedRealtime)
    }



    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        permissionFlowController.restoreInitialAppPermissionReRequestedThisLaunch(
            savedInstanceState?.getBoolean(STATE_INITIAL_APP_PERMISSION_RE_REQUESTED, false) == true
        )
        BoundedRuntimeDiagnosticLog.initialize(applicationContext)
        userReportInteractionOwner.restoreStatusFilter(savedInstanceState?.getString(STATE_USER_REPORT_STATUS_FILTER))
        accountDeletionActivityLease = accountDeletionProcessCoordinator.attach()
        gatewayWalkRenewalHandler = Handler(Looper.getMainLooper())
        walkBackDispatcher = OnBackPressedDispatcher { finishAfterTransition() }
        walkBackDispatcher.addCallback(walkScreenBackCallback)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            walkBackDispatcher.setOnBackInvokedDispatcher(onBackInvokedDispatcher)
        }
        firstRunOnboardingController.initializeEmailAccount(SystemClock.elapsedRealtimeNanos().coerceAtLeast(1L))
        stepLengthPrefs = getSharedPreferences("walksafe", MODE_PRIVATE)
        postLoginDeviceCheckResultStore = AndroidDeviceCheckResultStore(stepLengthPrefs)
        initializeRouteSnapshotOnIoWorker()
        accountDeletionRecoveryStore.bindIntentFence(AccountDeletionIntentFence(
            read = {
                runCatching {
                    val values = stepLengthPrefs.all
                    if (!values.containsKey(PREF_ACCOUNT_DELETION_INTENT_FENCE)) {
                        false
                    } else {
                        (values[PREF_ACCOUNT_DELETION_INTENT_FENCE] as? Boolean)
                            ?.takeIf { it }
                    }
                }.getOrNull()
            },
            store = run {
                @SuppressLint("UseKtx")
                val commitFence = {
                    stepLengthPrefs.edit()
                        .putBoolean(PREF_ACCOUNT_DELETION_INTENT_FENCE, true)
                        .commit()
                }
                commitFence
            },
            clear = run {
                @SuppressLint("UseKtx")
                val clearFence = {
                    stepLengthPrefs.edit()
                        .remove(PREF_ACCOUNT_DELETION_INTENT_FENCE)
                        .commit()
                }
                clearFence
            },
        ))
        fieldSessionLog = NoopFieldSessionLog()
        networkStateProbe = AndroidNetworkStateProbe(this)
        walkSessionLifecycle = WalkSessionLifecycle(elapsedRealtimeClock = SystemClock::elapsedRealtime)
        gatewayWalkAuthorityController.reset()
        // S03-19 (FP-018-DETAIL-05): same process, same paused walk; never a process restart.
        processWalkConfigurationChangeRetention.take(SystemClock.elapsedRealtime())?.let { retained ->
            walkSessionLifecycle = retained.lifecycle
            gatewayWalkAuthorityController.adoptHeldLeaseFrom(retained.authority)
            walkContinuedAfterConfigurationChange = true
        }
        privacyStartupResources.prepareOnUiThread {
            walkSessionResourceProbe = privacyStartupResources.acquireOnUiThread(
                { AndroidWalkSessionResourceProbe(this) }, { it.close() },
            )
            phoneMountingSensorProbe = privacyStartupResources.acquireOnUiThread(
                { AndroidPhoneMountingSensorProbe(this) }, { it.close() },
            )
        }
        cameraFallbackController.moveTo(Lifecycle.State.CREATED)
        setContentView(insetNativeContent(buildPrivacyStartupInspectionView()))
        startPrivacyStartupInspection(
            prepare = preparation@{
                val noBackupRoot = noBackupFilesDir
                rawCollectionRuntimeCoordinator = privacyStartupResources.acquireOnWorker(create = { RawCollectionRuntimeCoordinator(
                    // Android's private root may contain a system-managed path alias. Resolve
                    // that trusted root only; RAW children keep their no-symlink checks.
                    File(noBackupRoot.canonicalFile, "raw_collections"),
                    elapsedRealtimeMs = SystemClock::elapsedRealtime,
                    allocatableBytes = AndroidAllocatableBytes(applicationContext, noBackupRoot),
                ) }, release = { it.cancelActiveUpload() })
                privacyStartupResources.acquireOnWorker(
                    { rawCollectionTransferController }, { it.shutdownExecutor() },
                )
                initializeRawCollectionTransferController()
                // Retention must not depend on the next walk: prune once per process start.
                executeRawCollectionTask { rawCollectionRuntimeCoordinator.pruneExpired() }
                if (BuildConfig.DEBUG) initializePositionFieldRecorder()
                val fileAccountDeletionIntentAuthority =
                    FileAccountDeletionIntentAuthority(
                        File(noBackupRoot, "account_deletion_intent_authority"),
                    )
                accountDeletionRecoveryStore.bindFileAuthority(fileAccountDeletionIntentAuthority)
                accountDeletionInstallationResetController.initialize(noBackupRoot)
                accountDeletionRecoveryStore.observeAuthority(accountDeletionDualAuthority.startupState())
                accountDeletionInstallationResetController.observeJournalAtStartup()
                val legacyResetIntentAtStartup = legacyAccountDeletionResetIntentState()
                sensitivePrefs = AndroidSensitivePreferenceStore(
                    preferences = stepLengthPrefs,
                    spec = SENSITIVE_PREF_SPEC,
                    initiallyBlockedForExternalReset =
                        accountDeletionResetJournalStateAtStartup !is
                            AccountDeletionResetJournalState.Absent ||
                            legacyResetIntentAtStartup != LegacyResetIntentState.ABSENT,
                )
                gatewaySessionStore = AndroidGatewaySessionStore(stepLengthPrefs)
                initializeIntegratedConsentPersistence()
                gatewaySessionController.initializeStorage(object : GatewaySessionController.Store {
                    override fun getOrCreateInstallDeviceId() = gatewaySessionStore.getOrCreateInstallDeviceId()
                    override fun restoreBackendDevice(expectedGatewayBaseUrl: String) = gatewaySessionStore.restoreBackendDevice(expectedGatewayBaseUrl)
                    override fun isStorageBlocked() = gatewaySessionStore.isStorageBlocked()
                    override fun recoverRenewingToPendingRevocation() = gatewaySessionStore.recoverRenewingToPendingRevocation()
                    override fun restorePendingRevocation(expectedGatewayBaseUrl: String) = gatewaySessionStore.restorePendingRevocation(expectedGatewayBaseUrl)
                    override fun restoreActive(expectedGatewayBaseUrl: String) = gatewaySessionStore.restoreActive(expectedGatewayBaseUrl)
                    override fun purgeDisabled() = gatewaySessionStore.purgeDisabled()
                    override fun moveActiveToPendingRevocation(expectedVersion: GatewaySessionVersion, operationId: String) = gatewaySessionStore.moveActiveToPendingRevocation(expectedVersion, operationId)
                    override fun removeBackendDeviceIfCurrent(expectedVersion: GatewaySessionVersion) = gatewaySessionStore.removeBackendDeviceIfCurrent(expectedVersion)
                    override fun completePendingRevocation(expectedVersion: GatewaySessionVersion, operationId: String) = gatewaySessionStore.completePendingRevocation(expectedVersion, operationId)
                    override fun reserveRenewal(expectedVersion: GatewaySessionVersion, operationId: String) = gatewaySessionStore.reserveRenewal(expectedVersion, operationId)
                    override fun commitRenewal(expectedVersion: GatewaySessionVersion, operationId: String, renewedSession: GatewayFieldSession, firstRunSnapshot: FirstRunOnboardingSnapshot) = gatewaySessionStore.commitRenewal(expectedVersion, operationId, renewedSession, firstRunSnapshot)
                    override fun rollbackRenewalForRetry(expectedVersion: GatewaySessionVersion, operationId: String, reservation: kr.co.hanium.dreamup.walksafe.network.GatewayRefreshRetryReservation) = gatewaySessionStore.rollbackRenewalForRetry(expectedVersion, operationId, reservation)
                    override fun abandonRenewal(expectedVersion: GatewaySessionVersion, operationId: String) = gatewaySessionStore.abandonRenewal(expectedVersion, operationId)
                    override fun saveInitialIfAbsent(session: GatewayFieldSession, firstRunSnapshot: FirstRunOnboardingSnapshot, expectedGatewayBaseUrl: String) = gatewaySessionStore.saveInitialIfAbsent(session, firstRunSnapshot, expectedGatewayBaseUrl)
                    override fun persistGatewayOrigin(origin: String) { stepLengthPrefs.edit().putString(PREF_GATEWAY_ORIGIN_KEY, origin).apply() }
                })
                emailAccountController.initializeStorage(object : EmailAccountController.EnrollmentStorage {
                    private val store = AndroidEmailEnrollmentStore(
                        getSharedPreferences("walksafe_email_enrollment", MODE_PRIVATE),
                    )
                    override fun restore(nowEpochMs: Long, expectedOwnerBindingSha256: String) =
                        store.restore(nowEpochMs, expectedOwnerBindingSha256)
                    override fun save(partial: EmailEnrollmentPartial) = store.save(partial)
                    override fun clear() = store.clear()
                    override fun resetAfterConfirmedAccountDeletion() = store.resetAfterConfirmedAccountDeletion()
                    override fun hasUnconfirmedCreation(ownerBindingSha256: String) = store.hasUnconfirmedCreation(ownerBindingSha256)
                    override fun markCreationPending(ownerBindingSha256: String) = store.markCreationPending(ownerBindingSha256)
                    override fun clearUnconfirmedCreation(ownerBindingSha256: String) = store.clearUnconfirmedCreation(ownerBindingSha256)
                    override fun loadPendingOtpRequest() = store.loadPendingOtpRequest()
                    override fun savePendingOtpRequest(request: kr.co.hanium.dreamup.walksafe.network.PendingEmailOtpRequest) =
                        store.savePendingOtpRequest(request)
                    override fun clearPendingOtpRequest() = store.clearPendingOtpRequest()
                })
                readAccountDeletionFallbackMarkerAtStartup()
                previousProcessHadInterruptedWalk = !walkContinuedAfterConfigurationChange &&
                    stepLengthPrefs.getBoolean(PREF_WALK_SESSION_INTERRUPTED, false)
                restorePermissionRecoveryGateFromPrefs()
                metadataLogUploader = privacyStartupResources.acquireOnWorker(
                    { DebugMetadataLogUploaderFactory.create(this) }, { it.close() },
                )
                frameCaptureUploader = privacyStartupResources.acquireOnWorker(
                    { DebugFrameCaptureUploaderFactory.create(this) }, { it.close() },
                )
                prepareReportMetadataContext()
                fieldSessionLog = privacyStartupResources.acquireOnWorker(create = { if (BuildConfig.DEBUG) {
                    PersistentFieldSessionLog(
                        rootDirectory = File(filesDir, "field_sessions"),
                        deviceInfo = FieldSessionDeviceInfo(
                            model = Build.MODEL,
                            androidVersion = Build.VERSION.RELEASE,
                            appVersionName = BuildConfig.VERSION_NAME,
                            sourceCommit = BuildConfig.WALKSAFE_SOURCE_COMMIT,
                            apkSha256 = reportApkSha256,
                            modelConfigSha256 = reportModelConfigSha256,
                        ),
                        initiallyBlockedForAccountDeletion =
                            accountDeletionFallbackPresentAtStartup ||
                                accountDeletionMarkerPresentAtStartup() ||
                                accountDeletionAuthorityAtStartup.blocksPrivacy,
                        initiallyBlockedForRawSourceCollection =
                            stepLengthPrefs.getBoolean(
                                PREF_RAW_SOURCE_FIELD_LOG_BLOCKED,
                                false,
                            ),
                    )
                } else {
                    NoopFieldSessionLog()
                } }, release = { it.close() })
                runCatching { initializeGuidanceDiagnostics() }
                if (accountDeletionInstallationResetController.restoreStartupHandoffAfterResourcesPrepared() ==
                    InstallationResetStartupResult.FINISH
                ) return@preparation PrivacyStartupInspectionResult.FINISH
                null
            },
            inspect = inspection@{ speechOutputPurgeCompleted ->
                if (accountDeletionInstallationResetController.inspectStartupReset(speechOutputPurgeCompleted) ==
                    InstallationResetStartupResult.FINISH
                ) return@inspection PrivacyStartupInspectionResult.FINISH
                restoreEmailEnrollmentPartialAtStartup()
                restoreReportCooldownsFromPrefs()
                restoreStepLengthFromPrefs()
                restoreProgressBeepPrefs()
                purgeUnownedLegacyPriorityUserOnboardingPrefs()
                if (!migrateKnownIntegratedConsentPolicyAtStartup()) {
                    return@inspection PrivacyStartupInspectionResult.FINISH
                }
                restorePermissionSessionStateFromPrefs()
                if (!restorePrivacyControlStateFromPrefs()) {
                    return@inspection PrivacyStartupInspectionResult.FINISH
                }
                restorePriorityUserOnboardingFromPrefs()
                if (permissionRecoveryGate.blocksAutomaticResourceStart) {
                    fieldSessionLog.blockActiveSessionRestore()
                }
                fieldSessionLog.recordEvent("app_created")
                if (BuildConfig.DEBUG) startFieldSessionHeartbeat()
                if (previousProcessHadInterruptedWalk) {
                    fieldSessionLog.recordEvent(
                        "previous_walk_interrupted_fresh_walk_created",
                    )
                }
                initializeSpeechOutputCollectionOnPrivacyWorker()
                PrivacyStartupInspectionResult.READY
            },
            onReady = {
                scheduleLegacyPendingReportQueuePurge()
                reconcileAccountDeletionFallbackMarkerAtStartup()
                syncActiveSessionScreenPolicy()
                if (accountDeletionStateMachine.processingBlocked()) {
                    applyAccountDeletionRuntimeFence()
                }
                if (accountDeletionFallbackPresentAtStartup) {
                    applyAccountDeletionRuntimeFence()
                    startAccountDeletionFallbackRecoveryAfterRestore()
                }
                privacyStartupResources.acquireOnUiThread(
                    { gatewaySessionController }, { try { it.detach() } finally { it.unregisterGatewayCapacityNetworkObserver() } },
                ).attach(::dispatchGatewayProcessSessionChanged)
                registerGatewayCapacityNetworkObserver()
                enforcePriorityUserAccountEligibility()
                scheduleGatewaySessionRestoreAfterPrivacyStartupInspection()
                fusedLocationClient = LocationServices.getFusedLocationProviderClient(this)
                stepTracker = privacyStartupResources.acquireOnUiThread(create = { AndroidStepTracker(
                    context = this,
                    onStepCountChanged = { steps ->
                        val expectedEpoch = stepTrackingEpoch
                        if (
                            expectedEpoch != null &&
                            walkSessionLifecycle.isRuntimeEpochCurrent(expectedEpoch)
                        ) {
                            latestStepCount = steps
                            refreshWalkingCalibrationDiagnostics()
                        }
                    },
                    onStepEvent = { event ->
                        val binding = positioningCollectionBinding
                        val receivedAtMs = SystemClock.elapsedRealtime()
                        val motionOwner = binding?.coordinator?.currentUserMotionOwner()
                        if (binding != null && motionOwner != null) {
                            runOnUiThread {
                                handlePositioningStepEvent(event, binding, receivedAtMs, motionOwner)
                            }
                        }
                    },
                ) }, release = { it.stop() })
                earthOrientationTracker = privacyStartupResources.acquireOnUiThread(
                    { AndroidEarthOrientationTracker(this) }, { it.stop() },
                )
                setContentView(insetNativeContent(buildContentView()))
                surfaceView.onPause()
                updatePermissionRecoveryUi()
                if (accountDeletionStateMachine.processingBlocked()) {
                    resumePrivacyControlOperations()
                } else {
                    this@MainActivity.privacyStartupInspectionController.schedulePrivacyOperations()
                }
                startupCapabilityProbe = privacyStartupResources.acquireOnUiThread(create = { AndroidStartupCapabilityProbe(this) {
                    completeVoiceDataInstallRecheckIfPossible()
                    if (
                        restoreBoundPostLoginDeviceCheckResultIfPossible() &&
                        advanceEmailStagesWithRestoredDeviceCheck()
                    ) {
                        onFirstRunOnboardingStateChanged(
                            announcement =
                                "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요.",
                            preservePostLoginDeviceCheck = true,
                        )
                    }
                    refreshStartupCapabilityUi()
                } }, release = { it.close() })
                maybeStartFirstRunDeviceCheckProbes()
                maybeStartStoredDeviceCheckBindingValidation()
                refreshStartupCapabilityUi()
                updateRouteButtonText()
                updateStatus(
                    status = "ARCore Depth 대기",
                    detail = "목적지 없이 위험 인식 모드를 시작할 수 있습니다. TFLite는 카메라 권한과 기기 기능 확인 후 로드합니다.",
                )
                if (developmentQuickStartEnabled) {
                    window.decorView.post { this@MainActivity.developmentQuickStartController.loginDevelopmentQuickStartAccount() }
                }
            },
        )
    }

