    private fun drainPrivacyStartupSpeechOutputOnWorker() {
        val collection = speechOutputStorageCoordinator.collectionOrNull()
        if (collection != null) {
            val drain = collection.store.closeAndDrain()
            collection.drainFuture.compareAndSet(null, drain)
            // The retained future is the store's acknowledgement. A false drain must not
            // prevent the independent legacy uploader/logger close tail below.
            awaitSpeechOutputStorageCleanup(null, drain, requiresPurge = false)
        }
    }

