    private fun configuredGatewayOriginOrNull(): String? {
        if (developmentQuickStartEnabled) return BuildConfig.WALKSAFE_GATEWAY_ORIGIN
        val configured = stepLengthPrefs.getString(
            PREF_GATEWAY_ORIGIN_KEY,
            BuildConfig.WALKSAFE_GATEWAY_ORIGIN,
        )
        return if (BuildConfig.DEBUG) {
            GatewayEndpointPolicy.configuredDebugOriginOrNull(configured, BuildConfig.WALKSAFE_GATEWAY_ORIGIN)
        } else {
            GatewayEndpointPolicy.approvedReleaseOriginOrNull(
                raw = configured,
                approvedOrigin = BuildConfig.WALKSAFE_GATEWAY_ORIGIN,
            )
        }
    }

    private val actorSessionLifecycleCoordinator: ActorSessionLifecycleCoordinator by lazy(LazyThreadSafetyMode.NONE) {
        ActorSessionLifecycleCoordinator(
            gateway = object : ActorSessionLifecycleCoordinator.Gateway {
                override fun snapshot() = GatewaySessionProcessCoordinator.snapshot()
                override fun processSessionChanged(snapshot: GatewaySessionProcessSnapshot) { gatewaySessionController.processSessionChanged(snapshot) }
                override fun fenceCapacityGeneration(generation: Long) { GatewayCapacityProcessState.fenceSessionGeneration(generation) }
                override fun requestCapacity(reason: String) { this@MainActivity.gatewaySessionController.requestGatewayCapacityRefresh(reason) }
                override fun publishFirstRun(generation: Long, actorId: String, snapshot: FirstRunOnboardingSnapshot) =
                    GatewaySessionProcessCoordinator.updateFirstRunSnapshot(expectedGeneration = generation, expectedActorId = actorId, firstRunSnapshot = snapshot)
                override fun retryPendingRenewal() { retryPendingGatewayRenewal() }
            },
            routes = object : ActorSessionLifecycleCoordinator.Routes {
                override fun retireRequest(snapshot: GatewaySessionProcessSnapshot) = retireRouteRequestForGatewayTransition(snapshot)
                override fun presentRetiredRequest() {
                    updateRouteDeviationActions(routeNavigator.pendingUserDecision())
                    updateRouteButtonText()
                    updateNavigationStatus("navigation=route_request_finished session_renewal")
                }
                override fun reconcileAccount(snapshot: GatewaySessionProcessSnapshot) { this@MainActivity.routeArchiveController.reconcileRouteSnapshotAccount(snapshot) }
            },
            reports = object : ActorSessionLifecycleCoordinator.Reports {
                override fun cancelAuthorityExpiry() { cancelUserReportAuthorityExpirySchedule() }
                override fun invalidatePendingExplicit() { invalidatePendingExplicitReport() }
                override fun withdrawPrivacy() { reportPrivacyConsentSession.withdraw() }
                override fun cancelQueueDrain() { cancelReportQueueDrain() }
                override fun clearAuthorityUiFence() { clearUserReportRequestUiForAuthorityFence() }
                override fun initialized() = this@MainActivity::userReportController.isInitialized
                override fun authorityChanged() { userReportController.onAuthorityChanged() }
                override fun loadIfIdleAndAuthorized() {
                    if (currentUserReportAuthorityOrNull() != null && userReportController.snapshot().phase == UserReportUiPhase.IDLE) userReportController.loadReports()
                }
                override fun scheduleAuthorityExpiry() { scheduleUserReportAuthorityExpiryIfNeeded() }
            },
            raw = object : ActorSessionLifecycleCoordinator.Raw {
                override fun initialized() = this@MainActivity::rawCollectionRuntimeCoordinator.isInitialized
                override fun clearUploadIdentity() { rawCollectionTransferController.clearUploadWalk() }
                override fun cancelActiveUpload() { rawCollectionRuntimeCoordinator.cancelActiveUpload() }
                override fun revalidate() { revalidateRawCollectionRuntime() }
                override fun clearDetectionWindowInTask() { executeRawCollectionTask(::clearRawDetectionWindow) }
                override fun resetEnrollmentInTask(session: GatewayFieldSession, generation: Long, deviceCheck: PostLoginDeviceCheckSnapshot) {
                    executeRawCollectionTask { rawCollectionRuntimeCoordinator.resetForNewEnrollment(session = session, sessionGeneration = generation, deviceCheck = deviceCheck) }
                }
            },
            consent = object : ActorSessionLifecycleCoordinator.Consent {
                override fun onActorBindingChanged(session: GatewayFieldSession?) { integratedConsentController.onActorBindingChanged(session) }
                override fun fenceAuthorityChanged(snapshot: GatewaySessionProcessSnapshot) = integratedConsentController.fenceGatewayAuthorityChange(snapshot)
                override fun reapplyActorBound() { reapplyActorBoundIntegratedConsent() }
                override fun cachedConfirmationPresent() = integratedConsentSession.cachedConfirmationOrNull() != null
                override fun noPendingMutation() = integratedConsentController.screenState().pendingMutation == null
                override fun refreshFromServer() { refreshIntegratedConsentFromServer() }
            },
            speech = object : ActorSessionLifecycleCoordinator.Speech {
                override fun retireGatewayAuthorityIfChanged(snapshot: GatewaySessionProcessSnapshot) {
                    val authority = speechOutputStorageCoordinator.authorityOrNull()
                    if (authority != null && (snapshot.generation != authority.binding.gatewayGeneration ||
                        snapshot.session !== authority.binding.gatewaySession || snapshot.storageBlocked || snapshot.deletionRecoveryOnly)) invalidateSpeechOutputStorageBinding()
                }
                override fun invalidateStorage() { invalidateSpeechOutputStorageBinding() }
                override fun invalidatePermissionActorIfChanged(actorId: String) { this@MainActivity.speechOutputStorageCoordinator.invalidatePermissionActorIfChanged(actorId) }
            },
            permissions = object : ActorSessionLifecycleCoordinator.Permissions {
                override var reporterActorId: String?
                    get() = reporterUserId
                    set(value) { reporterUserId = value }
                override fun remember(actorId: String) { permissionSessionPolicy.rememberActor(actorId) }
                override fun authenticate(actorId: String) { permissionSessionPolicy.authenticated(actorId) }
                override fun expireAuthentication() { permissionSessionPolicy.authenticationExpired() }
                override fun invalidateRecoveryScope() { invalidatePermissionRecoveryScopeIfChanged() }
                override fun enforceAccountEligibility() { enforcePriorityUserAccountEligibility() }
            },
            device = object : ActorSessionLifecycleCoordinator.Device {
                override fun bindSession(actorId: String?, generation: Long?) { bindPostLoginDeviceCheckSession(actorId, generation) }
                override fun snapshot() = postLoginDeviceCheckSnapshot
                override fun passesGate() = postLoginDeviceCheckPassesFeatureGate()
                override fun disabledFeatureText() = postLoginDeviceCheckDisabledFeatureText()
                override fun hasRestrictions() = hasCurrentPostLoginDeviceRestrictions()
                override fun clearLiveStatus() { postLoginDeviceCheckLastLiveStatus = null; firstRunOnboardingPresenter.readinessBinding().postLoginDeviceCheckLiveStatusText.text = ""; firstRunOnboardingPresenter.readinessBinding().postLoginDeviceCheckLiveStatusText.visibility = View.GONE }
                override fun announceProgress(message: String) { this@MainActivity.postLoginDeviceInteraction.announcePostLoginDeviceCheckProgress(message) }
            },
            privacy = object : ActorSessionLifecycleCoordinator.Privacy {
                override fun callbackOwnerLive() = !privacyStartupInspectionDestroyed && accountDeletionStateMachine.activityLeaseIsCurrent(accountDeletionActivityLease)
                override fun resumeDeletionIfNeeded(sessionPresent: Boolean) {
                    val process = GatewaySessionProcessCoordinator.snapshot()
                    if (process.inFlightOperationId != null ||
                        (accountDeletionRecoveryLoginRequired() &&
                            accountDeletionRecoveryGatewaySessionOrNull(process.session) == null)
                    ) return
                    val journal = accountDeletionStateMachine.snapshotOrNull()
                    if (sessionPresent && journal != null && !isConfirmedAccountDeletionJournal(journal) &&
                        accountDeletionLocalPurgeInFlightRequestId == null && !accountDeletionRemoteResumeBlocked && !accountDeletionRequestInFlight) {
                        dispatchAccountDeletionNetworkEntry(journal = journal, keepPrivacyFenceClosed = ::keepAccountDeletionPrivacyFenceClosed, dispatch = ::refreshAccountDeletionStatus)
                    }
                }
            },
            runtime = object : ActorSessionLifecycleCoordinator.Runtime {
                override fun voiceGatewayChanged(snapshot: GatewaySessionProcessSnapshot) { voiceInputController.onProcessSessionChanged(snapshot) }
                override fun cancelEducation() { cancelPendingPriorityUserTrainingFeedback() }
