                override fun runOnUiThread(action: Runnable) { this@MainActivity.runOnUiThread(action) }
                override fun dispatchObserverInlineIfMain(action: Runnable) {
                    if (Looper.myLooper() == Looper.getMainLooper()) action.run() else this@MainActivity.runOnUiThread(action)
                }
                override fun postDecor(action: Runnable) { window.decorView.post(action) }
                override fun refreshActorScreens() { updateBackendAuthButtonText(); updateReportPrivacyConsentUi(); updateAccountDeletionUi(); updateFirstRunOnboardingUi() }
