    private fun newStableReportTraceId(
        actorId: String,
        sessionGeneration: Long,
    ): String {
        val namespace =
            sha256Hex(
                "$actorId|$sessionGeneration".toByteArray(Charsets.UTF_8),
            ).take(24)
        return "android:$namespace:${UUID.randomUUID()}".take(128)
    }

