    private fun createEmailAccountController(): EmailAccountController = EmailAccountController(
        services = object : EmailAccountController.Services {
            private val account = GatewayAccountClient()
            override fun installationDeviceId() = gatewaySessionStore.getOrCreateInstallDeviceId()
            override fun signupUnavailableOptionalDocuments(gatewayBaseUrl: String) = account.signupUnavailableOptionalDocuments(gatewayBaseUrl)
            override fun requestEmailOtp(gatewayBaseUrl: String, email: String, dateOfBirth: String, requestId: String) =
                account.requestEmailOtp(gatewayBaseUrl, email, dateOfBirth, requestId)
            override fun createAccount(gatewayBaseUrl: String, enrollmentHandle: String, otpCode: String, password: String, selections: SignupConsentSelections, documentVersions: Map<String, String>) =
                account.createAccount(gatewayBaseUrl, enrollmentHandle, otpCode, password, selections, documentVersions)
            override fun loginWithPassword(gatewayBaseUrl: String, email: String, password: String, rememberMe: Boolean, deviceId: String, enableLongLivedSession: Boolean) =
                gatewaySessionClient.loginWithPassword(gatewayBaseUrl, email, password, rememberMe, deviceId, enableLongLivedSession = enableLongLivedSession)
            override fun retirePasswordLogin(session: GatewayFieldSession, operationId: String): GatewaySessionStoreResult =
                session.versionOrNull?.let { version ->
                    if (session.isLongLived) gatewaySessionStore.moveActiveToPendingRevocation(version, operationId)
                    else gatewaySessionStore.removeBackendDeviceIfCurrent(version)
                } ?: GatewaySessionStoreResult.BLOCKED
            override fun logout(session: GatewayFieldSession) { gatewaySessionClient.logout(session) }
            override fun saveBackendDeviceIfAbsent(session: GatewayFieldSession, firstRunSnapshot: FirstRunOnboardingSnapshot, expectedGatewayBaseUrl: String) =
                if (session.isLongLived) gatewaySessionStore.saveInitialIfAbsent(session, firstRunSnapshot, expectedGatewayBaseUrl)
                else gatewaySessionStore.saveBackendDeviceIfAbsent(session, firstRunSnapshot, expectedGatewayBaseUrl)
            override fun removeBackendDeviceIfCurrent(expectedVersion: kr.co.hanium.dreamup.walksafe.network.GatewaySessionVersion) =
                gatewaySessionStore.removeBackendDeviceIfCurrent(expectedVersion)
        },
        flow = object : EmailAccountController.Flow {
            override val snapshot: FirstRunOnboardingSnapshot get() = firstRunOnboardingSnapshot
            override fun restartEmailAccount() = firstRunOnboardingController.restartEmailAccount(SystemClock::elapsedRealtimeNanos)
            override fun recordOtpEnrollment(receipt: FirstRunReceiptHash) = firstRunOnboardingController.recordEmailOtpEnrollment(receipt)
            override fun recordAccountCreated(receipt: FirstRunReceiptHash, clearEnrollment: () -> Boolean) =
                firstRunOnboardingController.recordEmailAccountCreated(receipt, clearEnrollment)
            override fun prepareVerifiedLogin(actor: FirstRunOpaqueActorBinding, receipt: FirstRunReceiptHash, completed: FirstRunOnboardingSnapshot?) =
                firstRunOnboardingController.prepareVerifiedEmailLogin(actor, receipt, completed)
            override fun applyVerifiedLogin(prepared: FirstRunOnboardingController.PreparedEmailLogin) =
                firstRunOnboardingController.applyVerifiedEmailLogin(prepared)
            override fun completedNativeProgress(actorId: String) = restoreCompletedNativeOnboarding(actorId)
        },
        inputs = object : EmailAccountController.Inputs {
            override fun text(field: EmailAccountController.InputField) = this@MainActivity.accountAccessPresenter.inputTarget(field).text?.toString().orEmpty()
            override fun consentSelections() = currentAccountConsentSelections()
            override fun signupExpanded() = accountSignupExpanded
            override fun displayedSignupDocumentVersions() = accountAccessPresenter.displayedSignupDocumentVersions()
        },
        readers = EmailAccountController.Readers(
            gatewayOrigin = ::configuredGatewayOriginOrNull,
            networkAvailable = ::accountNetworkAvailable,
            transitionAllowed = ::positionFieldAccountTransitionAllowed,
            backendRestorePending = { backendDeviceRestorePending },
            gatewaySession = { gatewayFieldSession },
            developmentQuickStartEnabled = { developmentQuickStartEnabled },
        ),
        ui = object : EmailAccountController.Ui {
            override fun showMessage(message: String) = showAccountMessage(message)
            override fun showInputError(field: EmailAccountController.InputField, message: String) =
                showAccountInputError(this@MainActivity.accountAccessPresenter.inputTarget(field), message)
            override fun showMissingRequiredConsentError() = this@MainActivity.showMissingRequiredConsentError()
            override fun clearAccessNotice() { accountAccessNotice = null }
            override fun setPasswordLoginFailureNotice(message: String?) { passwordLoginFailureNotice = message }
            override fun refresh() = updateFirstRunOnboardingUi()
            override fun revealSignup() { accountSignupExpanded = true }
            override fun applyConsentSelections(selections: SignupConsentSelections) = applyAccountConsentSelections(selections)
            override fun showUnavailableOptionalSignupDocuments(keys: Set<String>) = accountAccessPresenter.showUnavailableOptionalSignupDocuments(keys)
            override fun speakInteraction(message: String) { this@MainActivity.speakInteraction(message) }
            override fun focusOtp() {
                accountAccessPresenter.inputTarget(EmailAccountController.InputField.OTP).post {
                    accountAccessPresenter.inputTarget(EmailAccountController.InputField.OTP).requestFocus()
                    accountAccessPresenter.inputTarget(EmailAccountController.InputField.OTP).requestRectangleOnScreen(
                        Rect(0, 0, accountAccessPresenter.inputTarget(EmailAccountController.InputField.OTP).width, accountAccessPresenter.inputTarget(EmailAccountController.InputField.OTP).height), true,
                    )
                }
            }
            override fun clearInputs(fields: List<EmailAccountController.InputField>) {
                fields.forEach { this@MainActivity.accountAccessPresenter.inputTarget(it).text?.clear() }
            }
            override fun onFirstRunStateChanged(message: String) = onFirstRunOnboardingStateChanged(message)
            override fun updateStatus(message: String) = updateNavigationStatus(message)
        },
        effects = object : EmailAccountController.VerifiedEffects {
            override fun restoreGatewaySession() = restoreGatewaySessionFromPrefs()
            override fun refreshConfirmedConsent() = refreshIntegratedConsentFromServer()
            override fun noteDevelopmentQuickStartActor(actorId: String) { developmentQuickStartController.noteAuthenticatedActor(actorId) }
            override fun onBackendRestoreVerified() { gatewaySessionController.backendRestoreVerified() }
            override fun applyVerifiedAccount(actorId: String, reauthenticatesExistingProgress: Boolean) {
                reporterUserId = actorId
                priorityUserOnboardingActorId = actorId
                restorePriorityUserOnboardingFromPrefs()
                if (!permissionSessionPolicy.isAuthenticatedFor(actorId)) {
                    invalidateSpeechOutputStorageBinding()
                    permissionSessionPolicy.rememberActor(actorId)
                }
                reapplyActorBoundIntegratedConsent()
            }
        },
        executor = gatewaySessionExecutor,
        postToMain = { task -> runOnUiThread { task() } },
        elapsedRealtimeMs = SystemClock::elapsedRealtime,
    )


    private fun showAccountMessage(message: String) {
        developmentQuickStartController.showAccountStatusIfEnabled(message)
        val presentation = accountAccessPresenter.recordAccountMessage(
            message,
            statusInitialized = nativeUiPublication.isPublished(NativeUiPublication.Target.ACCOUNT_ACCESS_STATUS_TEXT),
        )
        if (presentation != null && isScreenReaderActive() &&
            (!presentation.changed || !presentation.isShown)) {
            announceForTalkBack(message, TalkBackAnnouncementPriority.INTERACTION)
        }
        updateStatus("계정 등록", message)
    }

