                if (nativeUiPublication.isPublished(NativeUiPublication.Target.ACCOUNT_PASSWORD_INPUT)) accountAccessPresenter.inputTarget(EmailAccountController.InputField.PASSWORD).text?.clear()
                if (nativeUiPublication.isPublished(NativeUiPublication.Target.ACCOUNT_PASSWORD_CONFIRMATION_INPUT)) accountAccessPresenter.inputTarget(EmailAccountController.InputField.PASSWORD_CONFIRMATION).text?.clear()
