    private fun initializeGuidanceDiagnostics() {
        val buildId = BuildConfig.WALKSAFE_GUIDANCE_DIAGNOSTIC_BUILD_ID
        if (!BuildConfig.DEBUG || !Regex("[a-f0-9]{64}").matches(buildId)) return
        val root = File(noBackupFilesDir.canonicalFile, "guidance_diagnostics")
        val http = GuidanceDiagnosticHttpTransport(System::currentTimeMillis)
        guidanceDiagnosticRuntime = privacyStartupResources.acquireOnWorker(create = { GuidanceDiagnosticRuntimeCoordinator(
            debugUserApproved = true, buildId = buildId,
            queueFactory = {
                EncryptedGuidanceDiagnosticQueue(root,
                    kr.co.hanium.dreamup.walksafe.security.AndroidKeyStoreAead(EncryptedGuidanceDiagnosticQueue.KEY_POLICY),
                    syncDirectory = { directory -> runCatching {
                        java.nio.channels.FileChannel.open(directory.toPath(), java.nio.file.StandardOpenOption.READ)
                            .use { it.force(true) }
                    }.isSuccess })
            },
            transport = http, preference = http::preference,
            authorizeIfAbsent = http::authorizeTestScopeIfAbsent, setPreference = http::setPreference,
            wallTimeMs = System::currentTimeMillis, elapsedRealtimeMs = SystemClock::elapsedRealtime,
            onState = { reportCleanupCallbackHandler.post {
                if (!privacyStartupInspectionDestroyed) {
                    commitGuidanceDiagnosticEnableIfReady()
                    renderGuidanceDiagnosticSetting()
                }
            } },
        ) }, release = {
            try { it.close() } finally { reportCleanupCallbackHandler.removeCallbacks(guidanceDiagnosticTick) }
        })
        reportCleanupCallbackHandler.post(guidanceDiagnosticTick)
    }

    private fun refreshGuidanceDiagnosticAuthority(): Boolean {
        val runtime = guidanceDiagnosticRuntime ?: return false
        return runCatching {
            if (Looper.myLooper() != Looper.getMainLooper()) {
                reportCleanupCallbackHandler.post {
                    if (!privacyStartupInspectionDestroyed) refreshGuidanceDiagnosticAuthority()
                }
                return@runCatching false
            }
            val process = GatewaySessionProcessCoordinator.snapshot()
            val session = process.session
            val deletionBlocked = accountDeletionStateMachine.processingBlocked()
            runtime.publishAuthority(GuidanceDiagnosticRuntimeCoordinator.Authority(
                session = session, gatewayGeneration = process.generation,
                accountGeneration = session?.backendAccountGeneration,
                admitted = privacyStartupInspectionComplete && !privacyStartupInspectionDestroyed &&
                    !deletionBlocked && !process.storageBlocked && !process.deletionRecoveryOnly &&
                    session?.sessionScope == kr.co.hanium.dreamup.walksafe.network.GatewaySessionScope.GENERAL &&
                    session?.isUsableFor(reporterUserId) == true,
                networkAllowed = isGatewayFeatureNetworkAllowed(),
                localEnabled = runtime.authorityLocalEnabled(session, session?.backendAccountGeneration,
                    stepLengthPrefs.getBoolean("guidance_diagnostic_enabled", true)),
                deletionBlocked = deletionBlocked, storageBlocked = process.storageBlocked,
            ))
            true
        }.getOrElse {
            runtime.suspendAuthority()
            false
        }
    }

    private fun recordGuidanceDiagnosticEvent(name: String, fields: Map<String, Any?>) {
        if (guidanceDiagnosticRuntime == null) return
        val owner = GatewaySessionProcessCoordinator.snapshot()
        val record = {
            runCatching {
                val current = GatewaySessionProcessCoordinator.snapshot()
                if (!privacyStartupInspectionDestroyed && current.session === owner.session && current.generation == owner.generation &&
                    refreshGuidanceDiagnosticAuthority()) {
                    guidanceDiagnosticRuntime?.record(name, fields)
                }
            }
            Unit
        }
        runCatching {
            if (Looper.myLooper() == Looper.getMainLooper()) record()
            else reportCleanupCallbackHandler.post { record() }
        }
    }

    private fun recordDirectionGraceDiagnostic() {
        runCatching {
            if (guidanceDiagnosticRuntime == null) return
            val state = routeNavigator.currentDirectionGraceSnapshot() ?: return
            val now = SystemClock.elapsedRealtime()
            val signature = "${state.mode}:${state.episodeId}:${state.reason}:${state.authorizedCueRevision}:${state.authorizationKind}"
            if (!guidanceDiagnosticFilter.admit("direction", signature, now)) return
            recordGuidanceDiagnosticEvent("direction_grace", mapOf(
                "mode" to state.mode.name, "reason" to state.reason?.name,
                "episode_id" to state.episodeId, "grace_onset_ms" to state.onsetElapsedRealtimeMs,
                "grace_deadline_ms" to state.deadlineElapsedRealtimeMs,
                "grace_remaining_ms" to state.deadlineElapsedRealtimeMs?.let { (it-now).coerceAtLeast(0L) },
                "source" to state.retainedSource?.name, "heading_accuracy_deg" to state.retainedReportedHeadingAccuracyDegrees,
                "retained_age_ms" to state.retainedObservedAtElapsedRealtimeMs?.let { (now-it).coerceAtLeast(0L) },
                "cue_revision" to state.authorizedCueRevision, "authorization_kind" to state.authorizationKind?.name,
                "observed_ms" to state.authorizationObservedAtElapsedRealtimeMs,
                "age_ms" to state.authorizationObservedAtElapsedRealtimeMs?.let { (now-it).coerceAtLeast(0L) },
            ))
        }
    }

    private fun toggleGuidanceDiagnostics() {
        val runtime = guidanceDiagnosticRuntime ?: return
        val state = runtime.state()
        val enabled = !state.requestedLocalEnabled || state.error == "server_disabled"
        if (!enabled) stepLengthPrefs.edit().putBoolean("guidance_diagnostic_enabled", false).apply()
        runtime.setLocalEnabled(enabled, explicitUserAction = true)
        refreshGuidanceDiagnosticAuthority()
        renderGuidanceDiagnosticSetting()
    }

    private fun commitGuidanceDiagnosticEnableIfReady() {
        val runtime = guidanceDiagnosticRuntime ?: return
        if (stepLengthPrefs.getBoolean("guidance_diagnostic_enabled", true)) return
        val state = runtime.state()
        if (!state.enabled || !state.authorized || !refreshGuidanceDiagnosticAuthority()) return
        val process = GatewaySessionProcessCoordinator.snapshot()
        if (runtime.consumePendingEnableCommit(process.session, process.generation,
                process.session?.backendAccountGeneration)
        ) stepLengthPrefs.edit().putBoolean("guidance_diagnostic_enabled", true).apply()
    }

    private fun purgeGuidanceDiagnosticsOnWorker(): Boolean {
        val purge = {
            kr.co.hanium.dreamup.walksafe.fieldlog.GuidanceDiagnosticLocalStorePurge(
                File(noBackupFilesDir.canonicalFile, "guidance_diagnostics"),
                kr.co.hanium.dreamup.walksafe.security.AndroidKeyStoreAead(EncryptedGuidanceDiagnosticQueue.KEY_POLICY),
                syncDirectory = { directory -> runCatching {
                    java.nio.channels.FileChannel.open(directory.toPath(), java.nio.file.StandardOpenOption.READ)
                        .use { it.force(true) }
                }.isSuccess },
            ).purgeAndRotate()
        }
        val runtime = guidanceDiagnosticRuntime ?: return runCatching(purge).getOrDefault(false)
        return runCatching { runtime.purgeForAccountDeletion(purge).get(15L, java.util.concurrent.TimeUnit.SECONDS) }.getOrDefault(false)
    }

    private fun renderGuidanceDiagnosticSetting() {
        val state = guidanceDiagnosticRuntime?.state() ?: return
        guidanceDiagnosticButton?.text = when {
            !state.requestedLocalEnabled || state.error == "server_disabled" -> "길 안내 문제 기록: 꺼짐 · 켜기"
            state.authorized -> "길 안내 문제 기록: 켜짐 · 끄기"
            else -> "길 안내 문제 기록: 전송 대기 · 끄기"
        }
    }

