    private fun integratedConsentRefreshSessionOrNull(): GatewayFieldSession? {
        val session = gatewayFieldSession ?: return null
        if (isGatewaySessionReadyForCurrentActor(session)) return session
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        val onboardingActorId = firstRunOnboardingSnapshot.takeIf {
            it.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 && !it.isComplete
        }?.verifiedActorBinding?.value
        val readyForOnboardingRefresh =
            onboardingActorId != null &&
                processSnapshot.session === session &&
                !processSnapshot.storageBlocked &&
                !processSnapshot.deletionRecoveryOnly &&
                session.sessionScope == GatewaySessionScope.GENERAL &&
                session.verificationState == GatewaySessionVerificationState.VERIFIED &&
                session.actorId == onboardingActorId &&
                session.isUsableFor(onboardingActorId) &&
                session.gatewayBaseUrl == configuredGatewayOriginOrNull() &&
                reporterUserId == onboardingActorId &&
                priorityUserOnboardingActorId == onboardingActorId
        if (readyForOnboardingRefresh) return session
        clearExpiredGatewaySessionIfCurrent(session)
        return null
    }

    private fun clearExpiredGatewaySessionIfCurrent(session: GatewayFieldSession) {
        return gatewaySessionController.clearExpiredGatewaySessionIfCurrent(session)
    }




    /**
     * login-F4: after the Gateway rejected a long-lived access credential, one durable refresh
     * (bounded per family, [GatewayUnauthorizedRenewalProbe]) either keeps a login the server
     * still has or returns the revocation reason (e.g. `field_session_revoked_reuse_detected`)
     * for [GatewayRenewalFailureNotice]. Returns true when the probe replaced the clear.
     */
    private fun probeGatewaySessionAfterUnauthorized(
        session: GatewayFieldSession,
        waiter: (() -> Unit)? = null,
    ): Boolean {
        return gatewaySessionController.probeGatewaySessionAfterUnauthorized(session, waiter)
    }

    /** login-F1: queues [waiter] behind a running in-run renewal, or runs it if already renewed. */
    private fun awaitInRunGatewaySessionRenewal(waiter: () -> Unit): Boolean {
        return gatewaySessionController.awaitInRunGatewaySessionRenewal(waiter)
    }





    private fun gatewayFailureUiGuardOrNull(
        session: GatewayFieldSession,
        expectedAuthenticationFailure: Boolean,
    ): GatewayFailureUiGuard? {
        if (expectedAuthenticationFailure) {
            // login-F4: a rejected long-lived access credential gets one durable refresh first; its
            // outcome (renewed login or the revocation reason notice) replaces this failure UI.
            if (probeGatewaySessionAfterUnauthorized(session)) {
                updateNavigationStatus("gateway=session_renewing reason=request_rejected")
                speakInteraction("로그인을 확인하고 있습니다. 잠시 후 다시 시도하세요.")
                return null
            }
            val clearedGeneration = clearGatewaySession(
                logoutRemote = false,
                expectedSession = session,
            ) ?: return null
            return GatewayFailureUiGuard(
                generation = clearedGeneration,
                expectedAuthenticationFailure = true,
            )
        }
        return if (!isGatewaySessionReadyForCurrentActor(session)) {
            null
        } else {
            GatewayFailureUiGuard(
                generation = gatewaySessionGeneration,
                expectedAuthenticationFailure = false,
            )
        }
    }

    private fun isGatewayFailureUiGuardCurrent(
        session: GatewayFieldSession,
        guard: GatewayFailureUiGuard,
    ): Boolean {
        return if (gatewaySessionGeneration != guard.generation) {
            false
        } else if (guard.expectedAuthenticationFailure) {
            gatewayFieldSession == null
        } else {
            isGatewaySessionReadyForCurrentActor(session)
        }
    }

    private fun prepareReportMetadataContext() {
        val startedAt = SystemClock.elapsedRealtime()
        reportApkSha256 = computeApkSha256()
        reportRuntimeConfig = loadReportRuntimeConfig()
        recordStartupPreparationDuration("REPORT_METADATA", startedAt)
    }

    private fun recordStartupPreparationDuration(stage: String, startedAtMs: Long) {
        if (!BuildConfig.DEBUG) return
        runCatching {
            android.util.Log.d("WalkSafeStartupPerf",
                "stage=$stage duration_ms=${SystemClock.elapsedRealtime() - startedAtMs}")
        }
    }

    private fun loadReportRuntimeConfig(): TwoModelRuntimeConfig? {
        return try {
            val runtimeJson = assets.open("model-config/two_model_runtime.json").bufferedReader().use { it.readText() }
            reportModelConfigSha256 = sha256Hex(runtimeJson.toByteArray())
            TwoModelRuntimeConfig.load(this)
        } catch (_: Exception) {
            null
        }
    }

    private fun computeApkSha256(): String? {
        return try {
            val digest = MessageDigest.getInstance("SHA-256")
            FileInputStream(applicationInfo.sourceDir).use { inputStream ->
                val buffer = ByteArray(1 shl 16)
                while (true) {
                    val read = inputStream.read(buffer)
                    if (read <= 0) break
                    digest.update(buffer, 0, read)
                }
            }
            hexEncoded(digest.digest())
        } catch (_: Exception) {
            null
        }
    }

    private fun sha256Hex(bytes: ByteArray): String {
        return hexEncoded(MessageDigest.getInstance("SHA-256").digest(bytes))
    }

    private fun hexEncoded(bytes: ByteArray): String {
        return bytes.joinToString("") { "%02x".format(it.toInt() and 0xFF) }
    }

    private fun resolveReportSourceModel(modelKey: String?): String? {
        val runtimeSourceModel = reportRuntimeConfig?.sourceModelForReportModel(modelKey)
        return runtimeSourceModel ?: modelKey?.let { "android/$it" }
    }

    private fun resolveReportThreshold(modelKey: String?, className: String): Float? {
        return reportRuntimeConfig?.thresholdForReportClass(modelKey, className)
    }

    override fun onResume() {
        invalidateSpeechOutputStorageBinding()
        super.onResume()
        // S04-27-F1: a capture silenced after the app had already left is retried on this return
        // (not a second leave) once no call or other recorder holds the input; the notice follows.
        voiceInputController.onBeforeForegroundReturn()
        emailAccountController.enteredForeground()
        feedbackLifecycleGeneration += 1
        isActivityForeground = true
        runtimeLoadObservationSource.start()
        cancelForegroundHomeWakeListening(resetFailure = true)
        revalidateUserReportAuthorityOnResume()
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.FIRST_RUN_WAITING_CARD)) {
            updateFirstRunWaitingDots(firstRunOnboardingPresenter.registrationBinding().firstRunWaitingCard.visibility == View.VISIBLE)
        }
        if (!privacyStartupInspectionComplete) {
            completePrivacyStartupReadyIfForeground()
            return
        }
        resumeWalkSafeRuntimeAfterPrivacyStartupInspection()
    }

    override fun onStop() {
        voiceInputController.onStopped()
        super.onStop()
    }

    override fun onWindowFocusChanged(hasFocus: Boolean) {
        super.onWindowFocusChanged(hasFocus)
        if (
            !hasFocus ||
            !isActivityForeground ||
            !privacyStartupInspectionComplete ||
            privacyStartupInspectionDestroyed
        ) return
        if (postLoginDeviceCheckSnapshot.passesFeatureGate) {
            refreshStartupCapabilityUi()
        }
    }

    private fun resumeWalkSafeRuntimeAfterPrivacyStartupInspection() {
        retryPendingGatewayRenewal()
        retryPendingBackendDeviceRestore()
        permissionFlowController.requirePermissionRecoveryRecheckAfterPrivacyInspection()
        revalidateCompletedPostLoginDeviceCheckPrerequisites()
        if (advanceEmailStagesWithRestoredDeviceCheck()) {
            onFirstRunOnboardingStateChanged(
                announcement = "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요.",
                preservePostLoginDeviceCheck = true,
            )
        }
        postLoginDeviceCheckController.allowStoredMetricRetry()
        maybeStartStoredMetricDepthRefresh()
        handleWalkSessionForegroundReturn()
        revalidateGatewayWalkAfterForegroundReturn()
        this@MainActivity.permissionFlowController.applyObservedPermissionStateChange("app_resumed")
        requestInitialAppEntryPermissionsIfNeeded()
        syncActiveSessionScreenPolicy()
        recheckVoiceDataAfterSettingsIfNeeded()
        refreshStartupCapabilityUi()
        postLoginDeviceCheckController.announceDeferredBackgroundFailure()
        updateIntegratedConsentUi()
        updateReportPrivacyConsentUi()
        completePermissionRecoveryRecheckIfPossible()
        registerPostWalkPowerConnectedReceiver()
        schedulePostWalkTransfers()
        postLoginDeviceCheckController.resumeDeferredPermissionObservation()
        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("app_resumed")
        if (
            arSessionOwner.observe().session == null &&
            actionMode == ActionMode.OPEN_SETTINGS &&
            checkSelfPermission(Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
        ) {
            setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
            updateStatus("ARCore Depth 대기", "카메라 권한이 허용되었습니다. ARCore Depth를 시작할 수 있습니다.")
        }
        scheduleDeviceRuntimeCalibration()
        showPendingHandsFreeVoiceStartFailure()
    }

    @SuppressLint("GestureBackNavigation")
    @Suppress("OVERRIDE_DEPRECATION")
