        walkBackDispatcher.onBackPressed()
    }

    private fun handleWalkScreenBackPressed(): Boolean {
        if (guidanceTouchGuardScreen != null) return true
        if (walkExitConfirmationScreen != null) { finishWalkExitConfirmation(false); return true }
        if (nativeGuidanceConfirmationScreen != null) { finishNativeGuidanceConfirmation(false); return true }
        if (voiceHelpScreen != null) { closeVoiceHelp(true); return true }
        if (isInWalkInteractionArea()) {
            if (nativeUiPage == NativeUiPage.SETTINGS || nativeUiPage == NativeUiPage.VOICE_COMMAND) returnToCurrentInteractionArea()
            else showWalkExitConfirmationDialog()
            return true
        }
        return handleNativeFeatureBackPressed()
    }

    private var nativeGuidanceAuthorizedDestination: DestinationSearchResult? = null
    private var nativeGuidanceConfirmationScreen: View? = null
    private val nativeGuidanceCoveredViews = mutableListOf<Pair<View, Int>>()
    private var nativeGuidanceConfirmationAction: (() -> Unit)? = null
    private val nativeGuidanceConfirmationRetries = kr.co.hanium.dreamup.walksafe.navigation.GuidanceConfirmationRetryBudget()
    private var nativeGuidanceConfirmationGeneration = 0
    private var nativeGuidanceConfirmationCurrent: (() -> Boolean)? = null
    private fun dismissNativeGuidanceConfirmation() {
        nativeGuidanceConfirmationAction = null
        nativeGuidanceConfirmationCurrent = null
        nativeGuidanceConfirmationGeneration++
        removeNativeGuidanceConfirmationScreen()
    }
    private fun requestNativeGuidanceStartConfirmation(action: () -> Unit) {
        if (nativeGuidanceConfirmationScreen != null || nativeGuidanceConfirmationAction != null ||
            startupCapabilityConfirmationPending) return
        val destination = pendingUiDestination ?: return
        if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeGuidanceStart", "confirmation=opened")
        val epoch = walkSessionLifecycle.snapshot().epoch
        val actor = reporterUserId
        val gateway = GatewaySessionProcessCoordinator.snapshot().generation
        nativeGuidanceConfirmationAction = {
            if (isActivityForeground && nativeUiPage == NativeUiPage.GUIDANCE &&
                pendingUiDestination == destination && reporterUserId == actor &&
                walkSessionLifecycle.snapshot().epoch == epoch &&
                GatewaySessionProcessCoordinator.snapshot().generation == gateway
            ) {
                nativeGuidanceAuthorizedDestination = destination
                action()
            }
        }
        closeVoiceHelp(announce = false)
        val density = resources.displayMetrics.density
        fun dp(value: Int) = (value * density).roundToInt()
        val content = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            setBackgroundColor(WS_COLOR_GROUND)
        }
        val title = TextView(this).apply {
            id = View.generateViewId()
            text = "길안내 시작"
            textSize = 28f
            typeface = wsTypeface(Typeface.BOLD)
            setTextColor(WS_COLOR_EMPHASIS)
            ViewCompat.setAccessibilityHeading(this, true)
        }
        content.addView(title)
        val items = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(0, dp(16), 0, 0)
        }
        var previousId = title.id
        listOf("시작", "다시 듣기", "취소").forEach { label ->
            val button = voiceHelpButton(label) {
                when (label) {
                    "시작" -> finishNativeGuidanceConfirmation(start = true)
                    "취소" -> finishNativeGuidanceConfirmation(start = false)
                    else -> speakNativeGuidanceConfirmation()
                }
            }.apply {
                viewStyle.applyWsSecondaryButtonStyle(this)
                textSize = 24f
                accessibilityTraversalAfter = previousId
            }
            previousId = button.id
            items.addView(button)
        }
        content.addView(ScrollView(this).apply {
            isFillViewport = true
            clipToPadding = true
            addView(items)
        }, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f))
        val host = findViewById<ViewGroup>(android.R.id.content)
        nativeGuidanceCoveredViews.clear()
        for (index in 0 until host.childCount) {
            val child = host.getChildAt(index)
            nativeGuidanceCoveredViews += child to child.importantForAccessibility
            child.importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS
        }
        nativeGuidanceConfirmationScreen = insetNativeContent(content).apply {
            isClickable = true
            isFocusable = true
            ViewCompat.setAccessibilityPaneTitle(this, "길안내 시작")
        }.also { host.addView(it, ViewGroup.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT,
        )) }
        title.requestFocus()
        speakNativeGuidanceConfirmation()
    }

    private fun removeNativeGuidanceConfirmationScreen() {
        val screen = nativeGuidanceConfirmationScreen
        nativeGuidanceConfirmationScreen = null
        (screen?.parent as? ViewGroup)?.removeView(screen)
        nativeGuidanceCoveredViews.forEach { (view, importance) ->
            view.importantForAccessibility = importance
        }
        nativeGuidanceCoveredViews.clear()
    }

    private fun announceNativeGuidanceConfirmationError(message: String) {
        if (nativeGuidanceConfirmationScreen == null || !isActivityForeground) return
        // Recovery guidance is spoken; the screen keeps only its title and large controls.
        // No completion/failure callback here, so a TTS failure cannot trigger a retry loop.
        speakCommandResponse(message)
    }

    private fun finishNativeGuidanceConfirmation(start: Boolean) {
        val action = nativeGuidanceConfirmationAction ?: return
        // Consume once before cancellation/UI callbacks can re-enter this method.
        nativeGuidanceConfirmationAction = null
        nativeGuidanceConfirmationGeneration++
        if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeGuidanceStart", "confirmation=consumed start=$start")
        cancelVoiceCommandRecognition()
        removeNativeGuidanceConfirmationScreen()
        if (start) action() else cancelNativeGuidanceAndReturnHome()
    }

    private fun handleNativeGuidanceConfirmationUnrecognized() {
        if (nativeGuidanceConfirmationScreen == null || nativeGuidanceConfirmationAction == null) return
        if (nativeGuidanceConfirmationRetries.allowAutomaticRetry()) {
            speakNativeGuidanceConfirmation(explicitAttempt = false)
            return
        }
        // Leave the confirmation open. Do not restart recognition from this recovery speech.
        nativeGuidanceConfirmationGeneration++
        cancelVoiceCommandRecognition()
        val message = "음성을 확인하지 못했습니다. 다시 듣기를 누르면 음성 입력을 다시 시도합니다. 시작 또는 취소 버튼으로도 선택할 수 있습니다."
        announceNativeGuidanceConfirmationError(message)
    }

    private fun speakNativeGuidanceConfirmation(explicitAttempt: Boolean = true) {
        val dialog = nativeGuidanceConfirmationScreen ?: return
        val destination = pendingUiDestination ?: return
        if (explicitAttempt) nativeGuidanceConfirmationRetries.beginExplicitAttempt()
        val generation = ++nativeGuidanceConfirmationGeneration
        cancelVoiceCommandRecognition()
        stopHandsFreeVoiceService()
        fun current() = nativeGuidanceConfirmationScreen === dialog && nativeGuidanceConfirmationCurrent?.invoke() != false && isActivityForeground &&
            nativeUiPage == NativeUiPage.GUIDANCE && pendingUiDestination == destination &&
            nativeGuidanceConfirmationGeneration == generation
        var recoveryAnnounced = false
        fun failed() {
            if (!current() || recoveryAnnounced) return
            recoveryAnnounced = true
            announceNativeGuidanceConfirmationError("음성 입력 또는 안내를 완료하지 못했습니다. 마이크 권한과 한국어 음성 설정을 확인하거나 다시 듣기를 눌러 주세요.\n시작·취소 버튼으로도 선택할 수 있습니다.")
        }
        val environmentNotice = currentOfficialEnvironmentAssessment()
            .takeIf { it.conditionallyAllowed }?.let { it.preparationNoticeKo() + " " }.orEmpty()
        val started = speakCommandResponse(
            environmentNotice + "${destination.name}까지 안내를 시작할까요? 시작 또는 취소라고 말씀해 주세요.",
            preparingInput = true,
            onCompleted = {
                if (current()) {
                    voiceInputController.completePreparedPrompt(voiceRecognitionGeneration)
                    if (!startVoiceCommandRecognition()) failed()
                }
            },
            onFailed = { failed() },
        )
        if (!started) failed()
    }

    private fun showWalkExitConfirmationDialog() {
        if (walkExitConfirmationScreen != null || !isActivityForeground) return
        val snapshot = walkSessionLifecycle.snapshot()
        if (snapshot.state !in setOf(WalkSessionState.READY, WalkSessionState.ACTIVE, WalkSessionState.PAUSED, WalkSessionState.SAFE_STOP)) return
        val actor = reporterUserId
        val gatewayGeneration = GatewaySessionProcessCoordinator.snapshot().generation
        cancelVoiceCommandRecognition()
        cancelCommandSpeechResponse()
        stopHandsFreeVoiceService()
        closeVoiceHelp(announce = false)
        walkExitConfirmationIsCurrent = {
            isActivityForeground && reporterUserId == actor &&
                GatewaySessionProcessCoordinator.snapshot().generation == gatewayGeneration &&
                walkSessionLifecycle.snapshot().epoch == snapshot.epoch &&
                walkSessionLifecycle.snapshot().state == snapshot.state
        }
        val density = resources.displayMetrics.density
        val content = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding((16 * density).roundToInt(), (24 * density).roundToInt(),
                (16 * density).roundToInt(), (16 * density).roundToInt())
            setBackgroundColor(WS_COLOR_GROUND)
        }
        val title = TextView(this).apply {
            id = View.generateViewId()
            text = "안내를 종료할까요?"
            textSize = 28f
            typeface = wsTypeface(Typeface.BOLD)
            setTextColor(WS_COLOR_EMPHASIS)
            ViewCompat.setAccessibilityHeading(this, true)
        }
        content.addView(title)
        var previousId = title.id
        listOf("안내로 돌아가기", "안내 종료").forEachIndexed { index, label ->
            val button = voiceHelpButton(label) { finishWalkExitConfirmation(end = index == 1) }
            viewStyle.applyWsButtonStyle(button, 144f, primary = index == 0)
            button.textSize = 24f
            button.accessibilityTraversalAfter = previousId
            previousId = button.id
            content.addView(button)
        }
        val host = findViewById<ViewGroup>(android.R.id.content)
        walkExitCoveredViews.clear()
        for (index in 0 until host.childCount) {
            val child = host.getChildAt(index)
            walkExitCoveredViews += child to child.importantForAccessibility
            child.importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS
        }
        val screen = insetNativeContent(ScrollView(this).apply { isFillViewport = true; addView(content) }).apply {
            isClickable = true
            isFocusable = true
            setBackgroundColor(WS_COLOR_GROUND)
            ViewCompat.setAccessibilityPaneTitle(this, "안내 종료 확인")
        }
        walkExitConfirmationScreen = screen
        host.addView(screen, ViewGroup.LayoutParams(-1, -1))
        title.requestFocus()
        speakCommandResponse(
            "안내를 종료할까요? 계속하려면 돌아가기, 종료하려면 안내 종료라고 말씀해 주세요.",
            preparingInput = true,
            onCompleted = {
                if (walkExitConfirmationScreen === screen && hasCurrentWalkExitConfirmation()) {
                    voiceInputController.completePreparedPrompt(voiceRecognitionGeneration)
                    startVoiceCommandRecognition()
                }
            },
        )
    }

    private fun dismissWalkExitConfirmation() {
        val screen = walkExitConfirmationScreen ?: return
        walkExitConfirmationScreen = null
        walkExitConfirmationIsCurrent = null
        cancelVoiceCommandRecognition()
        cancelCommandSpeechResponse()
        (screen.parent as? ViewGroup)?.removeView(screen)
        walkExitCoveredViews.forEach { (view, importance) -> view.importantForAccessibility = importance }
        walkExitCoveredViews.clear()
    }

    private fun finishWalkExitConfirmation(end: Boolean) {
        if (walkExitConfirmationScreen == null) return
        val current = hasCurrentWalkExitConfirmation()
        val epoch = walkSessionLifecycle.snapshot().epoch
        dismissWalkExitConfirmation()
        if (end && current) {
            cancelNativeGuidanceAndReturnHome()
        } else {
            // Returning never requests resume or restores a pre-dialog safety state.
            showNativeUiPage(NativeUiPage.GUIDANCE)
            if (end && !current) speakInteraction("보행 상태가 바뀌었습니다. 종료하려면 다시 요청해 주세요.")
        }
        voiceInputController.scheduleHandsFreeVoiceRestart()
    }

    override fun onSaveInstanceState(outState: Bundle) {
        outState.putBoolean(STATE_INITIAL_APP_PERMISSION_RE_REQUESTED, initialAppPermissionReRequestedThisLaunch)
        if (::userReportController.isInitialized) {
            userReportController.snapshot().statusFilter?.let { filter ->
                outState.putString(STATE_USER_REPORT_STATUS_FILTER, filter.wireValue)
            } ?: outState.remove(STATE_USER_REPORT_STATUS_FILTER)
        }
        super.onSaveInstanceState(outState)
    }

    override fun onPause() {
        guidanceTouchGuardContent?.cancelHold()
        dismissNativeGuidanceConfirmation()
        dismissWalkExitConfirmation()
        closeVoiceHelp(announce = false)
        if (arrivalEndingOwner?.isCurrent() == true) routeGuidanceController.retireArrivalForExit()
        userReportInteractionOwner.invalidateLocalQuarantineSelection()
        invalidateSpeechOutputStorageBinding()
        invalidateGuidanceStopConfirmation()
        cancelDeviceRuntimeCalibration("backgrounded")
        runtimeLoadMonitor.pause()
        if (runtimeLoadObservationSourceHolder.isInitialized()) runtimeLoadObservationSource.pause()
        runtimeLoadNormalFrameAtMs = null
        cancelForegroundHomeWakeAcknowledgement()
        cancelForegroundHomeWakeListening()
        clearHomeDestinationVoiceDialog(VoiceDialogDiagnosticReason.BACKGROUNDED)
        clearPendingExplicitRouteStart()
        cancelDestinationSearchLocation()
        cancelNativePrewalkPreparation(cancelFeatureEntry = true)
        cancelUserReportAuthorityExpirySchedule()
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.FIRST_RUN_WAITING_CARD)) updateFirstRunWaitingDots(active = false)
        stopHandsFreeVoiceService()
        cancelGatewaySpeechInteraction("app_paused")
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            rawCollectionTransferController.clearUploadWalk()
            rawCollectionRuntimeCoordinator.cancelActiveUpload()
            revalidateRawCollectionRuntime()
        }
        postLoginDeviceCheckController.enteredBackground()
        emailAccountController.enteredBackground()
        cancelReportQueueDrain()
        unregisterPostWalkPowerConnectedReceiver()
        if (!privacyStartupInspectionComplete) {
            isActivityForeground = false
            feedbackLifecycleGeneration += 1
            super.onPause()
            return
        }
        pauseWalkSafeRuntime()
        if (cameraFallbackControllerHolder.isInitialized()) {
            cameraFallbackController.moveTo(Lifecycle.State.CREATED)
        }
        super.onPause()
    }

    internal fun pauseWalkSafeRuntime() {
        cancelPendingPriorityUserTrainingFeedback()
        invalidatePendingExplicitReport()
        if (::walkSessionLifecycle.isInitialized) {
            transitionWalkSession(WalkSessionEvent.EnteredBackground)
            persistWalkSessionInterruptionMarker()
        }
        invalidateOfficialEnvironmentEvidence("app_paused")
        invalidatePhoneMountingEvidence("app_paused")
        isActivityForeground = false
        feedbackLifecycleGeneration += 1
        if (::surfaceView.isInitialized) {
            syncGlSurfaceRenderMode(forceFrame = true)
            surfaceView.onPause()
        }
        this@MainActivity.runtimeMetricInvalidation.invalidate("app_paused")
        confirmedStartupCapabilityDecision = null
        startupCapabilityConfirmationPending = false
        walkSessionResumeController.clearResumeState()
        gatewayWalkSessionController.clearResumeRevalidation()
        this@MainActivity.gatewayWalkSessionController.cancelPendingGatewayWalkStart()
        invalidateArCoreAvailabilityRecheck()
        cancelVoiceCommandRecognition()
        synchronized(reportUploadSafetyLock) {
            reportUploadSafetyGeneration += 1L
            reportPrivacyConsentSession.cancelActiveCalls()
        }
        invalidateFrameStateForPause()
        val navigationCancellation = cancelNavigationRequestsForPause()
        this@MainActivity.routeAcquisitionController.suspendNavigationForRecovery(navigationCancellation)
        syncActiveSessionScreenPolicy()
        speechOutputController.cancelPendingTalkBackInteraction()
        cancelPendingFeedbackTerminalResolution()
        this@MainActivity.riskFeedbackComponents.delivery.resetDeliveryState()
        speechOutputController.resetTalkBackHoldsAfterPause()
        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("app_paused")
        if (
            ::fieldSessionLog.isInitialized &&
            permissionRecoveryGate.blocksAutomaticResourceStart
        ) {
            fieldSessionLog.blockActiveSessionRestore()
        }
        stopLocationUpdates()
        stopStepTracking()
        if (::phoneMountingSensorProbe.isInitialized) phoneMountingSensorProbe.stop()
        if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop()
        this@MainActivity.riskFeedbackComponents.delivery.cancelPendingFeedbackDeliveries()
        nonMetricAdvisoryPolicy.reset()
        resetTactileDotReferenceDelivery()
        tactileReferenceDelivery.resetCrosswalk()
        speechOutputController.closeActuator()
        arSessionOwner.observe().session?.pause()
    }

    private fun invalidateFrameStateForPause() {
        synchronized(frameStateLock) {
            primaryDetectorOwner.retireFrameGeneration()
            resetVisualTrackingState()
            frameSynthesisOwner.clearDetectionSnapshot()
            reportCandidateController.clearFrameCapture()
            reportCandidateController.setStatus("reportCandidate=blocked:runtime_paused")
            frameCaptureRequested.set(false)
            reportCandidateController.resetLocationStartSchedule()
            primaryDetectorOwner.resetPacing()
            framePresentation.resetOverlayThrottle()
            framePresentation.resetUiThrottle()
            latestTactileRouteState = "localRoute=tmap:tactile_not_visible"
            frameSynthesisOwner.resetFrozenDepthPipeline { stepLengthEstimator.stepLengthM }
            fieldDiagnosticRecording.clearMetadata()
        }
        if (::debugBboxOverlay.isInitialized) runOnUiThread { debugBboxOverlay.clear() }
        if (::debugFrameCaptureButton.isInitialized) runOnUiThread { updateFrameCaptureButton() }
    }

    override fun onDestroy() {
        closeGuidanceTouchGuard()
        closeVoiceHelp(announce = false)
        dismissWalkExitConfirmation()
        accountDeletionPreparationController.cancelInstallationKeyPreparation()
        cancelRouteWarmingReassessment()
        guidanceDiagnosticRuntime?.let { privacyStartupResources.releaseOnWorker(it) }
        reportCleanupCallbackHandler.removeCallbacks(guidanceDiagnosticTick)
        retireSpeechOutputCollection()
        speechOutputStorageCoordinator.collectionOrNull()?.let { collection ->
            collection.drainFuture.compareAndSet(null, collection.store.closeAndDrain())
        }
        gatewaySessionController.cancelRestorationRetryTimer()
        cancelPendingPriorityUserTrainingFeedback()
        fieldDiagnosticRecording.closeHeartbeat()
        walkStopDelivery.close()
        if (runtimeLoadObservationSourceHolder.isInitialized()) runtimeLoadObservationSource.close()
        primaryDetectorOwner.fenceForClose()
        cancelDestinationSearchLocation()
        initialAppPermissionExitDialog?.dismiss()
        initialAppPermissionExitDialog = null
        cancelNativePrewalkPreparation(cancelFeatureEntry = true)
        cancelUserReportAuthorityExpirySchedule()
        invalidatePendingExplicitReport()
        closeHandsFreeVoice()
        cancelGatewaySpeechInteraction("app_destroyed")
        voiceInputController.gateway.shutdownWorker()
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            if (rawCollectionTransferControllerHolder.isInitialized()) rawCollectionTransferController.clearUploadWalk()
            privacyStartupResources.releaseOnWorker(rawCollectionRuntimeCoordinator)
        }
        if (rawCollectionTransferControllerHolder.isInitialized()) {
            privacyStartupResources.releaseOnWorker(rawCollectionTransferController)
        }
        emailAccountController.activityDestroyed()
        cancelReportQueueDrain()
        reportQueueDrainController.shutdownExecutor()
        clearUserReportRequestUiForAuthorityFence()
        if (::userReportController.isInitialized) userReportController.onDestroy()
        privacyStartupInspectionController.destroy()
        unregisterGatewayCapacityNetworkObserver()
        cancelEncryptedRouteSnapshotExpirySchedule()
        routeArchiveController.detach()
        privacyStartupInspectionController.clearPendingReady()
        if (!privacyStartupInspectionComplete) {
            runCatching { privacyStartupResources.closeOnUiThread() }
            if (::accountDeletionActivityLease.isInitialized) {
                accountDeletionProcessCoordinator.detach(accountDeletionActivityLease)
            }
            schedulePrivacyStartupResourcesClose()
            reportCleanupExecutor.shutdown()
            if (cameraFallbackControllerHolder.isInitialized()) {
                cameraFallbackController.moveTo(Lifecycle.State.DESTROYED)
            }
            routeExecutor.shutdownNow()
            super.onDestroy()
            return
        }
        if (::accountDeletionActivityLease.isInitialized) {
            accountDeletionProcessCoordinator.detach(accountDeletionActivityLease)
        }
        legacyPendingReportQueuePurgeController.destroy()
        reportCleanupExecutor.shutdownNow()
        integratedConsentController.cancelIntegratedConsentControlCall()
        accountDeletionOperationAuthority.destroy()
        privacyStartupResources.releaseOnUiThread(gatewaySessionController)
        if (::gatewayWalkRenewalHandler.isInitialized) {
            gatewayWalkRenewalHandler.removeCallbacksAndMessages(null)
        }
        postWalkTransferController.cancelPendingRetry()
        unregisterPostWalkPowerConnectedReceiver()
        // S03-19: a configuration re-creation hands the paused walk (same id and lease) to the next
        // Activity of this process; finishing and process death keep the reset/new-walk path.
        val walkRetainedForConfigurationChange = isChangingConfigurations &&
            ::walkSessionLifecycle.isInitialized &&
            processWalkConfigurationChangeRetention.retain(
                walkSessionLifecycle,
                gatewayWalkAuthorityController,
                SystemClock.elapsedRealtime(),
            )
        if (!walkRetainedForConfigurationChange) gatewayWalkAuthorityController.reset()
        // S03-19-F2: callbacks this destroyed Activity already queued (renewal, gateway, detector)
        // must not transition the walk it handed over; from here they reach a private placeholder
        // lifecycle with a different epoch, while the next Activity owns the retained one.
        if (walkRetainedForConfigurationChange) {
            walkSessionLifecycle = WalkSessionLifecycle(elapsedRealtimeClock = SystemClock::elapsedRealtime)
        }
        gatewayWalkSessionController.clearDetachedRequestState()
        val destroyedArCloseAction = synchronized(runtimeMetricStateLock) {
            val ownedSession = arSessionOwner.observe().session
            ownedSession?.let { { it.close() } }
        }
        completeDestroyedRuntimePreparation(
            closeAction = destroyedArCloseAction,
            preparation = {
                runRuntimeArInvalidationCleanupStages(
                    { cancelNavigationRequestsForDestroy() },
                    { isActivityForeground = false },
                    { if (::surfaceView.isInitialized) syncGlSurfaceRenderMode(forceFrame = true) },
                    { if (::surfaceView.isInitialized) surfaceView.onPause() },
                )
            },
            cleanupTail = {
                completeDestroyedRuntimeCleanup(
                    { this@MainActivity.runtimeMetricInvalidation.invalidate("app_destroyed") },
                    { invalidateOfficialEnvironmentEvidence("app_destroyed") },
                    { invalidatePhoneMountingEvidence("app_destroyed") },
                    { invalidateArCoreAvailabilityRecheck() },
                    { cancelPendingFeedbackTerminalResolution() },
                    { this@MainActivity.riskFeedbackComponents.delivery.resetDeliveryState() },
                    { syncActiveSessionScreenPolicy() },
                    {
                        if (cameraFallbackControllerHolder.isInitialized()) {
                            cameraFallbackController.moveTo(Lifecycle.State.DESTROYED)
                        }
                    },
                    { stopCameraFallbackSession() },
                    { stopDepthSession(closeSession = true) },
                    { stopLocationUpdates() },
                    { stopStepTracking() },
                    { if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop() },
                    { runCatching { closeGnssQualityObserver() }; Unit },
                    { positioningSessionController.closePedestrianMotionTracker() },
                    { positioningCoordinator.reset() },
                    { schedulePrivacyStartupResourcesClose() },
                    { this@MainActivity.riskFeedbackComponents.delivery.cancelPendingFeedbackDeliveries() },
                    { speechOutputController.closeActuator() },
                    { cancelVoiceCommandRecognition() },
                    { voiceInputController.destroyRecognizer() },
                    { if (::startupCapabilityProbe.isInitialized) privacyStartupResources.releaseOnUiThread(startupCapabilityProbe) },
                    { if (::walkSessionResourceProbe.isInitialized) privacyStartupResources.releaseOnUiThread(walkSessionResourceProbe) },
                    { privacyStartupResources.closeOnUiThread() },
                    { permissionFlowController.clearRequestLeases() },
                    { permissionFlowController.clearPurposeGenerations() },
                    {
                        synchronized(reportUploadSafetyLock) {
                            reportUploadSafetyGeneration += 1L
                            reportPrivacyConsentSession.cancelActiveCalls()
                        }
                    },
                    { routeExecutor.shutdownNow() },
                    { closeDetectorAsync() },
                )
            },
        )
        super.onDestroy()
    }

    internal fun completeDestroyedRuntimePreparation(
        closeAction: (() -> Unit)?,
        preparation: () -> Unit,
        cleanupTail: () -> Boolean,
    ): Boolean {
        var tailCompleted = false
        val stagesCompleted = completeDestroyedRuntimeCleanup(
            {
                synchronized(runtimeMetricStateLock) {
                    runtimeMetricSession.revokeOutput()
                }
                try {
                    preparation()
                } catch (failure: RuntimeException) {
                    // Preserve the original target before invalidation can detach it. A failed
                    // renderer preparation cannot allow native close or an automatic replay.
                    if (closeAction != null && retainRuntimeArSessionCloseOwner(closeAction)) {
                        closeRetainedRuntimeArSession { throw failure }
                    }
                    throw failure
                }
            },
            { tailCompleted = cleanupTail() },
        )
        return stagesCompleted && tailCompleted
    }

    /**
     * Reports synchronous cleanup exceptions and pending AR ownership. Existing resource Boolean
     * returns and asynchronous OS callbacks are preserved; true is not a full OS release ACK.
     */
    internal fun completeDestroyedRuntimeCleanup(vararg actions: () -> Unit): Boolean {
        return completeRuntimeArInvalidationCleanup(
            closeAction = null,
            beforeClose = { runRuntimeArInvalidationCleanupStages(*actions) },
            afterClose = {},
        )
    }

