    private fun copyRuntimeRecognitionInput(image: android.media.Image, frame: Frame,
        capturedAtElapsedRealtimeMs: Long, frameGeneration: Int, walkEpoch: WalkRuntimeEpoch,
        arGeneration: Long, trackingAtAcquisition: Boolean): RuntimeRecognitionInput? {
        val process = GatewaySessionProcessCoordinator.snapshot()
        val actor = reporterUserId
        val captureFacts = if (actor != null && process.session?.actorId == actor &&
            ::walkSessionLifecycle.isInitialized && walkSessionLifecycle.isRuntimeEpochCurrent(walkEpoch))
            ReportFrameCaptureFacts(capturedAtElapsedRealtimeMs, freshTrustedLocationOrNull(capturedAtElapsedRealtimeMs),
                actor, process.session?.accountGenerationOrNull, walkEpoch) else null
        return frameRecognition.copyFrameRecognitionInput(image, frame, capturedAtElapsedRealtimeMs, frameGeneration,
            walkEpoch, arGeneration, trackingAtAcquisition)?.copy(reportCaptureFacts = captureFacts)
    }


