    private fun DepthFrameSnapshot.runtimeMetricValidSampleCount(
        requireFreshRaw: Boolean = false,
    ): Int = validMetricSampleCount(
        minimumRawConfidence = RUNTIME_METRIC_MIN_RAW_CONFIDENCE,
        minimumDistanceMeters = RuntimeMetricPreflightPolicy.MIN_VALID_DISTANCE_METERS,
        maximumDistanceMeters = RuntimeMetricPreflightPolicy.MAX_VALID_DISTANCE_METERS,
        requireFreshRaw = requireFreshRaw,
    )

    /** Aggregates only copied depth values; no pixels or coordinates are written to diagnostics. */
    private fun DepthFrameSnapshot.metricPixelDiagnostics(): String {
        fun summarize(values: IntArray?): String {
            if (values == null) return "MISSING"
            var zeroCount = 0
            var minimumPositiveMm = Int.MAX_VALUE
            var maximumMm = 0
            for (value in values) {
                if (value == 0) zeroCount++
                if (value > 0) minimumPositiveMm = minOf(minimumPositiveMm, value)
                maximumMm = maxOf(maximumMm, value)
            }
            return "count:${values.size},zero:$zeroCount,min_mm:${minimumPositiveMm.takeIf { it != Int.MAX_VALUE } ?: 0},max_mm:$maximumMm"
        }
        val confidenceMaximum = rawConfidence?.values?.maxOfOrNull { it.toInt() and 0xff } ?: -1
        return "raw_pixels=${summarize(rawDepth?.millimeters)} " +
            "full_pixels=${summarize(fullDepth?.millimeters)} raw_conf_max=$confidenceMaximum"
    }

