    private fun currentDestinationSearchAllowsWork(): Boolean =
        (BuildConfig.DEBUG && BuildConfig.WALKSAFE_DEBUG_GUIDANCE_START_BYPASS &&
            isActivityForeground && shouldShowNativeHome()) ||
            currentNavigationCollectionAllowsWork() ||
            (nativeForegroundFeatureContextAvailable() &&
                postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE))

    private fun nativeFeatureAvailable(page: NativeUiPage): Boolean = when (page) {
        NativeUiPage.DESTINATION_SEARCH ->
            nativeUiPublication.isPublished(NativeUiPublication.Target.DESTINATION_QUERY_INPUT) && nativeScreenPresenter.destinationInputEnabled()
        NativeUiPage.DESTINATION_CONFIRM ->
            nativeUiPublication.isPublished(NativeUiPublication.Target.DESTINATION_QUERY_INPUT) &&
                currentDestinationSearchAllowsWork() && !destinationSearchInFlight
        NativeUiPage.VOICE_COMMAND ->
            nativeUiPublication.isPublished(NativeUiPublication.Target.VOICE_REPORT_BUTTON) && nativeScreenPresenter.voiceInputEnabled()
        NativeUiPage.HOME, NativeUiPage.SETTINGS, NativeUiPage.GUIDANCE -> shouldShowNativeHome()
    }

