            val target = if (nativeUiPage == NativeUiPage.GUIDANCE)
                nativeScreenPresenter.guidanceBinding().nativeGuidanceStatusText else nativeScreenPresenter.guidanceBinding().nativeDestinationConfirmationText
            target.post(callback)
        },
        navigationAdmitted: () -> Boolean = ::currentNavigationCollectionAllowsWork,
        start: () -> Unit = ::startNativeDestinationGuidance,
    ) {
