    private fun applyNativePreviewPresentation(
        homeAvailable: Boolean,
        homeVisible: Boolean,
        settingsVisible: Boolean,
        forceSettings: Boolean,
    ) {
        if (!::nativeDeviceCheckPanel.isInitialized || !nativeUiPublication.isPublished(NativeUiPublication.Target.NATIVE_HOME_RESTRICTION_TEXT)) return
        val stage = firstRunOnboardingSnapshot.stage
        val accountPanelVisible = accountAccessPresenter.rootTarget().visibility == View.VISIBLE
        val training = shouldShowFirstRunPhonePosture() || shouldShowFirstRunEducation()
        val deviceState = postLoginDeviceCheckSnapshot.state
        val preview = NativePreviewPresentationReader.read(NativePreviewPresentationPolicy.Input(
            homeAvailable = homeAvailable,
            homeVisible = homeVisible,
            settingsVisible = settingsVisible,
            forceSettings = forceSettings,
            stage = stage,
            accountPanelVisible = accountPanelVisible,
            training = training,
            deviceState = deviceState,
            page = nativeUiPage,
            pendingPage = pendingNativeUiPage,
            prewalkPending = nativePrewalkStartEpoch != null,
            developmentBypass = developmentGuidanceStartBypassEnabled,
        ), object : NativePreviewPresentationReader.Queries {
            override fun runtimeActive() = isWalkSessionRuntimeActive()
            override fun devicePassesFeatureGate() = postLoginDeviceCheckPassesFeatureGate()
            override fun cameraEnabled() = cameraAnalysisFeaturesEnabled()
            override fun featureAvailable(page: NativeUiPage) = nativeFeatureAvailable(page)
            override fun deletionPhase() = accountDeletionStateMachine.phase()
        })
        val accountVisible = preview.accountVisible
        val deviceScreen = preview.deviceScreen
        val deviceDetails = preview.deviceDetails
        val checking = preview.checking
        nativeScreenPresenter.beginPreview(preview)
        val accountSession = GatewaySessionProcessCoordinator.snapshot()
        val accountLogoutVisible = accountVisible && !accountSession.storageBlocked && !accountSession.deletionRecoveryOnly &&
            (backendDeviceRestorePending || accountSession.session?.sessionScope == GatewaySessionScope.GENERAL)
        val accountTone = if (accountVisible && accountAccessPresenter.statusTarget().visibility == View.VISIBLE) when {
            emailAccountController.isRequestInFlight() -> "info"
            stage == FirstRunOnboardingStage.VERIFIED_LOGIN -> "success"
            accountAccessPresenter.statusTarget().text.toString() == "다시 로그인해 주세요." -> "warning"
            else -> "error"
        } else null
        nativeScreenPresenter.renderPreviewAccountAndPreparation(preview,
            NativeScreenPresenter.AccountPreviewFacts(accountLogoutVisible, accountTone))
        updateNativeSafetyEducationUi()
        val phonePostureNotice = nativePhonePostureNotice
        val failureMessage = if (deviceScreen && deviceState == PostLoginDeviceCheckState.FAIL)
            postLoginDeviceCheckFailureMessage(postLoginDeviceCheckSnapshot.failure) else null
        val values = if (deviceDetails) postLoginDeviceCheckItemsMessage().lineSequence()
            .filter { '\t' in it }.associate { it.substringBefore('\t') to it.substringAfter('\t') }
            else emptyMap()
        val wakeProbeActive = postLoginDeviceProbes.wakeActive
        val devicePassesFeatureGate = if (deviceScreen && !checking)
            postLoginDeviceCheckSnapshot.passesFeatureGate else false
        val needsKoreanVoice = startupCapabilityDecision?.unavailableRequirements
            ?.contains(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) == true
        val speechGuidance = offlineKoreanSpeechGuidance()
        nativeScreenPresenter.renderPreviewReadiness(preview, NativeScreenPresenter.ReadinessPreviewFacts(
            phonePostureNotice = phonePostureNotice,
            deviceFailed = deviceState == PostLoginDeviceCheckState.FAIL,
            deviceFailureMessage = failureMessage,
            deviceValues = values,
            wakeProbeActive = wakeProbeActive,
            wakeReady = postLoginWakePhraseSignal == PostLoginDeviceCheckSignal.READY,
            hapticReady = this@MainActivity.postLoginDeviceProbes.hapticSignal == PostLoginDeviceCheckSignal.READY,
            devicePassesFeatureGate = devicePassesFeatureGate,
            needsKoreanVoice = needsKoreanVoice,
            voiceActionLabel = speechGuidance.actionLabel,
            voiceActionContentDescription = speechGuidance.actionContentDescription,
        ))
        refreshRouteCompassPresentation()
        nativeScreenPresenter.finishPreview(preview,
            durableDeletionConfirmationRecovery = preview.deletionConfirm &&
                accountDeletionStateMachine.durableConfirmationRecoveryRequired(),
            overlay = nativeRootOverlay,
        )
    }


