    private val guidancePreparationController: GuidancePreparationController by lazy(LazyThreadSafetyMode.NONE) {
        GuidancePreparationController(nativeWorkflowController,
            object : GuidancePreparationController.Scope {
                override fun reporterId() = reporterUserId
                override fun gatewayGeneration() = GatewaySessionProcessCoordinator.snapshot().generation
                override fun epoch() = walkSessionLifecycle.snapshot().epoch
                override fun walkState() = walkSessionLifecycle.snapshot().state
                override fun foreground() = isActivityForeground
                override fun hasRoute() = routeNavigator.hasRoute()
                override fun preflightFailedOrTimedOut() = officialEnvironmentPreflightPhase in setOf(OfficialEnvironmentPreflightPhase.FAILED, OfficialEnvironmentPreflightPhase.TIMED_OUT)
                override fun locationWaiting() = positionGuidancePaused || currentRouteLocationOrNull() == null
            }, object : GuidancePreparationController.Speech {
                override fun busy() = isGuidanceSpeechInputOrOutputBusy()
                override fun commandGeneration() = commandSpeechResponseGeneration
                override fun cancelRegisteredResponse(generation: Long) {
                    speechOutputController.cancelRegisteredCommandResponse(CommandResponseToken("command-response-$generation", generation))
                }
                override fun cancelCommandInteraction() { feedbackActuator?.cancelCommandInteraction() }
                override fun submitWaitingNotice(message: String, current: () -> Boolean, completed: () -> Unit, failed: () -> Unit) = speakRouteWaitingNotice(message, current, completed, failed)
            }, object : GuidancePreparationController.Callbacks {
                override fun postDelayed(action: Runnable, delayMs: Long) { reportCleanupCallbackHandler.postDelayed(action, delayMs) }
                override fun remove(action: Runnable) { reportCleanupCallbackHandler.removeCallbacks(action) }
            }, SystemClock::elapsedRealtime)
    }

    private val nativeStartAdmission: NativeDestinationStartAdmission by lazy(LazyThreadSafetyMode.NONE) {
        NativeDestinationStartAdmission(nativeWorkflowController,
            object : NativeDestinationStartAdmission.Scope {
                override fun homeAvailable() = shouldShowNativeHome()
                override fun runtimeActive() = isWalkSessionRuntimeActive()
                override fun epoch() = walkSessionLifecycle.snapshot().epoch
                override fun gatewayOwner() = GatewaySessionProcessCoordinator.snapshot().let { NativeDestinationStartAdmission.GatewayOwner(it.generation, it.session) }
                override fun reporterId() = reporterUserId
                override fun permissionRecoveryIdentity(): Any? = permissionRecoveryGate
                override fun routeGeneration() = routeRequestGeneration
            }, object : NativeDestinationStartAdmission.PositioningSource {
                override fun generation() = locationCallbackGeneration
                override fun binding(): NativeDestinationStartAdmission.Binding? {
                    val binding = positioningCollectionBinding ?: return null
                    return NativeDestinationStartAdmission.Binding(binding, binding.owner.actorId, binding.owner.gatewaySession, binding.owner.gatewayGeneration) {
                        positioningCoordinator === binding.coordinator && binding.coordinator.currentInputGeneration() == binding.inputGeneration &&
                            locationCallback != null && locationCollectionOwner == binding.owner
                    }
                }
            })
    }

    private val nativeGuidanceCalibrationSession by lazy(LazyThreadSafetyMode.NONE) {
        NativeGuidanceCalibrationSession(
            object : NativeGuidanceCalibrationSession.Scope {
                override fun requestCurrent(request: NativePhoneMountingCheckRequest) = nativeCalibrationRequestCurrent(request)
                override fun ownerCurrent(request: NativePhoneMountingCheckRequest) = nativeCalibrationOwnerCurrent(request)
            }, object : NativeGuidanceCalibrationSession.Speech {
                override fun pending() = speechOutputController.hasPendingCommandResponse()
                override fun commandGeneration() = commandSpeechResponseGeneration
                override fun submit(message: String, current: () -> Boolean, completed: () -> Unit, failed: () -> Unit) =
                    speakCommandResponse(message, statusExplanation = true, additionalCurrent = current,
                        onCompleted = completed, onFailed = failed, onCancelled = failed, onRetired = failed)
                override fun cancel() { speechOutputController.cancelCommandSpeechResponse() }
            }, object : NativeGuidanceCalibrationSession.Callbacks {
                override fun postDelayed(action: Runnable, delayMs: Long) { reportCleanupCallbackHandler.postDelayed(action, delayMs) }
                override fun remove(action: Runnable) { reportCleanupCallbackHandler.removeCallbacks(action) }
            }, object : NativeGuidanceCalibrationSession.Effects {
                override fun recordStage(stage: String) { recordGuidancePreparationStage(stage) }
                override fun reportVisibleFailure(message: String) { guidancePreparationController.reportVisibleFailure(message) }
                override fun visibleFailure() = guidancePreparationController.visibleFailure
                override fun clearVisibleFailure() { guidancePreparationController.clearVisibleFailure() }
                override fun render() { renderMainUi() }
                override fun continuePrewalk() { continueNativePrewalkIfReady() }
                override fun recoverPreparation(request: NativePhoneMountingCheckRequest) {
                    maybeStartNativeMetricDepthRefresh(request)
                    if (officialEnvironmentPreflightPhase in setOf(OfficialEnvironmentPreflightPhase.FAILED, OfficialEnvironmentPreflightPhase.TIMED_OUT) ||
                        startupCapabilityRetryRequiresUserAction) {
                        startupCapabilityRetryRequiresUserAction = false
                        confirmOfficialEnvironmentConditions()
                    }
                }
            }, SystemClock::elapsedRealtime,
        )
    }

    private fun nativeCalibrationRequestCurrent(request: NativePhoneMountingCheckRequest): Boolean =
        nativePhoneMountingCheckRequest === request && nativeGpsCheckIsCurrent(request.checkRequest.epoch) &&
            firstRunOnboardingComplete()

    private fun nativeCalibrationOwnerCurrent(request: NativePhoneMountingCheckRequest): Boolean =
        nativeCalibrationRequestCurrent(request) && hasLocationPermission()

    /** Existing GPS/heading streams keep collecting while this initial prompt/window is active. */
    private fun maybeStartNativeMetricDepthRefresh(request: NativePhoneMountingCheckRequest, allowRetry: Boolean = false) {
        if (!nativeCalibrationOwnerCurrent(request) || !::startupCapabilityProbe.isInitialized ||
            metricDistanceCapabilityOverride != null || isWalkSessionRuntimeActive() ||
            metricPreflightOwner != RuntimeMetricPreflightOwner.NONE ||
            !postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE) ||
            WalkSafeStartupRequirement.METRIC_DISTANCE !in resolveCurrentStartupCapabilityDecision().pendingRequirements) return
        val binding = postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (!postLoginDeviceCheckSnapshot.passesFeatureGate ||
            !postLoginDeviceCheckController.isSnapshotBindingLive(binding)) return
        if (!postLoginDeviceCheckController.storedMetricRefreshIsPending) {
            postLoginDeviceCheckController.prepareStoredMetricRefresh(postLoginDeviceCheckSnapshot, postLoginCameraDependentChecksDeferred)
        }
        if (allowRetry) postLoginDeviceCheckController.allowStoredMetricRetry()
        postLoginDeviceCheckController.maybeStartStoredMetricRefresh()
    }

    private fun advanceNativeGuidanceCalibration(request: NativePhoneMountingCheckRequest): Boolean =
        nativeGuidanceCalibrationSession.advance(request)

    private fun cancelNativeGuidanceCalibration() = nativeGuidanceCalibrationSession.cancel()

    private fun cancelNativeCalibrationPrompt() = nativeGuidanceCalibrationSession.cancelPrompt()

    private fun scheduleNativePreparationRecovery(request: NativePhoneMountingCheckRequest) =
        nativeGuidanceCalibrationSession.scheduleRecovery(request)

    private val nativePrewalkController: NativePrewalkController by lazy(LazyThreadSafetyMode.NONE) {
        NativePrewalkController(nativeWorkflowController,
            object : NativePrewalkController.Scope {
                override fun homeAvailable() = shouldShowNativeHome()
                override fun foreground() = isActivityForeground
                override fun reporterId() = reporterUserId
                override fun gatewayGeneration() = GatewaySessionProcessCoordinator.snapshot().generation
                override fun runtimeActive() = isWalkSessionRuntimeActive()
                override fun walk() = walkSessionLifecycle.snapshot()
                override fun developmentBypass() = developmentGuidanceStartBypassEnabled
            }, object : NativePrewalkController.Checks {
                override fun firstRunComplete() = firstRunOnboardingComplete()
                override fun postLoginState() = postLoginDeviceCheckSnapshot.state
                override fun environmentProfilesPresent() = activeEnvironmentProfiles != null
                override fun officialProfilePresent() = activeOfficialEnvironmentProfile != null
                override fun cameraEnabled() = cameraAnalysisFeaturesEnabled()
                override fun mountingProfilePresent() = activePhoneMountingProfile != null
                override fun preflightFailedOrTimedOut() = officialEnvironmentPreflightPhase in setOf(OfficialEnvironmentPreflightPhase.FAILED, OfficialEnvironmentPreflightPhase.TIMED_OUT)
                override fun preflightMeasuring() = officialEnvironmentPreflightPhase == OfficialEnvironmentPreflightPhase.MEASURING
                override fun startupRetryRequired() = startupCapabilityRetryRequiresUserAction
                override fun locationAccessUnavailable() = !hasLocationPermission() || !isLocationServiceEnabledForDeviceCheck()
                override fun environmentReadiness(epoch: WalkRuntimeEpoch) = officialEnvironmentReadiness(epoch).first
                override fun mountingReadiness(epoch: WalkRuntimeEpoch) = phoneMountingReadiness(epoch).first
                override fun startupDecision() = startupCapabilityDecision
                override fun readinessBlockReason(decision: WalkSafeStartupCapabilityDecision) = walkSessionReadinessBlockReason(decision)
                override fun confirmationPending() = startupCapabilityConfirmationPending
                override fun startupConfirmed() = isStartupCapabilityConfirmed()
                override fun cameraDiagnosticReason() = officialEnvironmentCameraDiagnosticReason
                override fun cameraAdjustmentDetail() = officialEnvironmentMeasurementDetail(currentOfficialEnvironmentAssessment(), false).lineSequence().firstOrNull { it.startsWith("카메라:") }
                override fun failureSpeech(): String {
                    if (!hasLocationPermission()) return "위치 권한이 꺼져 있습니다. 앱의 위치 권한을 허용해 주세요. 허용되면 안내 준비를 자동으로 이어갑니다."
                    if (!isLocationServiceEnabledForDeviceCheck()) return "휴대전화의 위치 서비스가 꺼져 있습니다. 위치 서비스를 켜주세요. 켜지면 안내 준비를 자동으로 이어갑니다."
                    val mounting = currentPhoneMountingAssessment()
                    return if (startupCapabilityRetryRequiresUserAction) "필수 음성 안내를 완료하지 못했습니다. 한국어 음성 기능을 확인해 주세요."
                    else officialEnvironmentFailureSpeech(currentOfficialEnvironmentAssessment()).ifBlank {
                        if (!mounting.canStartOrResumeDetection) "${mounting.accessibleReasonKo} ${mounting.accessibleActionKo}"
                        else "점검을 완료하지 못했습니다. 현재 상태를 다시 확인하고 있습니다."
                    }
                }
            }, object : NativePrewalkController.Speech {
                override fun commandPending() = speechOutputController.hasPendingCommandResponse()
                override fun submit(message: String, current: () -> Boolean, completed: () -> Unit, failed: () -> Unit, cancelled: () -> Unit, retired: () -> Unit) = speakCommandResponse(
                    message = message, statusExplanation = true, additionalCurrent = current,
                    onCompleted = completed, onFailed = failed, onCancelled = cancelled, onRetired = retired)
            }, object : NativePrewalkController.Actions {
                override fun showPage(page: NativeUiPage) { showNativeUiPage(page) }
                override fun ensureVoicePermissionThenListen() { this@MainActivity.ensureVoicePermissionThenListen() }
                override fun showHomeLockNotice(title: String, detail: String) { showHomeCardLockNotice(title, detail) }
                override fun preparationDialogShowing(): Boolean {
                    if (nativeGuidanceConfirmationScreen != null && nativeGuidanceConfirmationCurrent?.invoke() == false) dismissNativeGuidanceConfirmation()
                    return nativePrewalkDialog?.isShowing == true || nativeGuidanceConfirmationScreen != null
                }
                override fun postStartup(action: () -> Unit) { firstRunOnboardingPresenter.readinessBinding().startupCapabilityText.post { action() } }
                override fun cancelPendingFeatureEntry() { cancelNativePendingFeatureEntry() }
                override fun showStatus(title: String, detail: String) { updateStatus(title, detail) }
                override fun requestDevelopmentGuidanceStart() { developmentGuidanceStartRequested = true }
                override fun startPostLoginCheck() { startPostLoginDeviceCheckFromPrimaryAction() }
                override fun renderMain() { renderMainUi() }
                override fun startFreshWalk(reason: String) {
                    val previousEpoch = walkSessionLifecycle.snapshot().epoch
                    this@MainActivity.walkSessionCleanupController.startFreshWalk(reason)
                    val current = walkSessionLifecycle.snapshot()
                    // NewWalkRequested resets foreground; publish the actual Activity state only
                    // after cleanup completed and installed a fresh, unadmitted READY session.
                    if (isActivityForeground && current.state == WalkSessionState.READY &&
                        current.epoch != previousEpoch && !current.isForeground) {
                        transitionWalkSession(WalkSessionEvent.EnteredForeground)
                    }
                }
                override fun beginDevelopmentGuidance(walk: WalkSessionSnapshot) { beginDevelopmentGuidanceImmediately(walk) }
                override fun clearStartupRetryRequirement() { startupCapabilityRetryRequiresUserAction = false }
                override fun confirmEnvironment() { confirmOfficialEnvironmentConditions() }
                override fun beginCalibration(request: NativePhoneMountingCheckRequest) {
                    if (nativeCalibrationOwnerCurrent(request)) {
                        voiceDataSettingsRecovery.ensurePendingKoreanSpeechProbeStarted()
                        maybeStartNativeMetricDepthRefresh(request, allowRetry = true)
                    }
                    advanceNativeGuidanceCalibration(request)
                }
                override fun calibrationReady(request: NativePhoneMountingCheckRequest): Boolean {
                    maybeStartNativeMetricDepthRefresh(request)
                    return advanceNativeGuidanceCalibration(request)
                }
                override fun cancelCalibration() { cancelNativeGuidanceCalibration() }
                override fun cancelCalibrationForLocationAccess() { cancelNativeCalibrationPrompt() }
                override fun retryPreparation(request: NativePhoneMountingCheckRequest) { scheduleNativePreparationRecovery(request) }
                override fun requestStartConfirmation(current: () -> Boolean, confirmed: () -> Unit) {
                    if (pendingUiDestination != null) {
                        if (nativeUiPage != NativeUiPage.GUIDANCE || voiceHelpScreen != null || walkExitConfirmationScreen != null) return
                        nativeGuidanceConfirmationCurrent = current
                        requestNativeGuidanceStartConfirmation {
                            if (current()) confirmed()
                            else {
                                speakInteraction("준비 상태가 바뀌어 다시 확인합니다.")
                                continueNativePrewalkIfReady()
                            }
                        }
                    } else if (current()) confirmed()
                }
                override fun completeStartupConfirmation(decision: WalkSafeStartupCapabilityDecision) {
                    if (walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED) {
                        this@MainActivity.startupConfirmationInteraction.confirmStartupCapabilityDecision()
                    } else {
                        this@MainActivity.startupConfirmationInteraction.completeStartupCapabilityConfirmation(decision)
                    }
                }
                override fun completePermissionRecoveryRecheck() { completePermissionRecoveryRecheckIfPossible() }
                override fun discardAndStopEnvironmentCamera() { officialEnvironmentPreflightController.discardAfterRelease(); stopOfficialEnvironmentCameraPreflight() }
                override fun clearPrewalkConsent() { nativePrewalkConsentEpoch = null; nativePrewalkConsentAtElapsedRealtimeMs = null }
                override fun dismissPreparationDialog() { dismissNativeGuidanceConfirmation(); val dialog = nativePrewalkDialog; nativePrewalkDialog = null; dialog?.dismiss() }
                override fun cancelPreparationSpeech() { cancelGuidancePreparationSpeech() }
                override fun postFailureRetry(delayMs: Long, action: () -> Unit) { nativeScreenPresenter.guidanceBinding().nativeGuidanceStatusText.postDelayed({ action() }, delayMs) }
                override fun publishSpeechFailure(message: String) { guidancePreparationController.reportVisibleFailure(message) }
            }, object : NativePrewalkController.Diagnostics {
                override fun enabled() = BuildConfig.DEBUG
                override fun capture(stage: String, epoch: WalkRuntimeEpoch, actorId: String?, confirmationPosted: Boolean): String {
                    val walk = walkSessionLifecycle.snapshot()
            val prewalkState = walk.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED)
            val environment = if (prewalkState) officialEnvironmentReadiness(epoch) else null
            val mounting = if (prewalkState) phoneMountingReadiness(epoch) else null
            val decision = startupCapabilityDecision
            val request = nativePhoneMountingCheckRequest
            if (guidanceDiagnosticRuntime != null) {
                val nowMs = SystemClock.elapsedRealtime()
                for (event in GuidanceDiagnosticMetadata.prewalk(stage, walk.state, officialEnvironmentPreflightPhase,
                    environment?.first, mounting?.first, decision?.pendingRequirements.orEmpty(),
                    decision?.unavailableRequirements.orEmpty(), decision?.mayConfirmAndStart,
                    walk.confirmationToken != null, confirmationPosted, startupCapabilityConfirmationPending,
                    isStartupCapabilityConfirmed())) {
                    val channel = "prewalk_${event.fields["stage"]}_${event.fields["gate_reason"] ?: ""}"
                    if (guidanceDiagnosticFilter.admit(channel, event.fields.toString(), nowMs))
                        recordGuidanceDiagnosticEvent(event.name, event.fields)
                }
            }
            val state = "stage=$stage walkState=${walk.state.name} " +
                "phase=${officialEnvironmentPreflightPhase.name} " +
                "environment=${environment?.first?.name ?: "not_preflight"} environmentReason=${environment?.second?.ifBlank { "none" } ?: "not_preflight"} " +
                "mounting=${mounting?.first?.name ?: "not_preflight"} mountingReason=${mounting?.second?.ifBlank { "none" } ?: "not_preflight"} " +
                "foreground=$isActivityForeground epochCurrent=${walk.epoch == epoch} " +
                "actorCurrent=${nativePrewalkActorId == reporterUserId} " +
                "gatewayCurrent=${request?.gatewayGeneration == GatewaySessionProcessCoordinator.snapshot().generation} " +
                "destinationCurrent=${request?.destination == null || request.destination == pendingUiDestination} " +
                "decisionPresent=${decision != null} decisionMayStart=${decision?.mayConfirmAndStart} " +
                "decisionPending=${decision?.pendingRequirements?.joinToString(",") { it.name }.orEmpty()} " +
                "decisionUnavailable=${decision?.unavailableRequirements?.joinToString(",") { it.name }.orEmpty()} " +
                "tokenPresent=${walk.confirmationToken != null} " +
                "confirmationPosted=$confirmationPosted confirmationPending=$startupCapabilityConfirmationPending " +
                "confirmed=${isStartupCapabilityConfirmed()} modelAvailable=${primaryDetectorOwner.projection().available} " +
                "modelLoading=${primaryDetectorLifecycleController.metadata().loadInFlight} modelAttempted=${primaryDetectorLifecycleController.metadata().loadAttempted}"
            return state
                }
                override fun record(state: String) { android.util.Log.d("WalkSafePrewalkGate", state) }
                override fun directStart(state: WalkSessionState) { if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeNavigation", "event=NATIVE_PREWALK_DIRECT_START state=${state.name}") }
            }, SystemClock::elapsedRealtime)
    }

