    private fun shouldShowFirstRunEducation(): Boolean =
        firstRunOnboardingController.initialized &&
            priorityUserProfileController.policyInitialized &&
            firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
            firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.FP004_TRAINING &&
            !priorityUserOnboardingPolicy.snapshot().safetyEducationConsentComplete

    private fun currentFirstRunEducationEvidenceComplete(): Boolean =
        if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            priorityUserOnboardingPolicy.snapshot().nativeEducationComplete
        } else {
            priorityUserOnboardingPolicy.snapshot().interactivePracticeComplete
        }

    private fun shouldShowNativeHome(): Boolean {
        if (!firstRunOnboardingController.initialized ||
            !priorityUserProfileController.policyInitialized || initialAppPermissionExitRequired ||
            !firstRunOnboardingSnapshot.isComplete ||
            !priorityUserOnboardingPolicy.snapshot().nativeEducationComplete) return false
        val actorId = firstRunOnboardingSnapshot.verifiedActorBinding?.value ?: return false
        val process = GatewaySessionProcessCoordinator.snapshot()
        val currentSession = process.session ?: return false
        return actorId == reporterUserId && actorId == priorityUserOnboardingActorId &&
            currentSession.actorId == actorId &&
            currentSession.verificationState == GatewaySessionVerificationState.VERIFIED &&
            currentSession.isUsableFor(actorId) && !process.storageBlocked &&
            !process.deletionRecoveryOnly && !accountDeletionStateMachine.processingBlocked()
    }

    private fun updateNativeSafetyEducationUi() {
        if (!nativeUiPublication.isPublished(NativeUiPublication.Target.FIRST_RUN_PHONE_POSTURE_CONTROLS) ||
            !nativeUiPublication.isPublished(NativeUiPublication.Target.PRIORITY_USER_EDUCATION_AGREE_BUTTON)) return
        val state = priorityUserOnboardingPolicy.snapshot()
        val showPosture = shouldShowFirstRunPhonePosture()
        val showEducation = shouldShowFirstRunEducation()
        val actorId = firstRunOnboardingSnapshot.verifiedActorBinding?.value
        val eligible = actorId != null && actorId == reporterUserId &&
            actorId == priorityUserOnboardingActorId && postLoginDeviceCheckPassesFeatureGate() &&
            priorityUserOnboardingPolicy.accountBlockReason() == null
        val screenReaderReview = isScreenReaderActive()
        val necessityPlaying = educationInteractionController.presentationState().educationInFlight && educationInteractionController.presentationState().playbackIsPracticeNecessity
        val playback = if (!educationInteractionController.presentationState().educationInFlight) null else when {
            showPosture -> PriorityUserEducationPlayback.APP_USAGE
            necessityPlaying -> PriorityUserEducationPlayback.PRACTICE_NECESSITY
            else -> PriorityUserEducationPlayback.SAFETY_LIMITS
        }
        val hazardResponseReady = educationInteractionController.hazardResponseReady(priorityUserOnboardingPolicy)
        val body = PriorityUserEducationPresentation.screenText(state) +
            educationInteractionController.presentationState().practiceInFlight?.let { "\n\n${it.actionLabelKo} 안내\n${it.instructionKo}" }.orEmpty()
        val progress = PriorityUserEducationPresentation.progressNotice(
            state, playback, educationInteractionController.presentationState().practiceInFlight, hazardResponseReady, screenReaderReview,
        )
        val prepareFeedback = firstRunOnboardingPresenter.updateNativeSafetyEducationUi(
            FirstRunOnboardingPresenter.NativeEducationFacts(
                state = firstRunEducationViewState(state),
                showPosture = showPosture,
                showEducation = showEducation,
                eligible = eligible,
                educationInFlight = educationInteractionController.presentationState().educationInFlight,
                playbackIsPracticeNecessity = educationInteractionController.presentationState().playbackIsPracticeNecessity,
                practiceInFlight = educationInteractionController.presentationState().practiceInFlight,
                screenReaderReview = screenReaderReview,
                hazardResponseReady = hazardResponseReady,
                body = body,
                progress = progress,
                activityForeground = isActivityForeground,
            ),
        )
        if (prepareFeedback) ensureFeedbackActuator()
    }

