    private fun nativeDestinationPreparationMessage(includeMeasurements: Boolean = true): String {
        val environment = currentOfficialEnvironmentAssessment()
        val mounting = currentPhoneMountingAssessment()
        val retry = officialEnvironmentPreflightPhase in setOf(
            OfficialEnvironmentPreflightPhase.FAILED, OfficialEnvironmentPreflightPhase.TIMED_OUT,
        ) || startupCapabilityRetryRequiresUserAction
        return listOf(
            when (officialEnvironmentPreflightPhase) {
                OfficialEnvironmentPreflightPhase.TIMED_OUT -> "자동 점검 시간이 초과되었습니다."
                OfficialEnvironmentPreflightPhase.FAILED -> "자동 점검을 완료하지 못했습니다."
                else -> "안내 준비 중: 현재 위치와 카메라·자세를 실제로 점검합니다."
            },
            officialEnvironmentMeasurementDetail(environment, includeMeasurements).trim(),
            if (!mounting.canStartOrResumeDetection) mounting.accessibleReasonKo else "",
            if (!mounting.canStartOrResumeDetection) mounting.accessibleActionKo else "",
            if (retry) "현재 상태를 다시 확인하고 있습니다. 조건이 회복되면 안내를 자동으로 이어갑니다."
            else "실제 보행 준비 조건이 충족되면 경로와 객체인식 안내를 자동으로 시작합니다.",
        ).filter { it.isNotBlank() }.joinToString("\n")
    }

    private fun startNativeDestinationGuidance() {
        if (handleNativeGuidanceResumeAction()) return
        refreshGuidanceDiagnosticAuthority()
        guidanceDiagnosticRuntime?.startGuidanceSession()
        nativeGuidanceEntryController.start()
    }

    // The visible confirmation delegates notice delivery and live admission to the existing owner.
    internal fun currentNativeGuidanceResumeAction(): DestinationGuidanceResumeAction {
        val walk = walkSessionLifecycle.snapshot()
        val none = DestinationGuidanceResumeAction.NONE
        if (nativeUiPage != NativeUiPage.GUIDANCE || !isActivityForeground || !walk.isForeground ||
            walk.state != WalkSessionState.PAUSED ||
            walk.recoveryStage != WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION ||
            walk.confirmationToken == null) return none
        if (startupCapabilityConfirmationPending || (walkSessionResumeController.promptPending &&
                !walkSessionResumeController.awaitingResponseToDeliveredPrompt)) {
            return DestinationGuidanceResumeAction.PENDING
        }
        val request = nativePhoneMountingCheckRequest ?: return none
        if (!nativeGuidanceCalibrationSession.isReady(request)) return DestinationGuidanceResumeAction.PREPARING
        return if (isStartupCapabilityConfirmed()) DestinationGuidanceResumeAction.CONFIRM
            else DestinationGuidanceResumeAction.NOTICE
    }

    /** Within awaiting-resume, stale/pending clicks are consumed; a missing native request can retry preparation. */
    internal fun handleNativeGuidanceResumeAction(confirm: () -> Unit = ::confirmNativeGuidanceResumeFromTouch): Boolean {
        val walk = walkSessionLifecycle.snapshot()
        if (nativeUiPage != NativeUiPage.GUIDANCE || walk.state != WalkSessionState.PAUSED ||
            walk.recoveryStage != WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION) return false
        if (!isActivityForeground || !walk.isForeground || walk.confirmationToken == null) return true
        when (currentNativeGuidanceResumeAction()) {
            DestinationGuidanceResumeAction.CONFIRM, DestinationGuidanceResumeAction.NOTICE -> confirm()
            DestinationGuidanceResumeAction.NONE -> return false
            DestinationGuidanceResumeAction.PREPARING, DestinationGuidanceResumeAction.PENDING -> Unit
        }
        return true
    }

    private fun confirmNativeGuidanceResumeFromTouch() {
        if (walkSessionResumeController.awaitingResponseToDeliveredPrompt) {
            cancelVoiceCommandRecognition()
        }
        startupConfirmationInteraction.handleStartupCapabilityConfirmAction(preferTouchResume = true)
    }

