    private fun currentNativeGuidancePresentation(): DestinationGuidancePresentation {
        if (arrivalEndingOwner?.isCurrent() == true) {
            return DestinationGuidancePresentation(
                DestinationGuidanceDisplayStage.ARRIVED, "도착했습니다", "도착했습니다. 안내를 종료합니다",
                "카메라·객체인식 안내를 종료했습니다.", retryAvailable = false,
            )
        }
        val runtimeActive = isWalkSessionRuntimeActive()
        val environment = currentOfficialEnvironmentAssessment()
        val mounting = currentPhoneMountingAssessment(
            phase = if (runtimeActive) PhoneMountingAssessmentPhase.ACTIVE
                else PhoneMountingAssessmentPhase.PREFLIGHT,
            previousState = if (runtimeActive) phoneMountingRuntimeState else null,
        )
        val measuring = officialEnvironmentPreflightPhase == OfficialEnvironmentPreflightPhase.MEASURING &&
            nativePhoneMountingCheckRequest != null
        val routeInput = currentRouteGuidanceDisplayInput(runtimeActive)
        val cameraEngineStarted = runtimeActive && primaryDetectorOwner.projection().available && (
            arSessionOwner.observe().session != null && arSessionOwner.observe().purpose == ArSessionPurpose.RUNTIME ||
                cameraFallbackRequested && cameraFallbackRunning
            )
        val cameraOutputAvailable = cameraEngineStarted && currentFeedbackDeviceGateAllowsAlerts()
        val cameraReason = when {
            !hasCameraPermission() -> "설정에서 카메라 권한을 허용해 주세요."
            runningDetectorBlocksWalkEntry() ->
                kr.co.hanium.dreamup.walksafe.device.RunningDetectorReadiness.WALK_BLOCK_NOTICE_KO
            !cameraAnalysisFeaturesEnabled() -> "현재 기기 기능 설정에서 카메라 안내를 사용할 수 없습니다."
            !developmentGuidanceStartBypassEnabled && !mounting.canStartOrResumeDetection ->
                phoneMountingFailureSpeech(mounting, environment)
            !primaryDetectorOwner.projection().available -> "객체인식 모델이 아직 준비되지 않았습니다."
            cameraEngineStarted && !cameraOutputAvailable &&
                primaryDetectorLifecycleController.verificationState(primaryDetectorOwner.projection().detector) !=
                kr.co.hanium.dreamup.walksafe.inference.RunningDetectorVerificationState.VERIFIED ->
                kr.co.hanium.dreamup.walksafe.device.RunningDetectorReadiness.CHECKING_NOTICE_KO
            cameraEngineStarted && !cameraOutputAvailable ->
                "객체인식 엔진이 준비됐지만 실제 안내 출력 조건을 확인하고 있습니다."
            else -> null
        }
        val retry = officialEnvironmentPreflightPhase in setOf(
            OfficialEnvironmentPreflightPhase.FAILED, OfficialEnvironmentPreflightPhase.TIMED_OUT,
        ) || startupCapabilityRetryRequiresUserAction ||
            !runtimeActive && nativePrewalkStartEpoch == null ||
            runtimeActive && !routeInput.preparationRunning && !routeInput.outputRunning
        val resumeAction = currentNativeGuidanceResumeAction()
        val arrivalConfirmationPending =
            routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION
        val presentation = DestinationGuidancePresentationPolicy.present(
            route = routeInput.copy(preparationRunning = routeInput.preparationRunning || measuring),
            camera = GuidanceFeatureDisplayInput(cameraOutputAvailable, measuring || cameraEngineStarted, cameraReason),
            retryAvailable = retry && !arrivalConfirmationPending,
            arrivalConfirmed = routeAcquisitionController.hasCurrentConfirmedArrival,
            arrivalConfirmationPending = arrivalConfirmationPending,
        ).let { original -> original.copy(
            resumeAction = resumeAction,
            titleKo = when (resumeAction) {
                DestinationGuidanceResumeAction.PREPARING -> "보행 재개 준비 중"
                DestinationGuidanceResumeAction.NOTICE -> "안전 제한 안내 확인 필요"
                DestinationGuidanceResumeAction.CONFIRM -> "보행 안내 일시중지"
                DestinationGuidanceResumeAction.PENDING -> "보행 재개 확인 중"
                DestinationGuidanceResumeAction.NONE -> original.titleKo
            },
        ) }
        BoundedRuntimeDiagnosticLog.recordState(
            domain = RuntimeDiagnosticDomain.NAVIGATION,
            stage = presentation.stage,
            reason = mounting.reason,
            context = OfficialEnvironmentFactor.CAMERA_QUALITY,
        )
        BoundedRuntimeDiagnosticLog.recordState(
            domain = RuntimeDiagnosticDomain.NAVIGATION,
            stage = presentation.stage,
            reason = environment.factorStatuses[OfficialEnvironmentFactor.GPS_QUALITY],
            context = OfficialEnvironmentFactor.GPS_QUALITY,
        )
        return presentation
    }

    /** Route presentation reads Main/Navigator state; callbacks observe only SDK-backed admission/location. */
    internal fun currentRouteGuidanceDisplayInput(
        runtimeActive: Boolean = isWalkSessionRuntimeActive(),
        collectionAllowsWork: () -> Boolean = ::currentNavigationCollectionAllowsWork,
        trustedLocationAvailable: () -> Boolean = { currentRouteLocationOrNull() != null },
        locationPermissionReady: () -> Boolean = ::isRouteLocationPermissionReady,
        locationServiceEnabled: () -> Boolean = ::isLocationServiceEnabledForDeviceCheck,
        elapsedRealtimeMs: () -> Long = currentStateSpeechElapsedRealtime,
    ): GuidanceFeatureDisplayInput {
        val geometryGrace = isRouteActive && routeNavigator.hasRoute() &&
            routeNavigator.hasCurrentRouteGeometryGrace(elapsedRealtimeMs)
        val warmingReference = isRouteActive && routeNavigator.hasCurrentNavigationOnlyReference(elapsedRealtimeMs)
        val initialJoinPending = isRouteActive && routeNavigator.isWaitingForInitialRouteJoin()
        val routeRequestPending = routeAcquisitionController.requestPending || routeAcquisitionController.explicitStart != null
        val routePending = routeRequestPending || initialJoinPending ||
            installedRouteStartSpeechCoordinator.pending?.isCurrent?.invoke() == true
        val pendingDecision = routeNavigator.pendingUserDecision()
        val routeStatus = if (::navigationStatusText.isInitialized)
            navigationStatusText.text.toString().split(' ') else emptyList()
        val backendReason = NativeRouteGuidancePresentation.backendFailureReason(routeStatus)
        val trustedLocationReady = trustedLocationAvailable()
        val approachReady = runtimeActive && collectionAllowsWork() && isRouteActive &&
            initialJoinPending && !routeRequestPending && !positionGuidancePaused &&
            trustedLocationReady && pendingUiDestination?.point == currentDestination &&
            routeNavigator.currentRouteApproachTarget(elapsedRealtimeMs()) != null
        val routeReady = runtimeActive && collectionAllowsWork() &&
            isRouteActive && !routePending && !positionGuidancePaused &&
            (latestTmapOnRoute || geometryGrace || warmingReference || (developmentGuidanceStartBypassEnabled && routeNavigator.hasRoute())) &&
            trustedLocationReady &&
            pendingUiDestination?.point == currentDestination
        val locationReason = if (runtimeActive && isRouteActive && !routeRequestPending &&
            locationPermissionReady() && locationServiceEnabled() &&
            pendingDecision == RouteNavigatorUserDecision.LOCATION_RECHECK && routeNavigator.canResumeAfterPositionRecovery())
            "현재 위치를 다시 확인하고 있습니다. 확인되면 안내를 자동으로 이어갑니다."
        else NativeRouteGuidancePresentation.locationReason(
            runtimeActive, trustedLocationReady, routeRequestPending, pendingDecision, backendReason,
            initialJoinPending && !approachReady,
            locationPermissionReady, locationServiceEnabled,
            positionGuidancePaused = { positionGuidancePaused }, routeActive = { isRouteActive },
            directionGuidancePauseReason = { directionGuidancePauseReason },
            startupReadinessBlock = { startupCapabilityDecision?.let { walkSessionReadinessBlockReason(it) } },
        )
        return GuidanceFeatureDisplayInput(
            routeReady || approachReady, routePending && !approachReady, locationReason,
            availableMessageKo = if (approachReady) "가장 가까운 경로 지점의 방향과 거리를 안내하고 있습니다." else null,
        )
    }

