    /** Manual END and automatic arrival share the same final walk teardown. */
    private fun endCurrentWalk(reason: String, detail: String, outputsRetired: Boolean = false) {
        closeGuidanceTouchGuard()
        if (!outputsRetired && arrivalEndingOwner?.isCurrent() == true) {
            routeGuidanceController.retireArrivalForExit()
            return
        }
        walkAreaExitInProgress = true
        transitionWalkSession(WalkSessionEvent.EndRequested)
        persistWalkSessionInterruptionMarker()
        if (outputsRetired) {
            // Only the final speech is new; never retry uncertain native releases here.
            feedbackLifecycleGeneration += 1
            speechOutputController.closeActuator()
            arrivalCleanupCheckpoints?.runStage("arrival_final_route_reset") { resetRouteState() }
        } else {
            walkSessionCleanupController.cancelWalkSessionOutputs(reason)
            stopCameraFallbackSession(updateUi = false)
            stopDepthSession(closeSession = true)
        }
        walkAreaExitInProgress = false
        syncActiveSessionScreenPolicy()
        refreshStartupCapabilityUi()
        updateStatus("보행 종료", detail)
    }

    /** Retire ACTIVE input owners before the separately owned final arrival utterance. */
    private fun beginAutomaticArrivalCompletion(
        token: RouteNavigatorDecisionToken,
    ): RouteGuidanceController.ArrivalCompletion? {
        if (!isActivityForeground || nativeUiPage != NativeUiPage.GUIDANCE ||
            arrivalEndingOwner?.isCurrent() == true || !isWalkSessionRuntimeActive()
        ) return null
        val lifecycle = walkSessionLifecycle
        val activeEpoch = lifecycle.currentRuntimeEpochOrNull() ?: return null
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val actor = currentReporterUserId() ?: return null
        val actorBinding = firstRunOnboardingSnapshot.verifiedActorBinding
        val destination = pendingUiDestination ?: return null
        val pausedEpoch = activeEpoch.copy(recoveryGeneration = activeEpoch.recoveryGeneration + 1L)
        val initialRequestGeneration = routeAcquisitionController.requestGeneration
        var retired = false
        var prepared = false
        var requestGeneration: Int? = null
        fun endingGatewayCurrent(current: GatewaySessionProcessSnapshot): Boolean {
            if (current.storageBlocked || current.deletionRecoveryOnly) return false
            // This lease only ends an already claimed walk; it never admits route or detector work.
            if (!retired) return current.generation == gateway.generation && current.session === gateway.session
            val previous = gateway.session ?: return false
            val next = current.session ?: return false
            if (next.verificationState != GatewaySessionVerificationState.VERIFIED ||
                next.sessionScope != GatewaySessionScope.GENERAL || !next.isUsableFor(actor)
            ) return false
            return (next === previous && current.generation >= gateway.generation) ||
                (current.generation > gateway.generation &&
                    GatewayInRunRenewalPolicy.isRenewedContinuation(previous, next))
        }
        fun endingActorCurrent(current: GatewaySessionProcessSnapshot): Boolean {
            if (!retired) return currentReporterUserId() == actor && reporterUserId == actor
            // Ending this claimed walk does not re-admit device work while renewal rebinds its check.
            if (initialAppPermissionExitRequired || privacyStartupInspectionDestroyed ||
                accountDeletionStateMachine.processingBlocked() ||
                !firstRunOnboardingController.initialized || !priorityUserProfileController.policyInitialized
            ) return false
            val onboarding = firstRunOnboardingSnapshot
            val education = priorityUserOnboardingPolicy
            return onboarding.mayEnterWalk && actorBinding?.value == actor &&
                onboarding.verifiedActorBinding == actorBinding &&
                onboarding.reporterActorBinding?.value == actor &&
                current.restoredFirstRunSnapshot == onboarding && reporterUserId == actor &&
                permissionSessionPolicy.isAuthenticatedFor(actor) && priorityUserOnboardingActorId == actor &&
                education.snapshot().nativeEducationComplete && education.accountBlockReason() == null
        }
        val owner = object : RouteGuidanceController.ArrivalCompletion {
            override fun isCurrent(): Boolean {
                val current = GatewaySessionProcessCoordinator.snapshot()
                val walk = lifecycle.snapshot()
                return !privacyStartupInspectionDestroyed && walkSessionLifecycle === lifecycle &&
                    (walk.epoch == pausedEpoch && walk.state == WalkSessionState.PAUSED ||
                        !prepared && walk.epoch == activeEpoch && walk.state == WalkSessionState.ACTIVE) &&
                    endingGatewayCurrent(current) &&
                    endingActorCurrent(current) &&
                    pendingUiDestination === destination &&
                    (requestGeneration == null || routeAcquisitionController.requestGeneration == requestGeneration)
            }
            override fun finish() {
                if (arrivalEndingOwner !== this || !isCurrent()) return
                val returnHome = nativeUiPage == NativeUiPage.GUIDANCE
                arrivalEndingOwner = null
                endCurrentWalk("arrival_completed", "도착했습니다. 안내를 종료합니다", outputsRetired = true)
                val afterEnd = GatewaySessionProcessCoordinator.snapshot()
                if (!endingActorCurrent(afterEnd) || !endingGatewayCurrent(afterEnd) ||
                    pendingUiDestination !== destination || !returnHome || nativeUiPage != NativeUiPage.GUIDANCE ||
                    lifecycle.snapshot().let { it.epoch.walkSessionId != activeEpoch.walkSessionId ||
                        it.state != WalkSessionState.ENDED }
                ) return
                cancelNativeDestinationSearchAndReturnHome()
                updateNavigationStatus(if (arrivalCleanupBlocksNewWalk()) {
                    "navigation=arrival_ended cleanup_pending=true"
                } else "navigation=arrival_ended")
            }
        }
        arrivalEndingOwner = owner
        var claimFailure: RuntimeException? = null
        val claimed = try {
            routeAcquisitionController.completeDetectedArrival(token) {
                walkRuntimeSafetyCoordinator.retireEpoch(activeEpoch).also { retired = it }
            } != null
        } catch (failure: RuntimeException) {
            claimFailure = failure
            false
        }
        if (!claimed && (!retired || claimFailure == null || !owner.isCurrent() ||
                routeAcquisitionController.requestPending ||
                routeAcquisitionController.requestGeneration !in initialRequestGeneration..initialRequestGeneration + 1)) {
            if (arrivalEndingOwner === owner) arrivalEndingOwner = null
            return null // Veto is non-destructive; a reset's replacement intent is never cleaned up here.
        }
        check(retired)
        val generationBeforeCleanup = routeAcquisitionController.requestGeneration
        if (claimed) requestGeneration = generationBeforeCleanup
        val cleanup = WalkRuntimeStopCleanupCheckpoints()
        arrivalCleanupCheckpoints = cleanup
        cleanup.runStage("arrival_claim_reset") { claimFailure?.let { throw it } }
        fun refreshCleanupUi() {
            runOnUiThread {
                if (arrivalCleanupCheckpoints === cleanup && isActivityForeground &&
                    !privacyStartupInspectionDestroyed && currentReporterUserId() == actor &&
                    lifecycle.snapshot().let { it.epoch.walkSessionId == activeEpoch.walkSessionId &&
                        it.state == WalkSessionState.ENDED }
                ) {
                    refreshStartupCapabilityUi()
                    renderMainUi()
                }
            }
        }
        cleanup.runStage("arrival_recheck") { transitionWalkSession(WalkSessionEvent.RecheckRequested) }
        cleanup.runStage("arrival_marker") { check(persistWalkSessionInterruptionMarker()) }
        cleanup.runStage("arrival_environment") { invalidateOfficialEnvironmentEvidence("arrival_ending") }
        cleanup.runStage("arrival_mounting") { invalidatePhoneMountingEvidence("arrival_ending") }
        walkSessionResumeController.clearResumeState()
        walkSessionCleanupController.cancelWalkSessionOutputsForSafetyStop(
            "arrival_ending", cleanup, onLocationResult = { refreshCleanupUi() },
        )
        cleanup.beginAsync("arrival_camera")
        try {
            stopCameraFallbackSession(updateUi = false,
                onReleased = { if (cleanup.finishAsync("arrival_camera", true)) refreshCleanupUi() },
                onReleaseFailed = { if (cleanup.finishAsync("arrival_camera", false)) refreshCleanupUi() })
        } catch (_: RuntimeException) {
            cleanup.finishAsync("arrival_camera", false)
        }
        cleanup.runStage("arrival_depth") { check(stopDepthSession(closeSession = true)) }
        cleanup.runStage("arrival_route_purge") { check(!routeSnapshotPurgeFailed) }
        if (!claimed) {
            // A partial reset may need this cleanup's one reset, but never another request's generation.
            val afterCleanup = routeAcquisitionController.requestGeneration
            if (afterCleanup !in generationBeforeCleanup..generationBeforeCleanup + 1) {
                if (arrivalEndingOwner === owner) arrivalEndingOwner = null
                return null
            }
            requestGeneration = afterCleanup
        }
        prepared = true
        if (!owner.isCurrent() || routeAcquisitionController.requestPending ||
            (claimed && (isRouteActive || routeNavigator.hasRoute() || navigationRunState.destination != null))
        ) {
            if (arrivalEndingOwner === owner) arrivalEndingOwner = null
            return null
        }
        updateNavigationStatus("navigation=arrival_ending")
        renderMainUi()
        return owner
    }

    private fun cancelNativeGuidanceAndReturnHome() {
        closeGuidanceTouchGuard()
        if (arrivalEndingOwner?.isCurrent() == true) {
            routeGuidanceController.retireArrivalForExit()
            return
        }
        val walk = walkSessionLifecycle.snapshot()
        if (walk.state == WalkSessionState.READY) {
            // Retire admission before speech/camera cleanup can deliver a late callback.
            confirmedStartupCapabilityDecision = null
            startupCapabilityConfirmationPending = false
            startupCapabilityRetryRequiresUserAction = false
            gatewayWalkSessionController.cancelPendingGatewayWalkStart()
        }
        cancelNativePrewalkPreparation(cancelFeatureEntry = true)
        if (walk.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED, WalkSessionState.SAFE_STOP)) {
            executeWalkSessionVoiceAction(WalkSessionVoiceAction.CONFIRM_END, walk.epoch)
        } else {
            cancelActiveRouteRequest()
            resetRouteState()
        }
        cancelNativeDestinationSearchAndReturnHome()
    }


    private fun returnToCurrentInteractionArea() {
        if (isInWalkInteractionArea()) {
            showNativeUiPage(NativeUiPage.GUIDANCE)
            continueNativePrewalkIfReady()
        } else {
            cancelNativePendingFeatureEntry()
            showNativeUiPage(NativeUiPage.HOME)
        }
    }

    private fun cancelNativeVoiceCommandAndReturnHome() {
        if (isInWalkInteractionArea()) {
            cancelVoiceCommandRecognition()
            showNativeUiPage(NativeUiPage.GUIDANCE)
            return
        }
        cancelNativePendingFeatureEntry()
        cancelVoiceCommandRecognition()
        updateGatewayVoiceStatus("음성 명령이 취소되었습니다.")
        showNativeUiPage(NativeUiPage.HOME)
    }

    private fun handleNativeFeatureBackPressed(): Boolean = when (nativeWorkflowController.backAction()) {
        NativeWorkflowController.BackAction.CANCEL_DESTINATION -> { cancelNativeDestinationSearchAndReturnHome(); true }
        NativeWorkflowController.BackAction.CANCEL_GUIDANCE -> { cancelNativeGuidanceAndReturnHome(); true }
        NativeWorkflowController.BackAction.CANCEL_VOICE -> { cancelNativeVoiceCommandAndReturnHome(); true }
        NativeWorkflowController.BackAction.RETURN_HOME -> { returnToCurrentInteractionArea(); true }
        NativeWorkflowController.BackAction.CLOSE_CAMERA_OR_EXIT -> if (cameraScreenVisible) { closeLiveCameraScreen(); true } else false
    }

