    private fun createAccessibilityStatusView(): TextView = TextView(this).apply {
        id = View.generateViewId()
        textSize = 18f
        setTextColor(WS_COLOR_NOTICE_TEXT)
        setBackgroundColor(WS_COLOR_GROUND)
        // Visual status occupies one row; accessibility retains the complete original message.
        setSingleLine(true)
        ellipsize = android.text.TextUtils.TruncateAt.END
        importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_YES
        accessibilityLiveRegion = View.ACCESSIBILITY_LIVE_REGION_POLITE
        accessibilityStatusText = this
    }

    /**
     * 안전 고지는 목적·안전 확인 단계에서 확인 버튼보다 앞에 전문으로 보인다.
     * 확인 뒤에는 큰 글꼴에서 현재 행동을 가리지 않도록 카드를 숨기고, 정책 상수를
     * TalkBack 설명에 그대로 담은 펼침 버튼만 남긴다.
     */
    /**
     * 단계 문장 앞머리("첫 실행 N단계.")는 eyebrow 로 작고 흐리게, 나머지는 제목으로
     * 크고 굵게 보인다. 한 TextView 안에서 처리하므로 text 와 contentDescription 은
     * 전체 문장 그대로 남고 접근성 heading 계약이 유지된다.
     */


    /**
     * 고지 카드 머리글. addView(firstRunOnboardingPresenter.registrationBinding().productPurposeText) 가 오버레이에 직접 있어야 하는 계약
     * 때문에 별도 컨테이너로 감쌀 수 없어 같은 TextView 안에서 Spannable 로 처리한다.
     */
    private fun applyNoticeHeadingStyle(body: String) {
        if (!nativeUiPublication.isPublished(NativeUiPublication.Target.PRODUCT_PURPOSE_TEXT)) return
        val display = "$SAFETY_NOTICE_HEADING\n$body"
        val styled = SpannableString(display)
        val end = SAFETY_NOTICE_HEADING.length
        styled.setSpan(RelativeSizeSpan(0.78f), 0, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        styled.setSpan(StyleSpan(Typeface.BOLD), 0, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        styled.setSpan(
            ForegroundColorSpan(WS_COLOR_EMPHASIS),
            0,
            end,
            Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
        )
        firstRunOnboardingPresenter.registrationBinding().productPurposeText.text = styled
        firstRunOnboardingPresenter.registrationBinding().productPurposeText.contentDescription = display
    }

    private fun documentClauseOrNull(
        source: String,
        label: String,
        stops: List<String>,
    ): String? {
        val start = source.indexOf(label)
        if (start < 0) return null
        val rest = source.substring(start)
        val next = stops
            .mapNotNull { stop -> rest.indexOf(stop, label.length).takeIf { it > 0 } }
            .minOrNull()
        return if (next != null) rest.substring(0, next).trim() else rest.trim()
    }

    /** 승인된 통합 동의 전문에서 해당 항목의 조항만 잘라낸다. 새 문구를 만들지 않는다. */
    private fun consentClauseOrNull(label: String): String? {
        val source = INTEGRATED_CONSENT_DISCLOSURE_KO
        val start = source.indexOf("$label: ")
        if (start < 0) return null
        val rest = source.substring(start)
        val next = Regex("""\s\d\. """).find(rest, 1)?.range?.first
            ?: rest.indexOf(" 각 항목은")
        return if (next > 0) rest.substring(0, next).trim() else rest.trim()
    }

