    private fun startDevelopmentQuickStart() =
        developmentQuickStartController.startDevelopmentQuickStart()

    private fun firstRunOnboardingComplete(): Boolean {
        if (initialAppPermissionExitRequired) return false
        if (developmentGuidanceStartBypassEnabled && shouldShowNativeHome()) return true
        if (developmentQuickStartEnabled) return this@MainActivity.developmentQuickStartController.developmentQuickStartSessionOrNull() != null
        if (
            !firstRunOnboardingController.initialized ||
            !firstRunOnboardingSnapshot.mayEnterWalk ||
            !postLoginDeviceCheckPassesFeatureGate() ||
            accountDeletionStateMachine.processingBlocked()
        ) return false
        return GatewaySessionProcessCoordinator.snapshot().restoredFirstRunSnapshot ==
            firstRunOnboardingSnapshot
    }

    private fun updateFirstRunWaitingDots(active: Boolean) {
        val animationsEnabled = Settings.Global.getFloat(
            contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f,
        ) > 0f
        if (nativeRegistrationComposition.registrationInitialized()) {
            firstRunOnboardingPresenter.updateFirstRunWaitingDots(active, animationsEnabled)
        }
    }

