    }

    private fun updateRuntimeDebugControlsVisibility() {
        if (!::runtimeDebugControls.isInitialized) return
        runtimeDebugControls.visibility = View.GONE
    }

    private fun firstRunDeviceCheckAllowsPreflight(): Boolean =
        firstRunOnboardingController.initialized &&
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
            postLoginDeviceCheckSnapshot.bindingOrNull?.let {
                PostLoginDeviceCheckPolicy.isCurrent(postLoginDeviceCheckSnapshot, it) &&
                    isPostLoginDeviceCheckSessionBindingLive(it)
            } == true

    private fun maybeStartFirstRunDeviceCheckProbes() {
        if (!firstRunDeviceCheckAllowsPreflight()) return
        ensureWalkSessionResourceMonitoring()
        if (
            ::startupCapabilityProbe.isInitialized &&
            !startupCapabilityProbeStarted
        ) {
            startupCapabilityProbeStarted = true
            startupCapabilityProbe.start()
        }
    }

    private fun ensureWalkSessionResourceMonitoring() {
        if (!::walkSessionResourceProbe.isInitialized || walkSessionResourceProbeStarted) return
        walkSessionResourceProbeStarted = true
        walkSessionResourceProbeStarted =
            runCatching {
                walkSessionResourceProbe.start {
                    val resources = walkSessionResourceProbe.snapshot()
                    logWalkSessionResourceDiagnostics("resource_event", resources)
                    observeWalkRuntimeResourceSafety(resources = resources)
                    maybeContinuePostLoginDeviceCheck()
                    refreshStartupCapabilityUi()
                    onPostWalkChargingMaybeChanged()
                }
            }.getOrDefault(false)
    }

    /**
     * S14-43-F1: [AndroidWalkSessionResourceProbe.start] is re-entrant after a failed subscription,
     * but after onboarding it was reached only from activation, which needs READY first. Readiness
     * capture (start, resume and every user retry) therefore retries the subscription itself.
     */
    private fun logWalkSessionResourceDiagnostics(source: String, resources: WalkSessionDeviceResourceSnapshot) {
        if (BuildConfig.DEBUG) runCatching {
            android.util.Log.d("WalkSafeNavigation", "resource_diagnostics source=$source ${resources.resourceDiagnosticsLine()}")
        }
    }

    private fun retryFailedWalkSessionResourceMonitoring() {
        if (!::walkSessionResourceProbe.isInitialized) return
        if (walkSessionResourceProbe.monitoringHealth.state ==
            kr.co.hanium.dreamup.walksafe.device.WalkSessionResourceMonitoringState.SUBSCRIPTION_FAILED
        ) {
            ensureWalkSessionResourceMonitoring()
        }
    }

    private fun resetWalkSessionResourceProbe() {
        if (::walkSessionResourceProbe.isInitialized) privacyStartupResources.releaseOnUiThread(walkSessionResourceProbe)
        walkSessionResourceProbe = privacyStartupResources.acquireOnUiThread(
            { AndroidWalkSessionResourceProbe(this) }, { it.close() },
        )
        walkSessionResourceProbeStarted = false
    }

