    private fun nativeGpsCheckIsCurrent(epoch: WalkRuntimeEpoch): Boolean {
        val request = nativePhoneMountingCheckRequest ?: return false
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val walk = walkSessionLifecycle.snapshot()
        return isActivityForeground && walk.isForeground && walk.epoch == epoch &&
            walk.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED) &&
            request.checkRequest.epoch == epoch && request.actorId == reporterUserId &&
            request.gatewayGeneration == gateway.generation &&
            gateway.session?.actorId == request.actorId && !gateway.storageBlocked &&
            !gateway.deletionRecoveryOnly &&
            (request.destination == null || request.destination == pendingUiDestination)
    }

    private fun requestContinuousGpsForNativeCheck(epoch: WalkRuntimeEpoch) {
        if (!nativeGpsCheckIsCurrent(epoch)) return
        stopOfficialEnvironmentGpsPreflight()
        startLocationUpdatesIfAllowed()
        if (!cameraAnalysisFeaturesEnabled()) {
            officialEnvironmentPreflightController.beginNativeGpsOnlyWait(epoch)
        }
    }

