    private val phoneMountingInteractionController by lazy { createPhoneMountingInteractionController() }
private fun createPhoneMountingInteractionController(): PhoneMountingInteractionController<PositioningMountObservation> = PhoneMountingInteractionController(
    sessionSource = { phoneMountingSession },
    admission = object : PhoneMountingInteractionAdmission {
        override fun developmentBypassEnabled() = developmentGuidanceStartBypassEnabled
        override fun isForeground() = isActivityForeground
        override fun lifecycleAvailable() = ::walkSessionLifecycle.isInitialized
        override fun requireOnboarding(reason: String) = requireFirstRunOnboardingComplete(reason)
        override fun cameraEnabled() = cameraAnalysisFeaturesEnabled()
        override fun snapshot() = walkSessionLifecycle.snapshot()
        override fun isRuntimeEpochCurrent(epoch: WalkRuntimeEpoch) = walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        override fun officialReadiness(epoch: WalkRuntimeEpoch) = officialEnvironmentReadiness(epoch)
        override fun locationFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
        override fun quickStartEnabled() = developmentQuickStartEnabled
        override fun profileAvailable() = activePhoneMountingProfile != null
        override fun onboardingComplete() = firstRunOnboardingComplete()
        override fun profileApprovedForProduction() = activeEnvironmentProfiles?.approvedForProduction
    },
    preflight = object : PhoneMountingInteractionPreflight {
        override fun cameraActive() = officialEnvironmentCameraPreflightActive
        override fun cameraCleanupPending() = officialEnvironmentCameraCleanupPending
        override fun stopCamera(onReleased: () -> Unit) = stopOfficialEnvironmentCameraPreflight(onReleased = onReleased)
        override fun resetReadyGrace() = officialEnvironmentPreflightController.resetReadyGrace()
        override fun resetGuidanceProgress() = prewalkGuidanceProgress.reset()
        override fun startCamera(epoch: WalkRuntimeEpoch) = startOfficialEnvironmentCameraPreflight(epoch)
        override fun requestGps(epoch: WalkRuntimeEpoch, clearExistingEvidence: Boolean) = requestOfficialEnvironmentGpsForCheck(epoch, clearExistingEvidence)
        override fun markFailed() = officialEnvironmentPreflightController.markFailed()
    },
    effects = object : PhoneMountingInteractionEffects {
        override fun updateStatus(title: String, detail: String) = this@MainActivity.updateStatus(title, detail)
        override fun speakInteraction(message: String) { this@MainActivity.speakInteraction(message) }
        override fun refreshReadinessUi() = refreshStartupCapabilityUi()
    },
    view = object : PhoneMountingInteractionView {
        override fun statusPublished() = nativeUiPublication.isPublished(NativeUiPublication.Target.PHONE_MOUNTING_STATUS_TEXT)
        override fun chestPublished() = nativeUiPublication.isPublished(NativeUiPublication.Target.PHONE_MOUNTING_CHEST_CONFIRM_BUTTON)
        override fun necklacePublished() = nativeUiPublication.isPublished(NativeUiPublication.Target.PHONE_MOUNTING_NECKLACE_CONFIRM_BUTTON)
        override fun postFocusEnvironmentConfirmation() {
            firstRunOnboardingPresenter.readinessBinding().officialEnvironmentConfirmButton.post {
                if (firstRunOnboardingPresenter.readinessBinding().officialEnvironmentConfirmButton.isShown) {
                    firstRunOnboardingPresenter.readinessBinding().officialEnvironmentConfirmButton.requestFocus()
                }
            }
        }
        override fun hideStatus() { firstRunOnboardingPresenter.readinessBinding().phoneMountingStatusText.visibility = View.GONE }
        override fun setChestVisible(visible: Boolean) { firstRunOnboardingPresenter.readinessBinding().phoneMountingChestConfirmButton.visibility = if (visible) View.VISIBLE else View.GONE }
        override fun hideNecklace() { firstRunOnboardingPresenter.readinessBinding().phoneMountingNecklaceConfirmButton.visibility = View.GONE }
        override fun applyStatus(message: String) = applyWsStatusText(firstRunOnboardingPresenter.readinessBinding().phoneMountingStatusText, message)
        override fun setStatusDescription(message: String) { firstRunOnboardingPresenter.readinessBinding().phoneMountingStatusText.contentDescription = message }
        override fun statusText() = firstRunOnboardingPresenter.readinessBinding().phoneMountingStatusText.text.toString()
        override fun chestButton(): PhoneMountingButtonView {
            val button = firstRunOnboardingPresenter.readinessBinding().phoneMountingChestConfirmButton
            return object : PhoneMountingButtonView {
                override var enabled: Boolean
                    get() = button.isEnabled
                    set(value) { button.isEnabled = value }
                override var text: CharSequence
                    get() = button.text
                    set(value) { button.text = value }
                override var contentDescription: CharSequence
                    get() = button.contentDescription
                    set(value) { button.contentDescription = value }
            }
        }
    },
)

