    /** Uses the estimator's actual rejection outcome, after the raw callback's owner admission. */
    internal fun recordPositioningGpsObservation(
        snapshot: PositioningSnapshot,
        observedAtElapsedRealtimeMs: Long,
        horizontalAccuracyMeters: Double?,
        elapsedRealtimeMs: () -> Long = SystemClock::elapsedRealtime,
        onPrewalkEvidenceChanged: () -> Unit = ::refreshStartupCapabilityUi,
    ) {
        continuousGpsSession.recordPositioningGpsObservation(snapshot, observedAtElapsedRealtimeMs, horizontalAccuracyMeters, elapsedRealtimeMs, onPrewalkEvidenceChanged)
        val nowMs = elapsedRealtimeMs()
        val mode = snapshot.quality.name
        val reason = snapshot.gnssUpdate?.hardRejectReason?.name
        if (guidanceDiagnosticRuntime != null) {
            val recoveryStage = runtimeGpsQualityGate.gpsRecoveryStage(nowMs).name
            if (guidanceDiagnosticFilter.admit("position", "$mode:$reason:${snapshot.confidence.guidancePaused}:$recoveryStage", nowMs)) {
                recordGuidanceDiagnosticEvent("position_quality", mapOf("mode" to mode, "reason" to reason,
                    "accuracy_m" to horizontalAccuracyMeters, "observed_ms" to observedAtElapsedRealtimeMs,
                    "position_paused" to snapshot.confidence.guidancePaused))
                val raw = runtimeGpsQualityGate.latestRawObservation()
                val firstBad = runtimeGpsQualityGate.gpsFailureStartedAtElapsedRealtimeMs()
                val selected = runtimeGpsQualityGate.current(nowMs)
                val retained = selected?.status == EnvironmentEvidenceStatus.PASS && selected != raw
                recordGuidanceDiagnosticEvent("position_quality", mapOf("stage" to recoveryStage,
                    "source" to "MEASURED_GPS", "mode" to raw?.status?.name, "reason" to raw?.detail,
                    "authorization_kind" to if (retained) "RECENT_RETAINED" else if (selected?.status == EnvironmentEvidenceStatus.PASS) "CURRENT_MEASUREMENT" else "WITHHELD",
                    "retained_age_ms" to if (retained) selected?.observedAtElapsedRealtimeMs?.let { (nowMs - it).coerceAtLeast(0L) } else null,
                    "observed_ms" to raw?.observedAtElapsedRealtimeMs, "grace_onset_ms" to firstBad,
                    "grace_deadline_ms" to runtimeGpsQualityGate.pendingFailureDeadlineElapsedRealtimeMs(),
                    "position_paused" to snapshot.confidence.guidancePaused))
            }
        }
    }

