    @SuppressLint("MissingPermission")
    private fun requestFreshGpsLocation(onResult: (android.location.Location?) -> Unit): () -> Unit {
        if (!::fusedLocationClient.isInitialized || !currentLocationCollectionAllowsWork()) return {}
        val cancellation = com.google.android.gms.tasks.CancellationTokenSource()
        val request = com.google.android.gms.location.CurrentLocationRequest.Builder()
            .setPriority(Priority.PRIORITY_HIGH_ACCURACY)
            .setGranularity(Granularity.GRANULARITY_FINE)
            .setMaxUpdateAgeMillis(0L)
            .setDurationMillis(3_000L)
            .build()
        try {
            fusedLocationClient.getCurrentLocation(request, cancellation.token).addOnCompleteListener { task ->
                onResult(if (task.isSuccessful) task.result else null)
            }
        } catch (_: SecurityException) {
            onResult(null)
        } catch (_: RuntimeException) {
            onResult(null)
        }
        return { cancellation.cancel() }
    }

