    private fun recordOfficialEnvironmentGpsObservationAt(
        epoch: WalkRuntimeEpoch,
        observedAtElapsedRealtimeMs: Long,
        trustedFixAvailable: Boolean?,
        horizontalAccuracyMeters: Double?,
        elapsedRealtimeMs: () -> Long,
        singleOutlierAgainstFreshEstimate: Boolean,
    ) {
        officialEnvironmentEvidenceStore.recordGpsObservation(
            walkSessionLifecycle.snapshot().epoch, epoch, observedAtElapsedRealtimeMs,
