            { activeOfficialEnvironmentProfile }, walkSessionLifecycle::isRuntimeEpochCurrent,
            { continuousGpsSource?.epoch }, { officialEnvironmentPreflightController.separateGpsActive },
            ::isWalkSessionRuntimeActive, singleOutlierAgainstFreshEstimate,
            { currentEpoch, previous, current -> reactToAdmittedRuntimeGpsObservation(currentEpoch, previous, current) },
        )
    }

