    private fun createRawCollectionTransferController(): RawCollectionTransferController = RawCollectionTransferController(
        integratedConsentSession = integratedConsentSession,
        executor = Executors.newSingleThreadExecutor { runnable ->
            Thread(runnable, "walksafe-raw-collection").apply { priority = Thread.NORM_PRIORITY - 1 }
        },
        runtime = object : RawCollectionTransferController.Runtime {
            override fun sensitiveStorageBlocked() = !this@MainActivity::sensitivePrefs.isInitialized || sensitivePrefs.isBlocked()
            override fun isWalkReady() = ::walkSessionLifecycle.isInitialized
            override fun walkSnapshot() = walkSessionLifecycle.snapshot()
            override fun deviceCheckSnapshot() = postLoginDeviceCheckSnapshot
            override fun deletionProcessingBlocked() = accountDeletionStateMachine.processingBlocked()
            override fun activeGatewayWalkLeaseOrNull(epoch: WalkRuntimeEpoch) = gatewayWalkAuthorityController.activeLeaseOrNull(epoch)
            override fun isCharging() = chargingStateProbe.isCharging()
            override fun isForeground() = isActivityForeground
        },
        network = object : RawCollectionTransferController.Network {
            override fun isReady() = ::networkStateProbe.isInitialized
            override fun currentTransport() = networkStateProbe.currentTransport()
            override fun currentBinding() = networkStateProbe.currentIntegratedConsentBinding()
        },
        capture = object : RawCollectionTransferController.Capture {
            override fun detectorAvailable() = primaryDetectorOwner.projection().available
            override fun runtimeIdentity(executedRuntime: AndroidDetectorRuntime?): RawDetectorRuntimeIdentity? {
                val verifiedDetector = primaryDetectorLifecycleController.verifiedIdentity()
                return RawDetectorRuntimeIdentity.ofOrNull(
                    modelArtifactSha256 = verifiedDetector?.modelSetSha256,
                    runtimeConfigSha256 = verifiedDetector?.configSha256,
                    classListSha256 = verifiedDetector?.classListSha256,
                    activeDelegate = executedRuntime?.activeDelegate,
                    delegateFallbackUsed = executedRuntime?.let { it.fallbackUsed || verifiedDetector?.fallbackUsed == true },
                )?.takeIf {
                    // S1617-6-F1: the token must still name the live detector instance and load generation,
                    // so a window after a swap and before its re-verification never pairs the earlier
                    // token's hashes with the new delegate; such a window is rejected instead.
                    verifiedDetector != null &&
                        verifiedDetector.generation == primaryDetectorOwner.projection().loadGeneration &&
                        primaryDetectorLifecycleController.verificationAllows(primaryDetectorOwner.projection().detector, verifiedDetector)
                }
            }
            override fun peekMotion(nowElapsedRealtimeMs: Long) = runCatching { positioningCoordinator.peekUserMotion(nowElapsedRealtimeMs) }.getOrNull()
            override fun thermalThrottledIfReady() = if (::walkSessionResourceProbe.isInitialized) {
                runCatching { walkSessionResourceProbe.snapshot().thermalThrottled }.getOrNull()
            } else null
        },
        log = object : RawCollectionTransferController.Log {
            override fun isReady() = ::fieldSessionLog.isInitialized
            override fun recordEvent(name: String, counters: Map<String, Long>) { fieldSessionLog.recordEvent(name, counters) }
        },
        postWalk = object : RawCollectionTransferController.PostWalk {
            override fun scheduleTransfers() = schedulePostWalkTransfers()
            override fun scheduleWalkInProgressRetry() = schedulePostWalkRetryAfterWalkInProgress()
            override fun scheduleRetryAfter(delayMs: Long) = postWalkTransferController.schedulePostWalkRetryAfter(delayMs)
        },
        wallClockMs = System::currentTimeMillis,
        elapsedRealtimeMs = SystemClock::elapsedRealtime,
    )

