    gateway = gatewayWalkSessionController,
    gatewaySession = { gatewayFieldSession },
    effects = object : WalkTransitionEffects {
        override fun beforePublication(previous: WalkSessionSnapshot, next: WalkSessionSnapshot) {
            if (previous.epoch != next.epoch || previous.state != next.state ||
                previous.isForeground != next.isForeground
            ) invalidateRouteSnapshotResponseLease()
            fenceSpeechOutputStorageBeforeWalkPublication(previous, next)
