        override fun refreshCalibrationDiagnostics() = refreshWalkingCalibrationDiagnostics()
        override fun recordSafetyStopTransition(transition: WalkSessionTransition) { walkStopDelivery.recordSafetyStopTransitionIfOwned(transition) }
