        override fun onEpochChanged() {
            invalidatePermissionRecoveryScopeIfChanged()
            positioningCollectionBinding?.let { binding ->
                if (bindPositioningUserMotionEpoch(binding, SystemClock.elapsedRealtime())) {
                    startPositioningObservationSources()
                }
            }
        }
        override fun updateRouteSnapshotWalkOwnership(transition: WalkSessionTransition) = this@MainActivity.routeArchiveController.updateRouteSnapshotWalkOwnership(transition)
