        override fun stopHandsFreeVoiceService() { this@MainActivity.stopHandsFreeVoiceService() }
        override fun invalidatePendingExplicitReport() = this@MainActivity.invalidatePendingExplicitReport()
        override fun refreshActiveSpeechStorageBinding() { feedbackActuator?.let(::refreshSpeechOutputStorageBinding) }
