    private fun currentGatewayWalkStartReadinessOrNull(
        token: WalkSessionConfirmationToken,
    ): WalkSessionReadinessSnapshot? {
        if (missingRequiredWalkSessionPermissions(WalkSessionAction.START_WALK).isNotEmpty()) return null
        val decision = startupCapabilityDecision ?: return null
        val readiness = captureWalkSessionReadiness(
            decision = decision,
            action = WalkSessionAction.START_WALK,
            recordResourceDiagnostics = true,
        )
        if (BuildConfig.DEBUG && !readiness.isReady) {
            if (guidanceDiagnosticRuntime != null) {
                for (requirement in readiness.plan.requiredRequirements) {
                    val status = readiness.observations.getValue(requirement).status.name
                    if (guidanceDiagnosticFilter.admit("readiness_${requirement.name}", status, SystemClock.elapsedRealtime())) {
                        recordGuidanceDiagnosticEvent("route_terminal", mapOf("stage" to "READINESS",
                            "gate_reason" to requirement.name, "reason" to status, "navigation_allowed" to false))
                    }
                }
            }
            // Only enum states and freshness; account identifiers, positions and raw reasons
            // are excluded from this start-gate diagnostic.
            android.util.Log.d(
                "WalkSafeNavigation",
                "event=GATEWAY_WALK_READINESS_BLOCKED requirements=" +
                    readiness.plan.requiredRequirements.joinToString("+") { requirement ->
                        "$requirement:${readiness.observations.getValue(requirement).status}"
                    } + " stale=" + readiness.staleRequirements.joinToString("+") { it.name }.ifEmpty { "NONE" },
            )
        }
        return readiness.takeIf {
            it.isReady &&
                it.epoch == token.epoch &&
                it.plan.action == token.readiness.plan.action &&
                it.plan.mode == token.readiness.plan.mode
        }
    }




