    internal fun walkSessionPermissionReadinessForObservedSnapshot(
        observed: ObservedPermissionSnapshot,
    ): Pair<WalkSessionReadinessStatus, String> {
        val missing = requiredStartWalkObservedPermissions().filterNot(observed::isGranted)
        return if (missing.isEmpty()) WalkSessionReadinessStatus.READY to ""
        else WalkSessionReadinessStatus.UNAVAILABLE to
            "required_walk_permissions_missing:" + missing.joinToString(",") { it.name.lowercase(Locale.US) }
    }

    private fun captureWalkSessionReadiness(
        decision: WalkSafeStartupCapabilityDecision,
        action: WalkSessionAction,
        recordResourceDiagnostics: Boolean = false,
        checkEntryPermissions: Boolean = true,
    ): WalkSessionReadinessSnapshot {
