    private fun isCameraFallbackAdvisoryOwnerCurrent(
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
        nowMs: Long,
    ): Boolean = cameraEnvironmentOutputsAllowed() && phoneMountingOutputsAllowed &&
            isCameraFallbackLeaseCurrent(
                expectedWalkEpoch,
                fallbackGeneration,
                requireRunning = true,
            ) &&
            lifecycleGeneration == feedbackLifecycleGeneration &&
            currentAndroidLocalTactileTier(nowMs) == AndroidLocalTactileTier.CAMERA_IMU_NON_METRIC

    private fun currentAndroidLocalTactileTier(nowMs: Long): AndroidLocalTactileTier {
        return resolveAndroidLocalTactileTier(currentCameraFallbackAdvisoryGate(nowMs))
    }

    private fun currentCameraFallbackAdvisoryGate(nowMs: Long): NonMetricAdvisoryGate {
        return NonMetricAdvisoryGate(
            cameraPermissionGranted = hasCameraPermission(),
            cameraFallbackRunning = cameraFallbackRunning,
            detectorAvailable = runningDetectorVerifiedForOutput(),
            imuFresh = hasFreshCameraFallbackImu(nowMs),
            tmapRouteActive = hasFreshTmapFallbackContext(nowMs),
        )
    }

    private fun resolveAndroidLocalTactileTier(
        advisoryGate: NonMetricAdvisoryGate,
    ): AndroidLocalTactileTier {
        return AndroidLocalTactileCapability.resolve(
            AndroidLocalTactileCapabilityInput(
                cameraPermissionGranted = advisoryGate.cameraPermissionGranted,
                detectorAvailable = advisoryGate.detectorAvailable,
                arCoreSupported = arCoreSupported,
                depthSupported = depthSupported,
                arSessionRunning = arSessionOwner.observe().session != null,
                cameraFallbackRunning = advisoryGate.cameraFallbackRunning,
                imuFresh = advisoryGate.imuFresh,
                tmapRouteActive = advisoryGate.tmapRouteActive,
            ),
        )
    }

    private fun hasFreshCameraFallbackImu(nowMs: Long): Boolean {
        val orientation = earthOrientationTracker.latest() ?: return false
        val ageMs = nowMs - orientation.observedAtElapsedRealtimeMs
        return ageMs in 0L..CAMERA_FALLBACK_IMU_MAX_AGE_MS &&
            orientation.accuracy != EarthOrientationAccuracy.UNRELIABLE &&
            orientation.deviceToMagneticEnu.isOrthonormal()
    }

    private fun hasFreshTmapFallbackContext(nowMs: Long): Boolean {
        val location = LocationTrustPolicy.freshOrNull(latestTrustedLocation, nowMs) ?: return false
        return isRouteActive &&
            latestTmapOnRoute &&
            !routeAcquisitionController.requestPending &&
            routeNavigator.hasRoute() &&
            location.accuracyM.isFinite()
    }

    /** ARCore and CameraX share one physical detector and never enqueue replacement frames. */
    private fun beginNativeDetectorFlight(
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedDetectorGeneration: Int,
    ): NativeDetectorFlight? {
        return primaryDetectorOwner.beginNativeFlight(expectedWalkEpoch, expectedDetectorGeneration)
    }

    private fun completeNativeDetectorFlight(flight: NativeDetectorFlight) {
        primaryDetectorOwner.completeNativeFlight(flight)
    }

    private fun requestNativeDetectorStall(flight: NativeDetectorFlight) {
        primaryDetectorOwner.requestNativeStall(flight)
    }

    private fun rejectBlockedNativeDetectorWork(): Boolean {
        val walk = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.snapshot() else null
        return primaryDetectorOwner.rejectBlockedNativeWork(walk?.epoch, walk?.state) { epoch ->
            detectorWatchdogHandler.post {
                if (!isDestroyed && ::walkSessionLifecycle.isInitialized &&
                    primaryDetectorOwner.nativeWorkBlocked() &&
                    walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                ) {
                    enterWalkSessionSafetyStopAndCancelOutputs("detector_stalled")
                }
            }
        }
    }

    internal fun rejectUnsafeDetectorAtWalkEntry(
        epoch: WalkRuntimeEpoch,
        state: WalkSessionState,
        watchdog: DetectorStallWatchdog? = null,
        requestSafeStop: (WalkRuntimeEpoch) -> Unit,
    ): Boolean = watchdog?.rejectUnsafeWalkEntry(epoch, state, requestSafeStop) ?: primaryDetectorOwner.rejectUnsafeWalkEntry(epoch, state, requestSafeStop)

    private fun handleNativeDetectorStall(
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedDetectorGeneration: Int,
    ) {
        if (!::walkSessionLifecycle.isInitialized || isDestroyed) return
        val ownsCurrentWalk = primaryDetectorOwner.fenceStalledIfCurrent(expectedDetectorGeneration,
            ownsCurrentWalk = {
                val walk = walkSessionLifecycle.snapshot()
                nativeDetectorStallOwnsWalk(expectedWalkEpoch, expectedDetectorGeneration,
                    walk.epoch, primaryDetectorOwner.projection().frameGeneration, walk.state)
            },
            commit = { frameSynthesisOwner.clearDetectionSnapshot() },
        )
        if (!ownsCurrentWalk) return
        walkRuntimeSafetyCoordinator.observe(
            WalkRuntimeSafetyObservation(
                epoch = expectedWalkEpoch,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                riskTrusted = false,
            ),
        )
        val walk = walkSessionLifecycle.snapshot()
        if (nativeDetectorStallOwnsWalk(
                expectedWalkEpoch, expectedDetectorGeneration + 1,
                walk.epoch, primaryDetectorOwner.projection().frameGeneration, walk.state,
            )
        ) {
            enterWalkSessionSafetyStopAndCancelOutputs("detector_stalled")
        }
        if (::debugBboxOverlay.isInitialized) debugBboxOverlay.clear()
        if (::statusText.isInitialized && !isDestroyed) {
            updateStatus("객체 탐지 지연 · 안전 중지", "검출 기한 800ms를 넘겨 보행 기능을 안전 중지했습니다.")
        }
        closeDetectorAsync()
    }

    private fun tryStartDetectionWork(nowElapsedRealtimeMs: Long): InferencePacingTicket? {
        return primaryDetectorOwner.tryStartWork(nowElapsedRealtimeMs)
    }

    private fun finishDetectionWork(
        ticket: InferencePacingTicket,
        detectorInvoked: Boolean,
        inferenceDurationMs: Long? = null,
        validCompletion: Boolean = false,
    ) {
        primaryDetectorOwner.finishWork(ticket, detectorInvoked, inferenceDurationMs, validCompletion,
            observation = { completedAt ->
                val loadObservation = runtimeLoadObservationSource.latestObservation(completedAt)
                unknownServiceOwner.recordLoadObservation(loadObservation)
                PrimaryCompletionObservation(latestInferenceThermalThrottled, loadObservation)
            },
            onValidCompletion = { endToEnd, staleOrDropped ->
                observeRuntimeInferenceLoad(completion = RuntimeLoadCompletion(endToEnd, staleOrDropped))
            },
        )
    }

    private fun runtimeLoadEnvironmentKey(): String =
        "${primaryRuntimeCalibrationOwner.projection().selectionBinding ?: "unmeasured"}:${primaryRuntimeCalibrationOwner.projection().activeCandidate}:${runtimeLoadFrameScope}:${primaryDetectorOwner.projection().frameGeneration}:${visualGeometryVersion}"

    private fun observeRuntimeInferenceLoad(inputObserved: Boolean = false, completion: RuntimeLoadCompletion? = null) {
        val now = SystemClock.elapsedRealtime()
        val lastNormal = runtimeLoadNormalFrameAtMs
        val normal = primaryDetectorOwner.projection().available && !primaryRuntimeCalibrationOwner.projection().preparing && primaryRuntimeCalibrationOwner.projection().session == null && (!unknownServiceOwnerLazy.isInitialized() || !unknownServiceOwner.hasCalibration) &&
            isActivityForeground && isWalkSessionRuntimeActive() &&
            latestInferenceThermalThrottled == false &&
            runCatching { !getSystemService(android.os.PowerManager::class.java).isPowerSaveMode }.getOrDefault(false) &&
            lastNormal != null && now - lastNormal in 0L..1_000L
        val observation = runtimeLoadMonitor.observe(now, runtimeLoadEnvironmentKey(), normal, inputObserved, completion)
        observeUnknownRuntimeLoad(now, normal, inputObserved, primaryCompletion = completion)
        primaryRuntimeCalibrationOwner.recordPendingDegradationIfNeeded(observation.pendingReason != null) {
            primaryRuntimeCalibrationCoordinator.recordPersistentDegradation(it)
        }
    }

    private fun observeUnknownRuntimeLoad(
        nowMs: Long,
        normal: Boolean,
        inputObserved: Boolean = false,
        primaryCompletion: RuntimeLoadCompletion? = null,
        auxiliaryCompletion: RuntimeLoadCompletion? = null,
    ) { if (unknownServiceOwnerLazy.isInitialized()) unknownServiceOwner.observeLoad(nowMs, normal,
            inputObserved, primaryCompletion, auxiliaryCompletion) }

    private fun adaptiveInferencePacingStatusText(): String {
        val pacing = primaryDetectorOwner.pacingSnapshot()
        val loadDiagnostic = if (BuildConfig.DEBUG) {
            val load = runtimeLoadMonitor.snapshot()
            "primaryTicketWindowMax=${load.lastCompletedWindowMaxEndToEndMs ?: "unknown"}ms "
        } else ""
        return "pacing=${pacing.targetIntervalMs}ms idle=${pacing.cooldownMs}ms " +
            "e2e=${pacing.lastEndToEndMs ?: "unknown"}ms " +
            loadDiagnostic +
            "detectorTotal=${pacing.lastInferenceMs ?: "unknown"}ms " +
            "thermal=${pacing.thermalThrottled ?: "unknown"} " +
            "loadPressure=${pacing.observedLoadPressure} workHeadroom=${pacing.workHeadroomMultiplier} " +
            "overFreshnessBudget=${pacing.overFreshnessBudget ?: "unknown"} reason=${pacing.reason}"
    }

    private val primaryArSubmissionBridge: AndroidPrimaryArSubmissionBridge<ArSessionLease> by lazy {
        AndroidPrimaryArSubmissionBridge(frameStateLock, frameCaptureRequested,
            { primaryDetectorFrameSchedulingOwner }, { frameSynthesisOwner }, { frameGeometry },
            frameRouteEvidence, { primaryArDetectorWorker }, object : PrimaryArSubmissionAuthority {
                override fun obstacleFeatureEnabled() = postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
                override fun ownsFrame(generation: Int, epoch: WalkRuntimeEpoch) = isCurrentFrameGeneration(generation, epoch)
                override fun finishUnsubmitted(ticket: InferencePacingTicket) = finishDetectionWork(ticket, detectorInvoked = false)
            })
    }

/**
     * Runs inference off the GL thread. Published snapshots retain both capture and completion
     * timestamps so a fast partial result cannot be mistaken for a fresh current-frame result.
     */
    private fun scheduleDetectionIfDue(
        recognitionInput: RuntimeRecognitionInput?,
        arLease: ArSessionLease,
        frame: Frame,
        timestampMs: Long,
        capturedAtMs: Long,
        elapsedRealtimeMs: Long,
        capturedDepthSnapshot: DepthFrameSnapshot,
        frameGeneration: Int,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedArSessionGeneration: Long,
