    /** Loading execution services must not depend on opening a performance-check camera. */
    private fun prepareRuntimeServices() {
        if (isDestroyed || primaryDetectorOwner.projection().closing || primaryDetectorLifecycleController.metadata().loadInFlight || !primaryDetectorOwner.projection().available) return
        // The loaded detector already uses the persisted, fixture-checked choice. Do not replace
        // it with an unconditional GPU instance or start a second FastSAM while on the home page.
        if (nativeUiPage == NativeUiPage.GUIDANCE || isWalkSessionRuntimeActive()) startUnknownRuntimeForWalk()
    }

    private fun startUnknownRuntimeForWalk() {
        val source = captureAutomaticUnknownWalkingSource()
        if (source == null && !unknownServiceOwnerLazy.isInitialized()) return
        unknownServiceOwner.startForWalk(source, { reportRuntimeConfig },
            { primaryRuntimeCalibrationOwner.projection().activeCandidate }) {
            if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE))
                RuntimeFeatureScope.CAMERA_TRACKING_METRIC_DEPTH else RuntimeFeatureScope.CAMERA_TRACKING
        }
    }

    /** Resource eligibility does not assert fresh metric/tracking evidence for unknown results. */
    private fun captureAutomaticUnknownWalkingSource(): UnknownWalkingSource? {
        if (!::walkSessionLifecycle.isInitialized) return null
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return null
        val ar = captureRuntimeArObservation()
        val session = ar.session ?: return null
        val provider = ar.provider ?: return null
        if (ar.purpose != ArSessionPurpose.RUNTIME) return null
        val current = {
            !isDestroyed && isActivityForeground && hasCameraPermission() &&
                !primaryDetectorOwner.projection().closing && primaryDetectorOwner.projection().available &&
                !runtimeArSessionCleanupPending() && walkSessionLifecycle.isRuntimeEpochCurrent(epoch) &&
                walkSessionLifecycle.snapshot().isForeground && isWalkSessionRuntimeActive() &&
                isRuntimeArLeaseCurrent(ar)
        }
        return if (current()) UnknownWalkingSource(session, provider, ar.purpose, ar.generation, epoch, current) else null
    }

