    internal fun observeRuntimeRawCameraAssessment(
        assessment: CameraFrameQualityAssessment,
        nowElapsedRealtimeMs: Long = SystemClock.elapsedRealtime(),
    ): Boolean = officialEnvironmentEvidenceStore.observeRuntimeRawCameraAssessment(assessment, nowElapsedRealtimeMs)

    internal fun rawCameraAssessmentAllowsNewOutput(
        assessment: CameraFrameQualityAssessment?,
        expectedEpoch: WalkRuntimeEpoch,
        approvedProfile: ApprovedCameraFrameQualityProfile?,
        nowElapsedRealtimeMs: Long,
    ): Boolean {
        val profile = approvedProfile ?: return false
        val measured = assessment ?: return false
        val observedAt = measured.observedAtElapsedRealtimeMs ?: return false
        return measured.epoch == expectedEpoch && measured.profileId == profile.profileId &&
            measured.maximumEvidenceAgeMs == profile.maximumEvidenceAgeMs &&
            measured.status == EnvironmentEvidenceStatus.PASS && measured.reason == CameraFrameQualityReason.PASSED &&
            observedAt in 0L..nowElapsedRealtimeMs &&
            nowElapsedRealtimeMs - observedAt <= profile.maximumEvidenceAgeMs
    }

    private fun currentRawCameraFrameAllowsNewOutput(nowMs: Long = SystemClock.elapsedRealtime()): Boolean {
        if (!::walkSessionLifecycle.isInitialized) return false
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return false
        return rawCameraAssessmentAllowsNewOutput(
            latestRuntimeRawCameraAssessment,
            epoch,
            activeCameraFrameQualityProfile,
            nowMs,
        )
    }

    private fun currentArCoreQualitativeFeedbackAllowsWork(nowMs: Long): Boolean =
        synchronized(runtimeMetricStateLock) {
            val decision = startupCapabilityDecision
            val metricReady = currentRuntimeMetricOutputAllowsWork()
            val visualGapReady = runtimeMetricActivationSession == null &&
                allowsRuntimeDepthGapProcessing(
                    frameTimestampNanos = runtimeMetricLastFrameTimestampNanos,
                    latestFrameTimestampNanos = runtimeMetricLastFrameTimestampNanos,
                    observedAtElapsedRealtimeMs = nowMs,
                    lastValidFrameAtElapsedRealtimeMs = runtimeMetricLastValidFrameAtMs,
                    tracking = runtimeVisualDepthFrameTracking,
                )
            firstRunOnboardingComplete() &&
                isWalkSessionRuntimeActive() &&
                isActivityForeground &&
                !runtimeArSessionCleanupPending() &&
                cameraEnvironmentOutputsAllowed() &&
                currentRawCameraFrameAllowsNewOutput(nowMs) &&
                phoneMountingOutputsAllowed &&
                hasCameraPermission() &&
                runningDetectorVerifiedForOutput() &&
                arCoreSupported && depthSupported &&
                decision?.allowsMetricDistance() == true &&
                isStartupCapabilityConfirmed() &&
                arSessionOwner.observe().purpose == ArSessionPurpose.RUNTIME &&
                arSessionOwner.observe().session != null && arSessionOwner.observe().provider != null &&
                !cameraFallbackRequested && !cameraFallbackRunning &&
                (metricReady || visualGapReady)
        }

    private fun currentFeedbackDeviceGateAllowsAlerts(): Boolean {
        if (!firstRunOnboardingComplete()) return false
        val decision = startupCapabilityDecision
        val capabilityGate = when {
            decision == null || decision.tier == WalkSafeStartupCapabilityTier.BLOCKED -> false
            decision.allowsMetricDistance() ->
                arSessionOwner.observe().purpose == ArSessionPurpose.RUNTIME &&
                    runtimeMetricOutputAllowed &&
                    currentRuntimeMetricOutputAllowsWork() &&
                    currentRawCameraFrameAllowsNewOutput()
            else ->
                metricDistanceCapabilityOverride == false &&
                    cameraFallbackRequested &&
                    cameraFallbackRunning &&
                    isStartupCapabilityConfirmed()
        }
        return isActivityForeground &&
            isWalkSessionRuntimeActive() &&
            cameraEnvironmentOutputsAllowed() &&
            phoneMountingOutputsAllowed &&
            capabilityGate &&
            hasCameraPermission() &&
            runningDetectorVerifiedForOutput() &&
            this@MainActivity.riskFeedbackComponents.delivery.latestDeviceGateAllowsAlerts()
    }



