    private val currentStateSpeechElapsedRealtime: () -> Long = SystemClock::elapsedRealtime

    /** Read the observation's current meaning without promoting evidence or reading sensor state. */
    private fun currentRuntimeGpsSpeechState(walk: WalkSessionSnapshot?): RuntimeGpsSpeechState? {
        if (walk?.state != WalkSessionState.ACTIVE || walk.readiness?.isReady != true) return null
        val profile = activeOfficialEnvironmentProfile
        val profileId = profile?.profileId
        val evidence = officialEnvironmentGpsEvidence?.takeIf {
            if (profile == null || it.factor != OfficialEnvironmentFactor.GPS_QUALITY ||
                it.epoch != walk.epoch || it.measurementProfileId != profileId
            ) return@takeIf false
            val observedAtMs = it.observedAtElapsedRealtimeMs ?: return@takeIf false
            val maximumAgeMs = it.maximumEvidenceAgeMs ?: return@takeIf false
            if (observedAtMs < 0L || maximumAgeMs < 0L) return@takeIf false
            val nowMs = currentStateSpeechElapsedRealtime()
            nowMs >= 0L && nowMs >= observedAtMs &&
                nowMs - observedAtMs <= minOf(maximumAgeMs, profile.maximumMeasuredEvidenceAgeMs)
        }
        val meaning = when (evidence?.status) {
            EnvironmentEvidenceStatus.PASS -> RuntimeGpsSpeechMeaning.AVAILABLE
            EnvironmentEvidenceStatus.FAIL -> when (evidence.detail) {
                "GPS_ACCURACY_OUTSIDE_APPROVED_RANGE" -> RuntimeGpsSpeechMeaning.ACCURACY_LIMITED
                "TRUSTED_FIX_UNAVAILABLE" -> RuntimeGpsSpeechMeaning.FIX_UNAVAILABLE
                else -> RuntimeGpsSpeechMeaning.WAITING
            }
            else -> RuntimeGpsSpeechMeaning.WAITING
        }
        return RuntimeGpsSpeechState(walk.epoch, profileId, meaning)
    }

    /** Initial capture keeps the original evaluation order before the response is formatted. */
    internal fun captureCurrentStateSpeechContext(): CurrentStateSpeechContext {
        val currentLifecycle = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle else null
        val walk = currentLifecycle?.snapshot()
        return CurrentStateSpeechContext(
            routeRequestGeneration,
            routeNavigator.currentRouteId(),
            routeNavigator.currentTactileRouteProgress(),
            isRouteActive,
            routeAcquisitionController.requestPending,
            positionGuidancePaused,
            directionGuidancePauseReason,
            routeNavigator.pendingDecisionToken(),
            currentRuntimeGpsSpeechState(walk),
            currentDestination,
            pendingUiDestination,
            currentLifecycle,
            walk?.epoch,
            walk?.state,
            walk?.recoveryStage,
            nativeUiPage,
            homeRouteStatusMessage(),
        )
    }

    /** Each projection is read only after preceding lease comparisons pass. */
    internal fun currentStateSpeechReader(): CurrentStateSpeechReader {
        val currentLifecycle = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle else null
        val walk = currentLifecycle?.snapshot()
        return object : CurrentStateSpeechReader {
            override val routeGeneration: Int get() = routeRequestGeneration
            override val routeId: String? get() = routeNavigator.currentRouteId()
            override val routeProgress: TactileActiveRouteProgress get() = routeNavigator.currentTactileRouteProgress()
            override val routeActive: Boolean get() = isRouteActive
            override val routeRequestPending: Boolean get() = routeAcquisitionController.requestPending
            override val positionPaused: Boolean get() = positionGuidancePaused
            override val directionPauseReason: String? get() = directionGuidancePauseReason
            override val decisionToken: RouteNavigatorDecisionToken? get() = routeNavigator.pendingDecisionToken()
            override val runtimeGpsState: RuntimeGpsSpeechState? get() = currentRuntimeGpsSpeechState(walk)
            override val destination: RoutePoint? get() = currentDestination
            override val pendingDestination: DestinationSearchResult? get() = pendingUiDestination
            override val lifecycle: WalkSessionLifecycle? get() = currentLifecycle
            override val epoch: WalkRuntimeEpoch? get() = walk?.epoch
            override val state: WalkSessionState? get() = walk?.state
            override val recoveryStage: WalkSessionRecoveryStage? get() = walk?.recoveryStage
            override val page: Enum<*> get() = nativeUiPage
            override val homeRouteMessage: String get() = homeRouteStatusMessage()
        }
    }

    /** Compatibility entry point; the immutable response lease belongs to the output owner. */
