    }

    internal fun captureCommandSpeechResponseOwner(
        source: CurrentStateSpeechLease? = null,
        responseGeneration: Long = commandSpeechResponseGeneration,
        lifecycleGeneration: Int = feedbackLifecycleGeneration,
    ): CommandSpeechResponseOwner = CommandSpeechResponseOwner(
        speechOutputController.captureCommandSpeechResponseOwner(source, responseGeneration, lifecycleGeneration),
