    internal fun currentStateSpeechMessage(
        walk: WalkSessionSnapshot?,
        ownedStopSummary: String?,
        homeRouteMessage: () -> String,
        guidanceMessage: () -> String,
        pausedMessage: () -> String,
        stoppedMessage: () -> String,
    ): String = when {
        ownedStopSummary != null -> listOfNotNull("보행 안전 중지\n$ownedStopSummary",
            WALK_RESTART_NOTICE_KO.takeIf { walk?.state == WalkSessionState.SAFE_STOP }).joinToString("\n\n")
        walk?.state == WalkSessionState.PAUSED -> listOfNotNull(pausedMessage(), WALK_CONTINUATION_NOTICE_KO, when (walk.recoveryStage) {
            WalkSessionRecoveryStage.RECHECK_REQUIRED -> "필수 기능을 다시 확인한 뒤 보행 재개를 확인합니다."
            WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION ->
                "재검사를 통과했습니다. 안전 제한 안내를 확인한 뒤 재개 여부를 말해 주세요."
            null -> null
        }).joinToString("\n\n")
        walk?.state == WalkSessionState.SAFE_STOP -> "${stoppedMessage()}\n\n$WALK_RESTART_NOTICE_KO"
        walk?.state == WalkSessionState.ENDED -> "보행을 종료했습니다.\n\n${homeRouteMessage()}"
        walk?.state == WalkSessionState.ACTIVE -> guidanceMessage()
        else -> homeRouteMessage()
    }

    private fun speakCurrentState(): Boolean {
        val source = CurrentStateSpeechLease.capture(captureCurrentStateSpeechContext())
        val walk = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.snapshot() else null
        val message = currentStateSpeechMessage(walk, currentOwnedWalkRuntimeSafetyStopStatus()?.userFacingSummary(),
            homeRouteMessage = ::homeRouteStatusMessage,
            guidanceMessage = { nativeGuidanceStatusMessage(currentNativeGuidancePresentation()) },
            pausedMessage = { getString(R.string.walk_safety_paused) },
            stoppedMessage = { getString(R.string.walk_safety_stopped) })
        return speakCommandResponse(message, statusExplanation = true, stateSource = source)
    }

