    internal fun dispatchCrosswalkReference(
        owner: CrosswalkReferenceDeliveryOwner,
        nowElapsedRealtimeMs: () -> Long,
        outputIsCurrent: () -> Boolean,
        routeIsCurrent: (CrosswalkReferenceNotice) -> Boolean,
        completionOwnerIsCurrent: () -> Boolean = { true },
        speak: (CrosswalkReferenceNotice, () -> Boolean, () -> Unit, () -> Unit) -> Boolean,
    ): Boolean = tactileReferenceDelivery.dispatchCrosswalkReference(owner, nowElapsedRealtimeMs, outputIsCurrent, routeIsCurrent, completionOwnerIsCurrent, speak)

    private fun maybeSpeakCrosswalkReference(
        owner: CrosswalkReferenceDeliveryOwner, arLease: ArSessionLease,
        sourceIsCurrent: (() -> Boolean)? = null,
    ) {
        runOnUiThread {
            val ownerIsCurrent = {
                isFeedbackLifecycleCurrent(owner.feedbackLifecycleGeneration) &&
                    isCurrentFrameGeneration(owner.frameGeneration, owner.epoch) &&
                    isArSessionLeaseCurrent(arLease)
            }
            dispatchCrosswalkReference(
                owner = owner,
                nowElapsedRealtimeMs = SystemClock::elapsedRealtime,
                outputIsCurrent = {
                    val nowMs = SystemClock.elapsedRealtime()
                    val safety = walkRuntimeSafetyCoordinator.evaluate(nowMs)
                    (sourceIsCurrent?.invoke() != false) && ownerIsCurrent() && currentArCoreQualitativeFeedbackAllowsWork(nowMs) &&
                        crosswalkReferenceDeviceGateAllowsSpeech(buildDeviceGateState(
                            bestOutput = null,
                            staleReason = null,
                            expectedRuntimeMetricGeneration = owner.arGeneration,
                            qualitativeRuntimeReady = true,
                        )) &&
                        postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE) &&
                        startupCapabilityDecision?.allowsRequirement(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) == true &&
                        safety.epoch == owner.epoch && safety.safetyOutputsAllowed &&
                        !isGuidanceVoiceInputActive()
                },
                routeIsCurrent = { notice ->
                    isRouteActive && !routeAcquisitionController.requestPending && latestTmapOnRoute &&
                        notice.isValidForRoute(routeNavigator.currentRouteId(), routeNavigator.currentTactileRouteProgress())
                },
                completionOwnerIsCurrent = ownerIsCurrent,
                speak = { notice, current, completed, failed ->
                    ensureFeedbackActuator().speakAdvisory(
                        message = notice.message,
                        validUntilMs = notice.validUntilElapsedRealtimeMs,
                        isStillValid = current,
                        onCompleted = completed,
                        onFailed = failed,
                    )
                },
            )
        }
    }

