    private fun trainingOutputCapabilityAllowed(requirement: WalkSafeStartupRequirement): Boolean =
        (educationInteractionController.presentationState().educationInFlight || educationInteractionController.presentationState().practiceInFlight != null) &&
            !isWalkSessionRuntimeActive() && postLoginDeviceCheckPassesFeatureGate() &&
            startupCapabilityDecision?.allowsTrainingOutput(
                requirement,
                if (::startupCapabilityProbe.isInitialized) startupCapabilityProbe.snapshot().vibrationAvailable else null,
            ) == true

    private fun navigationSpeechCapabilityAllowed(): Boolean =
        developmentGuidanceStartBypassEnabled ||
            trainingOutputCapabilityAllowed(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) ||
            startupCapabilityDecision?.allowsRequirement(
                WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
            ) != false

