    /** Native identity, clock and accessibility observations; actual registration/busy checks remain. */
    internal fun isHandsFreeVoiceSpeechOutputActive(
        observeCurrentActuator: () -> AndroidFeedbackActuator?,
        nowElapsedRealtimeMs: () -> Long = { SystemClock.elapsedRealtime() },
        observeScreenReaderActive: () -> Boolean = ::isScreenReaderActive,
    ): Boolean {
        if (speechOutputController.hasPendingCommandResponse() || voiceInputController.gateway.hasPlayer()) return true
        val currentActuator = observeCurrentActuator()
        if (currentActuator?.isAppSpeechActive() == true) return true
        return externalFallbackSpeechOutputActive(nowElapsedRealtimeMs(), observeScreenReaderActive())
    }

