    private val walkSessionCleanupController by lazy { createWalkSessionCleanupController() }
private fun createWalkSessionCleanupController(): WalkSessionCleanupController = WalkSessionCleanupController(
    walk = object : WalkSessionRuntimeAccess {
        override fun available() = ::walkSessionLifecycle.isInitialized
        override fun snapshot() = walkSessionLifecycle.snapshot()
        override fun isRuntimeEpochCurrent(epoch: WalkRuntimeEpoch) = walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        override fun transition(event: WalkSessionEvent) = transitionWalkSession(event)
    },
    authority = gatewayWalkAuthorityController,
    gateway = gatewayWalkSessionController,
    gatewaySession = { gatewayFieldSession },
    resume = walkSessionResumeController,
    debug = BuildConfig.DEBUG,
    admission = object : WalkCleanupAdmission {
        override fun developmentBypassEnabled() = developmentGuidanceStartBypassEnabled
        override fun persistInterruptionMarker() = persistWalkSessionInterruptionMarker()
        override fun invalidateOfficialEnvironment(reason: String) = invalidateOfficialEnvironmentEvidence(reason)
        override fun invalidatePhoneMounting(reason: String) = invalidatePhoneMountingEvidence(reason)
        override fun stopCleanupBlocksNewWalk() = walkRuntimeSafetyCoordinator.stopCleanupBlocksNewWalk || arrivalCleanupBlocksNewWalk()
        override fun stopCleanupExhausted() = walkRuntimeSafetyCoordinator.stopCleanupExhausted || arrivalCleanupFailed()
        override fun showRestartNotice() = showWalkRuntimeSafetyRestartNotice()
        override fun resetTransientStateForNewWalk() = resetWalkTransientStateForNewWalk()
        override fun updateStatus(title: String, detail: String) = this@MainActivity.updateStatus(title, detail)
        override fun updateNavigationStatus(detail: String) = this@MainActivity.updateNavigationStatus(detail)
        override fun refreshReadinessIfInitialized() { if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi() }
        override fun clearStartupState() {
            confirmedStartupCapabilityDecision = null
            startupCapabilityConfirmationPending = false
            startupCapabilityRetryRequiresUserAction = false
            pendingCameraFallbackStart = null
        }
        override fun debug(tag: String, message: String) { android.util.Log.d(tag, message) }
    },
    native = object : WalkCleanupNative {
        override fun stopCameraFallbackSession(updateUi: Boolean, onReleased: (() -> Unit)?, onReleaseFailed: (() -> Unit)?) {
            this@MainActivity.stopCameraFallbackSession(updateUi = updateUi, onReleased = onReleased, onReleaseFailed = onReleaseFailed)
        }
        override fun stopDepthSession(closeSession: Boolean) = this@MainActivity.stopDepthSession(closeSession)
        override fun lastDepthCloseFailure() = arSessionOwner.cleanupFailureOrNull()
        override fun invalidateArRecheck() = invalidateArCoreAvailabilityRecheck()
        override fun stopVoiceService() = stopHandsFreeVoiceService()
        override fun cancelRecognition() = cancelVoiceCommandRecognition()
        override fun stopMountingProbe() { if (::phoneMountingSensorProbe.isInitialized) phoneMountingSensorProbe.stop() }
        override fun moveCameraToCreated() { if (cameraFallbackControllerHolder.isInitialized()) cameraFallbackController.moveTo(Lifecycle.State.CREATED) }
        override fun pauseSurface() {
            if (::surfaceView.isInitialized) {
                syncGlSurfaceRenderMode(forceFrame = true, allowContinuousRendering = false)
                surfaceView.onPause()
            }
        }
        override fun syncScreenPolicy() = syncActiveSessionScreenPolicy()
    },
    navigation = object : WalkCleanupNavigation {
        override fun cancelRequestsForPause() = cancelNavigationRequestsForPause()
        override fun clearDestinationSearchState(cancelled: Boolean) = this@MainActivity.clearDestinationSearchState(cancelled)
        override fun cancelWalkSessionRouteState(reason: String, checkpoints: WalkRuntimeStopCleanupCheckpoints?, cancellation: AndroidNavigationCancellation) =
            this@MainActivity.cancelWalkSessionRouteState(reason, checkpoints, cancellation)
        override fun invalidateFrameState() = invalidateFrameStateForPause()
        override fun stopPositionFieldSession() = stopActivePositionFieldSession()
