private fun performWalkSessionSafetyStopCleanup(
        reason: String,
        persistInterruptionMarker: Boolean,
        checkpoints: WalkRuntimeStopCleanupCheckpoints?,
        onCameraResult: ((Boolean) -> Unit)?,
        onLocationResult: ((Boolean) -> Unit)? = null,
    ): Boolean = walkSessionCleanupController.performWalkSessionSafetyStopCleanup(reason, persistInterruptionMarker, checkpoints, onCameraResult, onLocationResult)

    private fun resetWalkTransientStateForNewWalk() {
        runtimeObstacleDetectionCapabilityOverride = null
        runtimeMetricSession.restoreCapability(if (postLoginCameraDependentChecksDeferred) {
            false
        } else {
            runtimeMetricSession.retainDeviceDepthApiCapability(
                "new_walk", postLoginDeviceCheckSnapshot.bindingOrNull, metricDistanceCapabilityOverride,
            )
        })
        latestStepCount = 0
        routeAcquisitionController.resetProviderFailureCount()
        if (::stepTracker.isInitialized) stepTracker.resetForNewWalk()
        positioningCollectionBinding?.let { binding ->
            // The transition already bound this epoch; the same owner never moves its boundary forward.
            if (bindPositioningUserMotionEpoch(binding, SystemClock.elapsedRealtime())) {
                startPositioningObservationSources()
            }
        }
        if (currentLocationCollectionAllowsWork()) {
            freshTrustedLocationOrNull()
            clearLocationDerivedState()
        } else {
            clearTrustedLocation()
        }
        destinationSearchController.clearPendingVoiceQuery()
        this@MainActivity.riskFeedbackComponents.delivery.resetForNewWalk()
        nonMetricAdvisoryPolicy.reset()
        resetTactileDotReferenceDelivery()
        tactileReferenceDelivery.resetCrosswalk()
        speechOutputController.resetTalkBackForNewWalk()
        lastProgressBeepAtMs = 0L
        latestNavigationState = "navigation=not_started"
    }


    /** Route-state stage shared by ordinary output cancellation and checkpointed safety cleanup. */
    internal fun cancelWalkSessionRouteState(
        reason: String,
        checkpoints: WalkRuntimeStopCleanupCheckpoints?,
        navigationCancellation: AndroidNavigationCancellation,
    ) {
        if (reason == "arrival_ending" && arrivalEndingOwner?.isCurrent() == true &&
            !isRouteActive && !routeAcquisitionController.requestPending && !routeNavigator.hasRoute() &&
            navigationRunState.destination == null
        ) {
            if (checkpoints != null && routeSnapshotPurgeFailed) {
                throw IllegalStateException("route snapshot purge failed during arrival cleanup")
            }
            return
        }
        if (
            ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED
        ) {
            if (reason == "voice_pause" && checkpoints == null) {
                // Keep reset's transient start/stop owners retired while retaining the installed destination.
                invalidateGuidanceStopConfirmation()
                clearPendingExplicitRouteStart()
                installedRouteStartSpeechCoordinator.clear()
                guidancePreparationController.clearPreparationFailureOwner()
                this@MainActivity.routeAcquisitionController.suspendNavigationForRecovery(navigationCancellation)
            } else {
                resetRouteState(purgeRouteSnapshot = false)
            }
        } else {
            resetRouteState()
        }
        if (checkpoints != null && routeSnapshotPurgeFailed) {
            throw IllegalStateException("route snapshot purge failed during safety stop")
        }
    }



    private fun handleRuntimeSpeechCapabilityFailure(
        requirement: WalkSafeStartupRequirement,
        detail: String,
    ) {
        if (requirement != WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) return
        val wasConfirmed = isStartupCapabilityConfirmed()
        if (offlineKoreanTextToSpeechCapabilityOverride == false) return
        offlineKoreanTextToSpeechCapabilityOverride = false
        val activeWalk = ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.snapshot().state == WalkSessionState.ACTIVE
        if (activeWalk) {
            enterWalkSessionSafetyStopAndCancelOutputs("offline_korean_tts_runtime_failure")
        } else {
            refreshStartupCapabilityUi()
        }
        if (wasConfirmed) {
            confirmedStartupCapabilityDecision = startupCapabilityDecision?.takeIf {
                it.mayConfirmAndStart
            }
            refreshStartupCapabilityUi()
        }
        updateStatus(
            "한국어 음성 필요 · 보행 시작/재개 불가",
            if (activeWalk) {
                "$detail 실행 중인 보행 안내를 안전 중지했습니다. 한국어 음성 데이터를 설치한 뒤 기기 점검을 다시 실행하세요."
            } else {
                "$detail 한국어 음성 데이터를 설치하고 기기 점검을 다시 실행하기 전에는 보행 안내를 시작하거나 재개할 수 없습니다."
            },
        )
        // S13-30: through the single TalkBack channel, so an active risk announcement keeps priority.
        if (isScreenReaderActive()) announceTalkBackInteractionAfterVoiceRecognition(detail)
    }

    /**
     * S13-30-F2: once the app TTS failed TalkBack is the only channel, so an INTERACTION message that
     * voice recognition would suppress is delivered after recognition ends instead of being dropped.
     */
    private fun announceTalkBackInteractionAfterVoiceRecognition(message: String): Boolean {
        if (!voiceRecognitionActive) return announceForTalkBack(message, TalkBackAnnouncementPriority.INTERACTION)
        return scheduleTalkBackInteraction(
            message,
            TALKBACK_VOICE_RECOGNITION_RECHECK_MS,
            waitForVoiceRecognitionEnd = true,
        )
    }

