    private fun buildFrozenReportCandidateInput(
        output: TrackedObjectDepth,
        trustedLocation: TrustedLocation,
        modelKey: String,
        sourceModel: String,
        threshold: Float,
        capturedAtMs: Long,
        requestElapsedRealtimeMs: Long,
        nowMs: Long,
        trigger: String,
        reporterId: String,
        gateState: DeviceGateState,
        reportImage: ByteArray?,
        frozenReportCapture: Pair<DetectionSnapshot, TactileSnapshotFrameResult>?,
    ): AndroidReportCandidateInput {
        val coordinateGateStatus = AndroidReportCandidatePolicy.frozenFrameCoordinateGateStatus(
            output, capturedAtMs, reportImage, frozenReportCapture,
            currentGeometryVersion = { visualGeometryVersion },
        )
        return AndroidReportCandidateInput(
            depth = output,
            location = trustedLocation,
            modelKey = modelKey,
            sourceModel = sourceModel,
            runtimeMode = "android",
            modelConfigSha256 = reportModelConfigSha256,
            modelVersion = BuildConfig.VERSION_NAME,
            sourceCommit = BuildConfig.WALKSAFE_SOURCE_COMMIT,
            threshold = threshold,
            capturedAtMs = capturedAtMs,
            requestElapsedRealtimeMs = requestElapsedRealtimeMs,
            trigger = trigger,
            reporterUserId = reporterId,
            traceId = "${output.frameId}-${output.trackId}",
            deviceGateAllowsReports = gateState.reportCandidatesAllowed,
            depthSampleCount = output.validSampleCount,
            depthValidSampleRatio = output.validSampleRatio,
            detectionAgeMs = frozenReportCapture?.first?.capturedAtElapsedRealtimeMs?.let { requestElapsedRealtimeMs - it },
            coordinateGateStatus = coordinateGateStatus,
            heading = latestHeadingDeg,
            apkSha256 = reportApkSha256,
            fallbackUsed = primaryDetectorLifecycleController.metadata().fallbackUsed,
            loadedModelKey = primaryDetectorLifecycleController.metadata().loadedModelKey,
            modelLoadReason = primaryDetectorLifecycleController.metadata().loadReason,
        )
    }


