    private fun startStepTrackingIfAllowed() {
        if (!currentStepTrackingCollectionAllowsWork()) {
            stopStepTracking()
            return
        }
        if (!::stepTracker.isInitialized) return
        if (!hasActivityRecognitionPermission()) {
            updateNavigationStatus("navigation=activity_recognition_permission_missing step_fallback_wait")
            return
        }
        stepTrackingEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        stepTracker.start()
        refreshWalkingCalibrationDiagnostics()
    }

    private fun stopStepTracking() {
        stepTrackingEpoch = null
        val retainedForReportQueueDrain = reportQueueDrainController.hasActiveDrain()
        if (retainedForReportQueueDrain) return
        stopStepTrackingNow()
    }

    private fun stopStepTrackingNow() {
        if (!::stepTracker.isInitialized) return
        val stop = { stepTracker.stop() }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            stop()
        } else {
            runOnUiThread {
                val drainCleared = !reportQueueDrainController.hasActiveDrain()
                if (drainCleared && stepTrackingEpoch == null) stop()
            }
        }
    }

