    /** Called on the sensor thread outside the tracker lock. Keep a BAD before a coalesced GOOD. */
    internal fun onRouteCompassObservation(
        event: RouteCompassObservationEvent,
        trackerCurrent: (RouteCompassObservationEvent) -> Boolean = { earthOrientationTracker.isRouteObservationCurrent(it) },
        sdkSourceCurrent: () -> Boolean = {
            positioningCollectionBinding?.let(::isPositioningCollectionCurrent) == true
        },
        post: (Runnable) -> Unit = { reportCleanupCallbackHandler.post(it); Unit },
        cancelSpeech: () -> Unit = { feedbackActuator?.cancelNavigationSpeech(); Unit },
        invalidateClaim: (RouteCompassObservationEvent) -> Unit = {
            retryCurrentNavigationSpeechForObservation(SystemClock.elapsedRealtime(), it.receivedAtMs,
                it.heading, publishInstruction = false)
        },
        schedule: (RouteCompassObservationEvent, Long?) -> Unit = ::scheduleRouteCompassPresentationUpdate,
    ) =
        routeCompassSession.onRouteCompassObservation(event, trackerCurrent, sdkSourceCurrent, post, cancelSpeech,
            { admitted -> invalidateClaim(admitted); recordDirectionGraceDiagnostic() },
            { admitted, onset -> schedule(admitted, onset); recordDirectionGraceDiagnostic() })

