    private var routeWarmingReassessment: Runnable? = null

    /** One owned poll also covers a missing next GPS callback; it never creates sensor evidence. */
    internal fun scheduleRouteWarmingReassessment(
        deadline: () -> Long? = { positioningSessionController.routeWarmingDeadlineElapsedRealtimeMs },
        reassess: (Long) -> Unit = positioningSessionController::reassessRouteWarming,
        clock: () -> Long = SystemClock::elapsedRealtime,
        current: () -> Boolean = { isActivityForeground && currentLocationCollectionAllowsWork() &&
            positioningCollectionBinding?.let(::isPositioningCollectionCurrent) == true },
        post: (Runnable, Long) -> Unit = { task, delay -> reportCleanupCallbackHandler.postDelayed(task, delay) },
    ) {
        if (routeWarmingReassessment != null || !current()) return
        val due = deadline() ?: return
        val task = object : Runnable {
            override fun run() {
                if (routeWarmingReassessment !== this) return
                routeWarmingReassessment = null
                if (!current() || deadline() == null) return
                reassess(clock())
                scheduleRouteWarmingReassessment(deadline, reassess, clock, current, post)
            }
        }
        routeWarmingReassessment = task
        val remaining = due - clock()
        post(task, if (remaining > 0L) remaining.coerceAtMost(300L) else 1_000L)
    }

    internal fun cancelRouteWarmingReassessment(
        remove: (Runnable) -> Unit = { reportCleanupCallbackHandler.removeCallbacks(it) },
    ) {
        routeWarmingReassessment?.let(remove)
        routeWarmingReassessment = null
    }

