    private fun updateRouteDeviationActions(decision: RouteNavigatorUserDecision?) {
        if (!nativeUiPublication.isPublished(NativeUiPublication.Target.ROUTE_DEVIATION_ACTIONS)) return
        val suspected = decision == RouteNavigatorUserDecision.LOCATION_RECHECK
        val confirmed = decision == RouteNavigatorUserDecision.REROUTE
        val decisionVisible = suspected || confirmed
        nativeScreenPresenter.searchBinding().routeDeviationActions.visibility = if (decisionVisible) View.VISIBLE else View.GONE
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.ROUTE_DEVIATION_SECTION)) {
            nativeScreenPresenter.searchBinding().routeDeviationSection.visibility =
                if (decisionVisible) View.VISIBLE else View.GONE
        }
        nativeScreenPresenter.searchBinding().routeDeviationActions.contentDescription = when {
            confirmed -> "경로 이탈 확정. 새 경로 요청, 위치 다시 확인, 길안내 종료 중 선택"
            suspected -> "위치 재확인이 필요합니다. 위치 다시 확인 선택"
            else -> null
        }
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.OFF_ROUTE_NOTICE_TEXT)) {
            nativeScreenPresenter.searchBinding().offRouteNoticeText.text = when {
                confirmed -> "경로를 벗어났습니다"
                suspected -> "위치를 다시 확인해 주세요"
                else -> ""
            }
        }
        nativeScreenPresenter.searchBinding().routeDeviationNewRouteButton.visibility = if (confirmed) View.VISIBLE else View.GONE
        nativeScreenPresenter.searchBinding().routeDeviationRecheckButton.visibility = if (suspected || confirmed) View.VISIBLE else View.GONE
        nativeScreenPresenter.searchBinding().routeDeviationEndButton.visibility = if (confirmed) View.VISIBLE else View.GONE
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.ROUTE_BUTTON)) {
            nativeScreenPresenter.searchBinding().routeButton.visibility = if (decisionVisible) View.GONE else View.VISIBLE
        }
        if (::destinationResetButton.isInitialized) {
            destinationResetButton.visibility = if (decisionVisible) View.GONE else View.VISIBLE
        }
    }

