    private fun updateFirstRunConsentSummaryUi() {
        if (!nativeUiPublication.isPublished(NativeUiPublication.Target.FIRST_RUN_CONSENT_COUNT_TEXT)) return
        val items = IntegratedConsentItem.entries
        val draftGranted = items.count(integratedConsentController.screenState().draft::isGranted)
        val states = items.map(integratedConsentSession::status)
        val serverSummary = when {
            PurposeConsentSyncState.FAIL_CLOSED in states -> "서버 처리 잠김"
            integratedConsentController.screenState().requestInFlight || states.any {
                it == PurposeConsentSyncState.GRANT_PENDING ||
                    it == PurposeConsentSyncState.WITHDRAWAL_PENDING
            } -> "서버 확인 중"
            PurposeConsentSyncState.WITHDRAWAL_RETRY in states -> "서버 철회 재시도 대기"
            states.all {
                it == PurposeConsentSyncState.CONFIRMED_GRANTED ||
                    it == PurposeConsentSyncState.CONFIRMED_DENIED
            } -> {
                val serverGranted = states.count { it == PurposeConsentSyncState.CONFIRMED_GRANTED }
                "서버 확인 완료: ${items.size}개 중 ${serverGranted}개 허용"
            }
            else -> "서버 미확인"
        }
        firstRunOnboardingPresenter.updateFirstRunConsentSummaryUi(
            FirstRunOnboardingPresenter.ConsentSummaryFacts(items.size, draftGranted, serverSummary),
        )
    }

    private fun captureAccountDeletionUiFacts(): SettingsPrivacyPresenter.DeletionFacts {
        // Keep the original authority reads in Main and in this order.
        val phase = accountDeletionStateMachine.phase()
        val failClosedReason = accountDeletionStateMachine.failureReasonOrNull()
        val durableConfirmationRecovery = accountDeletionStateMachine.durableConfirmationRecoveryRequired()
        val rev0ReauthenticationRequired = accountDeletionRev0RecoveryBindingOrNull() != null
        val durableRecoverySessionReady = (durableConfirmationRecovery || rev0ReauthenticationRequired) &&
            accountDeletionRecoveryGatewaySessionOrNull() != null
        val journal = accountDeletionStateMachine.snapshotOrNull()
        return SettingsPrivacyPresenter.DeletionFacts(
            phase = phase,
            failClosedReason = failClosedReason,
            durableConfirmationRecovery = durableConfirmationRecovery,
            rev0ReauthenticationRequired = rev0ReauthenticationRequired,
            durableRecoverySessionReady = durableRecoverySessionReady,
            retryNeedsPasswordLogin = journal?.lastErrorCode ==
                kr.co.hanium.dreamup.walksafe.network.ACCOUNT_DELETION_REAUTHENTICATION_RETRY_CODE,
            terminalCleanupComplete = accountDeletionTerminalCleanupComplete,
            requestInFlight = accountDeletionRequestInFlight,
            gatewaySessionPresent = gatewayFieldSession != null,
            passwordRecoveryAvailable = accountDeletionPasswordRecoveryBindingOrNull() != null,
            passwordRecoveryInFlight = GatewaySessionProcessCoordinator.snapshot().inFlightOperationId != null,
            journalPresent = journal != null,
            installationKeyPreparation = if (journal != null) accountDeletionPreparationController.installationKeyPreparationState else null,
            deviceVerification = accountDeletionDeviceVerification?.takeIf { (status, _) ->
                journal != null && status.requestId == journal.requestId && status.installationId == journal.installationId &&
                    status.revision == journal.serverRevision && status.clientRevision == journal.clientRevision &&
                    status.accountGeneration == journal.accountGeneration && status.tombstoneId == journal.tombstoneId &&
                    status.requestReceiptSha256 == journal.requestReceiptSha256
            }?.second,
            items = journal?.items?.mapValues { (_, status) -> SettingsPrivacyPresenter.DeletionItemFacts(
                state = status.state, dueAt = status.dueAt, reasonCode = status.reasonCode,
                nextRetryAt = status.nextRetryAt, contactUrl = status.contactUrl,
            ) }.orEmpty(),
        )
    }

