    private fun updateBackendAuthButtonText() {
        if (!nativeUiPublication.isPublished(NativeUiPublication.Target.BACKEND_AUTH_APPLY_BUTTON)) return
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        val requestInFlight = processSnapshot.inFlightOperationId != null
        val deletionRecoverySessionReady =
            processSnapshot.deletionRecoveryOnly &&
                accountDeletionRecoveryGatewaySessionOrNull(
                    processSnapshot.session,
                ) != null
        val deletionRecoverySessionReserved =
            processSnapshot.deletionRecoveryOnly &&
                accountDeletionStateMachine.processingBlocked() &&
                !accountDeletionRecoveryLoginRequired()
        val deletionRecoverySurface =
            accountDeletionRecoveryLoginRequired() ||
                processSnapshot.deletionRecoveryOnly
        val passwordRecoverySurface = accountDeletionPasswordRecoveryBindingOrNull() != null
        val surfaceVisible = (BuildConfig.DEBUG || deletionRecoverySurface) && !passwordRecoverySurface
        settingsPrivacyPresenter.renderGatewayControls(
            surfaceVisible, requestInFlight, deletionRecoverySessionReady,
            deletionRecoverySessionReserved, processSnapshot.deletionRecoveryOnly,
            hasGatewaySession = { gatewayFieldSession != null },
        )
        updatePrivacySectionVisibility()
    }

    private fun nextProgressBeepVolume(current: Int): Int {
        return when {
            current < 20 -> 20
            current < 40 -> 40
            current < 60 -> 60
            else -> 0
        }
    }

    private fun maybePlayProgressBeep(nowMs: Long, offRoute: Boolean, arrived: Boolean) {
        if (!isActivityForeground) return
        if (!isWalkSessionRuntimeActive() || !navigationEnvironmentOutputsAllowed()) return
        if (!progressBeepEnabled || progressBeepVolumePercent <= 0) return
        if (!isRouteActive || offRoute || arrived) return
        if (isGuidanceVoiceInputActive()) return
        // The beep yields to the same app, gateway and TalkBack speech ownership as voice input.
        if (isHandsFreeVoiceSpeechOutputActive()) return
        if (!this@MainActivity.riskFeedbackComponents.delivery.canSpeakNavigation(nowMs)) return
        if (nowMs - lastProgressBeepAtMs < PROGRESS_BEEP_INTERVAL_MS) return
        ensureFeedbackActuator().playProgressBeep(progressBeepVolumePercent)
        lastProgressBeepAtMs = nowMs
    }

