    private fun currentPositionFieldAuthority(): FieldRecordAuthority = FieldRecordAuthority(
        foreground = isActivityForeground,
        walkRuntimeActive = isWalkSessionRuntimeActive(),
        fineLocationGranted = isActivityForeground && isWalkSessionRuntimeActive() &&
            ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED,
        walkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull(),
        gatewayGeneration = GatewaySessionProcessCoordinator.snapshot().generation,
    )

    private fun currentPositionFieldExportAuthenticationOrNull(): FieldExportAuthentication? {
        if (!BuildConfig.DEBUG || positionFieldController.storageBlocked ||
            accountDeletionStateMachine.processingBlocked()
        ) return null
        val actor = currentReporterUserId() ?: return null
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val authenticated = gateway.session ?: return null
        if (gateway.storageBlocked || gateway.deletionRecoveryOnly ||
            authenticated.sessionScope != GatewaySessionScope.GENERAL ||
            authenticated.verificationState != GatewaySessionVerificationState.VERIFIED ||
            !authenticated.isUsableFor(actor) ||
            !permissionSessionPolicy.isAuthenticatedFor(actor)
        ) return null
        return FieldExportAuthentication(
            walkSessionLifecycle.snapshot().epoch.walkSessionId, actor, gateway.generation,
        )
    }

    private fun startPositionFieldSession() {
        if (!BuildConfig.DEBUG) return
        val started = positionFieldController.start(
            PositionFieldStartRequest(
                routeId = positionFieldRouteIdInput.text.toString(),
                exactCoordinateExportConfirmed = positionFieldExactExportCheck.isChecked,
                chestCalibrationConfirmed = positionFieldChestCalibrationCheck.isChecked,
                deviceModel = Build.MODEL,
                androidApi = Build.VERSION.SDK_INT,
            ),
            ::currentPositionFieldAuthority,
        )
        if (!started) return
        positioningSessionController.resetStationaryState()
        ensureEarthOrientationForLocation()
        startLocationUpdatesIfAllowed()
        startStepTrackingIfAllowed()
        updatePositionFieldControls()
        positionFieldController.resetMotionTelemetry()
        syncActiveSessionScreenPolicy()
        speakInteraction("위치 평가 기록을 시작했습니다. 화면을 잠그거나 다른 앱으로 전환하면 기록이 종료됩니다.")
    }

    private fun currentPositionFieldLeaseOrNull(): PositionFieldSessionLease? {
        if (!BuildConfig.DEBUG || positionFieldController.storageBlocked ||
            !positionFieldController.explicitChestConfirmed
        ) return null
        return positionFieldController.currentLeaseOrNull(currentPositionFieldAuthority())
    }

    private fun stopActivePositionFieldSession(): Boolean = positionFieldController.stop()

    private fun purgeAndRotatePositionFieldScope(): Boolean = positionFieldController.purgeAndRotate()

    private fun surfacePositionFieldStorageFailure(message: String) {
        if (::statusText.isInitialized) {
            updateStatus("위치 평가 기록 저장소 오류", message)
        }
        if (::walkLastResultText.isInitialized) speakInteraction(message)
    }

    private fun exportLastPositionFieldSession() {
        if (!BuildConfig.DEBUG) return
        val sessionId = positionFieldController.beginExport(
            walkEpoch = { walkSessionLifecycle.currentRuntimeEpochOrNull() },
            exportAuthentication = ::currentPositionFieldExportAuthenticationOrNull,
        ) ?: return
        val intent = Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
            addCategory(Intent.CATEGORY_OPENABLE)
            type = "application/x-ndjson"
            putExtra(Intent.EXTRA_TITLE, "walksafe-position-${sessionId}.jsonl")
        }
        runCatching { startActivityForResult(intent, REQUEST_POSITION_FIELD_EXPORT) }
            .onFailure { positionFieldController.exportLaunchFailed() }
    }

    private fun handlePositionFieldExportResult(resultCode: Int, data: Intent?) {
        val destination = data?.data?.let { AndroidPositionFieldExportDestination(contentResolver, it) }
        positionFieldController.handleExportResult(
            accepted = resultCode == Activity.RESULT_OK,
            destination = destination,
            exportAuthentication = ::currentPositionFieldExportAuthenticationOrNull,
        )
    }

    private fun markPositionFieldCheckpoint() {
        if (currentPositionFieldLeaseOrNull() == null) return
        val nowMs = SystemClock.elapsedRealtime()
        // Re-check the sensor owner's expiry rather than using the cached UI state alone.
        applyUserMotionState(positioningCoordinator.currentUserMotion(nowMs))
        positionFieldController.markCheckpoint(
            currentPositionFieldAuthority(), latestPositionStationaryState, latestPositionStationarySinceMs,
        )
    }

