    private fun toggleFieldSessionLog() {
        if (!BuildConfig.DEBUG) return
        if (fieldSessionLog.isActive()) {
            fieldSessionLog.stop()
            this@MainActivity.riskFeedbackComponents.delivery.clearRejectionFieldSession()
            resetFeedbackOutputRejectionDiagnostics()
            // S1617-36: approved statistics only; the encrypted archive stays unanalysable on the host.
            fieldSessionLog.lastSessionStatsSummary()?.let { updateStatus("현장 로그 요약", it.displayText()) }
            if (!isRouteActive && !navigationPermissionsRequestedForRoute && !navigationPermissionsRequestedForReport) {
                stopLocationUpdates()
                stopStepTracking()
            }
        } else {
            if (permissionRecoveryGate.blocksAutomaticResourceStart) {
                updateStatus(
                    "현장 로그 시작 보류",
                    "권한과 필수 기능 전체 상태를 다시 확인하고 명시적으로 재개한 뒤 시작하세요.",
                )
                updatePermissionRecoveryUi()
                return
            }
            if (!isWalkSessionRuntimeActive()) {
                updateStatus("현장 로그 시작 보류", "보행 안내가 활성 상태일 때만 새 현장 로그를 시작할 수 있습니다.")
                return
            }
            val missing = WalkStartPermissionPolicy.missing(
                observed = currentObservedPermissionSnapshot(),
                activityRecognitionRequired = Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q,
            )
            if (missing.isNotEmpty()) {
                enterPermissionRecoveryBarrier(missing, "field_session_start")
                return
            }
            GatewayCapacityProcessState.fenceSessionGeneration(
                GatewaySessionProcessCoordinator.snapshot().generation,
            )
            val capacityAdmission = GatewayCapacityProcessState.admission()
            if (!capacityAdmission.newRawCollectionSessionAllowed) {
                updateStatus(
                    "현장 로그 시작 보류",
                    "서버 용량 상태를 확인한 뒤 새 원본 수집 세션을 시작할 수 있습니다.",
                )
                fieldSessionLog.recordEvent(
                    "field_log_start_blocked_gateway_capacity",
                    mapOf(
                        "availability" to capacityAdmission.availability.name,
                        "version" to capacityAdmission.snapshot?.version,
                    ),
                )
                return
            }
            this@MainActivity.riskFeedbackComponents.delivery.setRejectionFieldSession(fieldSessionLog.startAfterUserConfirmation())
            resetFeedbackOutputRejectionDiagnostics()
            fieldSessionLog.recordEvent(
                "field_log_enabled",
                mapOf(
                    "camera_permission" to hasCameraPermission(),
                    "location_permission" to hasLocationPermission(),
                    "activity_permission" to hasActivityRecognitionPermission(),
                    "audio_permission" to hasRecordAudioPermission(),
                ),
            )
            // S09-56: a profile loaded before this session started is still visible in its log.
            latestPedestrianProfileLoadStatus?.let { status ->
                fieldSessionLog.recordEvent("pedestrian_profile_loaded", mapOf("result" to status))
            }
            if (
                startupCapabilityDecision?.allowsRequirement(
                    WalkSafeStartupRequirement.GPS,
                ) == true
            ) {
                this@MainActivity.permissionFlowController.ensureNavigationPermissions(requireActivityRecognition = true)
            }
            startNavigationServicesIfNeeded()
        }
        syncActiveSessionScreenPolicy()
        if (::startupCapabilityProbe.isInitialized) {
            refreshStartupCapabilityUi()
        } else {
            updateFieldSessionLogButton()
        }
    }

    /** Active route/risk work keeps the foreground window awake; background collection stays disabled. */
    private fun syncActiveSessionScreenPolicy() {
        if (!::surfaceView.isInitialized) return
        val walkSessionScreenVisible = ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.snapshot().state in setOf(
                WalkSessionState.ACTIVE,
                WalkSessionState.PAUSED,
            )
        if (
            ::controlsScroll.isInitialized &&
            ::walkSafetyOverlay.isInitialized &&
            ::walkSafetyScroll.isInitialized
        ) {
            controlsScroll.visibility = if (cameraScreenVisible) View.GONE else View.VISIBLE
            walkSafetyOverlay.visibility = View.GONE
            walkSafetyScroll.visibility = View.GONE
            if (walkSessionScreenVisible && nativeUiPublication.isPublished(NativeUiPublication.Target.FIRST_RUN_ONBOARDING_CONTROLS)) {
                updateFirstRunOnboardingUi()
            }
        }
        if (nativeUiPublication.isPublished(NativeUiPublication.Target.VOICE_REPORT_BUTTON) && ::walkSafetyVoiceButton.isInitialized) {
            updateVoiceCommandButton()
        }
        updateWalkSafetySummary()
        val activeForegroundSession = isWalkSessionRuntimeActive() &&
            (arSessionOwner.observe().session != null || cameraFallbackRunning || isRouteActive || isFieldSessionActive() ||
                positionFieldController.explicitChestConfirmed)
        if (activeForegroundSession) {
            window?.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        } else {
            window?.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        }
        renderMainUi()
    }

    private fun updateWalkSafetySummary() {
        if (!::safetySummaryText.isInitialized || !::walkSessionLifecycle.isInitialized) return
        val walk = walkSessionLifecycle.snapshot()
        val resourceReasons = walk.readiness?.observations
            ?.get(WalkSessionReadinessRequirement.DEVICE_RESOURCES)
            ?.reason?.split(",").orEmpty()
        val performanceNotice = when {
            "thermal_throttled" in resourceReasons -> "발열로 성능 제한 중입니다."
            "thermal_throttle_state_pending" in resourceReasons ->
                "발열에 따른 성능 제한 여부 확인 중입니다."
            else -> ""
        }
        val summary = when (walk.state) {
            WalkSessionState.ACTIVE -> listOf(getString(R.string.walk_safety_active), performanceNotice)
                .filter(String::isNotBlank).joinToString("\n")
            WalkSessionState.PAUSED -> getString(R.string.walk_safety_paused)
            WalkSessionState.SAFE_STOP -> currentOwnedWalkRuntimeSafetyStopStatus()?.let {
                it.userFacingSummary()
            } ?: getString(R.string.walk_safety_stopped)
            else -> listOf(getString(R.string.walk_safety_preparing), performanceNotice)
                .filter(String::isNotBlank).joinToString("\n")
        }
        if (safetySummaryText.text.toString() == summary) return
        safetySummaryText.text = summary
        safetySummaryText.contentDescription = summary
    }

    private fun isFieldSessionActive(): Boolean {
        return ::fieldSessionLog.isInitialized && fieldSessionLog.isActive()
    }

    private fun updateFieldSessionLogButton() {
        if (!::fieldSessionLogButton.isInitialized) return
        if (!BuildConfig.DEBUG) {
            fieldSessionLogButton.visibility = View.GONE
            fieldSessionLogButton.isEnabled = false
            return
        }
        val sessionId = fieldSessionLog.activeSessionId()
        if (this@MainActivity.riskFeedbackComponents.delivery.rejectionFieldSessionId() != sessionId) {
            this@MainActivity.riskFeedbackComponents.delivery.setRejectionFieldSession(sessionId)
            resetFeedbackOutputRejectionDiagnostics()
        }
        val active = sessionId != null
        fieldSessionLogButton.visibility = if (active || isStartupCapabilityConfirmed()) {
            View.VISIBLE
        } else {
            View.GONE
        }
        fieldSessionLogButton.text = if (active) "현장 로그 종료" else "현장 로그 시작"
        fieldSessionLogButton.contentDescription = if (active) {
            "현장 테스트 메타데이터 로그 기록 중, 눌러서 종료"
        } else {
            "현장 테스트 메타데이터 로그 시작"
        }
        fieldSessionLogButton.isEnabled = true
    }

