    private data class FirstRunAsyncLease(
        val epoch: Long,
        val revision: Long,
        val stage: FirstRunOnboardingStage,
    )

    internal enum class ArSessionPurpose {
        NONE,
        PREFLIGHT,
        RUNTIME,
    }



    internal data class RuntimeArObservation(
        val session: Any?,
        val provider: Any?,
        val purpose: ArSessionPurpose,
        val generation: Long,
    ) {
        fun matchesLease(lease: RuntimeArObservation): Boolean =
            lease.session != null && lease.provider != null &&
                session === lease.session && provider === lease.provider &&
                purpose == lease.purpose && generation == lease.generation

        fun hasPurposeAndGeneration(expectedPurpose: ArSessionPurpose, expectedGeneration: Long): Boolean =
            purpose == expectedPurpose && generation == expectedGeneration

        fun allowsMetricLease(expectedGeneration: Long?): Boolean =
            purpose == ArSessionPurpose.RUNTIME &&
                (expectedGeneration == null || generation == expectedGeneration) &&
                session != null && provider != null
    }

    private data class ArSessionLease(
        val session: Session,
        val provider: ArCoreFrameProvider,
        val purpose: ArSessionPurpose,
        val generation: Long,
    )




    internal enum class TalkBackAnnouncementPriority {
        RISK,
        INTERACTION,
        NAVIGATION,
        ADVISORY,
    }

    private data class GatewayFailureUiGuard(
        val generation: Long,
        val expectedAuthenticationFailure: Boolean,
    )



}

internal fun nativeDetectorStallOwnsWalk(
    expectedEpoch: WalkRuntimeEpoch,
    expectedDetectorGeneration: Int,
    currentEpoch: WalkRuntimeEpoch,
    currentDetectorGeneration: Int,
    currentState: WalkSessionState,
): Boolean =
    expectedEpoch == currentEpoch &&
        expectedDetectorGeneration == currentDetectorGeneration &&
        currentState in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)

private class CameraFallbackLifecycleOwner : LifecycleOwner {
    private val registry = LifecycleRegistry(this)

    override val lifecycle: Lifecycle
        get() = registry

    fun moveTo(state: Lifecycle.State) {
        registry.currentState = state
    }
}
